INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('عامر بن الطفيل', 'مؤلف', 'عامِر بن الطُّفَيْل (٧٠ ق هـ - ١١ هـ = ٥٥٤ - ٦٣٢ م)
عامر بن الطفيل بن مالك بن جعفر العامري، من بني عامر بن صعصعة
• فارس قومه، وأحد فتاك العرب وشعرائهم وساداتهم في الجاهلية. كنيته أبو عليّ. ولد ونشأ بنجد.
• وكان يأمر مناديا في (عكاظ) ينادي: هل من راجل فنحمله؟ أو جائع فنطعمه؟ أو خائف فنؤمنه؟
• وخاض المعارك الكثيرة، وأدرك الاسلام شيخا، فوفد على رسول الله صلّى الله عليه وسلم وهو في المدينة، بعد فتح مكة، يريد الغدر به، فلم يجرؤ عليه. فدعاه إلى الإسلام، فاشترط أن يجعل له نصف ثمار المدينة، وأن يجعله ولي الأمر من بعده، فرده، فعاد حنقا، وسمعه أحدهم يقول: لأملأنها خيلا جردا ورجالا مردا ولأربطن بكل نخلة فرسا! فمات في طريقه قبل أن يبلغ قومه.
• وكان أعور أصيبت عينه في إحدى وقائعه، عقيما لا يولد له.
• وهو ابن عم لبيد الشاعر.
• أخباره كثيرة متفرقة.
• وله (ديوان شعر - ط) مما رواه أبو بكر محمد بن القاسم الأنباري.
• وفي البيان والتبيين: وقف جبار ابن سليمان الكلابي على قبر عامر فقال: كان والله لا يضل حتى يضل النجم، ولا يعطش حتى يعطش البعير، ولا يهاب حتى يهاب السيل، وكان والله خير ما يكون حين لا تظن نفس بنفس خيرا (١).
_________
(١) خزانة الأدب للبغدادي ١: ٤٧١ - ٤٧٤ ورغبة الآمل ٢: ١٧٦ ثم ٨: ١٦٥ و ٢٤٣ والتبريزي ١: ٨١ ثم ٢: ١٢١ والشعور بالعور - خ. والشعر والشعراء ١١٨ والإصابة، ت ٦٥٥٠ والبيان والتبيين ١: ٣٢ والمحبر ٢٣٤ و ٤٧٢ ومعجم المطبوعات ١٢٦٠ والعقد، طبعة اللجنة، ٢: ١٧ ثم ٣: ١٢٨ و ٤١٠ وفي ثمار القلوب ٧٨ أنه كان يلقب بملاعب الأسنة، وأما عامر بن مالك بن جعفر، المعروف بملاعب الأسنة، فلقبه (ملاعب الرماح) وقد أشرت إلى هذا في ترجمته.
نقلا عن: «الأعلام» للزركلي', NULL, '0554-01-01', '0632-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('لبيد بن ربيعة', 'مؤلف', 'لَبِيد العَامِري (٠٠٠ - ٤١ هـ = ٠٠٠ - ٦٦١ م)
لَبِيد بن ربيعة بن مالك، أبو عقيل العامري: أحد الشعراء الفرسان الأشراف في الجاهلية.
من أهل عالية نجد. أدرك الإسلام، ووفد على النبي صلّى الله عليه وآله ويعد من الصحابة، ومن المؤلفة قلوبهم. وترك الشعر، فلم يقل في الإسلام إلا بيتا واحدا، قيل: هو
ما عاتب المرء الكريم كنفسه … والمرء يصلحه الجليس الصالح
وسكن الكوفة، وعاش عمرا طويلا. وهو أحد أصحاب المعلقات. ومطلع معلقته:
عفت الديار محلها فمقامها … بمنى، تأبد غولها فرجامها
وكان كريما: نذر أن لا تهب الصبا إلا نحر وأطعم.
جُمع بعض شعره في «ديوان - ط» صغير، ترجم إلى الألمانية
نقلا عن: الأعلام للزركلي', NULL, '0041-01-01', '0661-01-01', NOW(), NOW())
