INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('آدم بن أبى إياس', 'مؤلف', 'الاسم: آدم بن أبى إياس: عبد الرحمن ويقال: ناهية بن محمد بن شعيب الخراسانى المروذى أبو الحسن العسقلانى، مولى بنى تيم أو تميم
الطبقة: ٩: من صغار أتباع التابعين
الوفاة: ٢٢١ هـ بـ عسقلان
روى له: خ خد ت س ق (البخاري - أبو داود في الناسخ والمنسوخ - الترمذي - النسائي - ابن ماجه)
