INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('العلاء بن موسى الباهلي', 'مؤلف', 'العلاء بن موسى بن عطية البغدادي، أبو الجهم الباهلي، صاحب الليث.
تاريخ الوفاة: ٢٢٨ هـ.
شيوخه:
الليث بن سعد.
سفيان بن عيينة.
عبد العزيز بن الماجشون.
عبد القدوس بن حبيب.
سوار بن مصعب.
والهيثم بن عدي.
تلاميذه:
علي بن الجعد الجوهري.
أبو داود السجستاني، ( تفرد ابن حجر بهذا القول )
إسحاق بن إبراهيم بن سنين.
أحمد بن علي الأبار.
عبد الله بن محمد البغوي.
مكانته:
قال الذهبي: الشيخ المحدث الثقة، ذكرته لشهرته، همام من المعمرين، كان من أبناء الثمانين، روي ذلك الجزء العالي.
ذكره أبو احمد الحاكم في «الكنى» فيمن لم يسم، ولم يذكر فيه شيئا.
وقال أبو زرعة الرازي: واه.
وقال ابن عدي: شيخ مجهول، لا يعرف له اسم، وخبره منكر.
وقال ابن عبد البر: لا يصح حديثه.
قال الخطيب: كان صدوقا.
مصنفاته:
«نسخة أبي الجهم»، رواية أبي القاسم البغوي.
مصادر الترجمة:
تاريخ بغداد.
سير الأعلام.
معجم المحدثين.
ذيل التقييد.
تعجيل المنفعة.
كشف الظنون.
(نقلا عن موقع جامع الحديث)', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('نعيم بن حماد المروزي', 'مؤلف', 'نعيم بن حماد ( ٠٠٠ - ٢٢٨ هـ = ٠٠٠ - ٨٤٣ م)
نعيم بن حماد بن معاوية بن الحارث الخزاعي المروزي، أبو عبد الله: أول من جمع «المسند» في الحديث.
كان من أعلم الناس بالفرائض.
ولد في مرو الشاهجان، وأقام مدة في العراق والحجاز يطلب الحديث.
ثم سكن مصر، ولم يزل فيها إلى أن حمل إلى العراق في خلافة المعتصم، وسئل عن القرآن: أمخلوق هو ؟ فأبى أن يجيب، فحبس في سامرا، ومات في سجنه.
من كتبه «الفتن والملاحم - خ» [ثم طُبع] منه نسخة في جامعة «الرياض» الرقم ٢١٦ كتب سنة ٦٨٧ هـ
