INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('سريج بن يونس', 'مؤلف', 'سريج بن يونس بن إبراهيم، أبو الحارث البغدادي، مروزي الأصل.
تاريخ الوفاة: ٢٣٥ هـ.
(شيوخه)
إسماعيل بن جعفر.
إسماعيل ابن علية.
بشر بن المفضل.
سفيان بن عيينة.
عبد الله بن رجاء المكي.
عبد الرحمن بن مهدي.
عبد الصمد بن عبد الوارث.
الفرج بن فضالة.
هشيم بن بشير.
وكيع بن الجراح.
الوليد بن مسلم.
يحيى بن زكريا بن أبي زائدة.
يزيد بن هارون.
(تلاميذه)
مسلم بن الحجاج النيسابوري.
أبو بكر أحمد بن علي بن سعيد المروزي القاضي.
إسحاق بن إبراهيم بن سنين الختلي.
بقي بن مخلد الأندلسي.
الحارث بن محمد بن أبي أسامة.
عبد الله بن أحمد بن حنبل.
عبد الله بن محمد بن أبي الدنيا.
عبد الله بن محمد البغوي.
أبو زرعة عبيد الله بن عبد الكريم الرازي.
أبو حاتم محمد بن إدريس الرازي.
موسى بن هارون بن عبد الله الحمال.
(مكانته)
قال الذهبي: الإمام القدوة الحافظ، من الأئمة العابدين، له أحوال، وكان رأسا في السنة.
وقال النديم: من جِلة المحدثين وثقاتهم والفقهاء والقراء.
وقال صالح جزرة: ثقة جدا عابد.
قال الميموني عن أحمد بن حنبل: رجل صالح صاحب خير ما علمت.
وقال أبو داود عن أحمد: ليس به بأس.
وقال أبو داود في موضع آخر: ثقة سمعت أحمد يثني عليه.
وقال ابن أبي خيثمة وغيره: ليس به بأس، كذا قال يعقوب بن شيبة عن ابن معين، وزاد: وهو كيس.
وقال الغلابي عن ابن معين: سريج بن النعمان ثقة، وسريج بن يونس أفضل منه.
وقال أبو حاتم: صدوق.
وقال النسائي: ليس به بأس.
وقال محمد بن عوف: قال لي أحمد: اُكتب عنه.
وقال عنه إسحاق بن إبراهيم الختلي: الشيخ الصالح الصدوق.
وقال ابن سعد، وابن قانع: ثقة ثبت.
وذكره ابن حبان في «الثقات».
وعن سهل بن علي الدوري قال: سمعت سريج بن يونس يقول: خرجت يوم الجمعة أريد مسجد الجامع، فلما دخلت القنطرة رأيت سمكتين في سفود في دكان شواء، فاشتهيتهما بقلبي للصبيان ولم أتكلم به، فلما قضيت الجمعة ورجعت رأيتهما وقد أخرجهما الشَّوَّاءُ، فتمنيتهما بقلبي، فلما دخلت البيت ما استقررت حينا، فإذا داقٌّ يدق الباب، فقلت: من هذا، وخرجت، فإذا رجل معه طبق عليه السمكتين وبقْل وخلٌّ ورُطَبٌ كثير، فقال لي: يا أبا الحارث، كُلْ هذا، فأخذته منه.
قال ابن الجعد: حدثني بقَّال لسريج بن يونس فقال: جاءني سريج بن يونس ليلا وقد ولد له مولود، فأعطاني ثلاثة دراهم فقال لي: أعطني بدرهم عسلا وبدرهم سمنا وبدرهم سَوِيقا، ولم يكن عندي، وكنت قد عزلت الظروف لأبكر فأشتري، فقلت: ما عندي شيء؛ قد عزلت الظروف لأبكر فأشتري، فقال لي: اُنظر قليلا، أيش ما كان، اِمسح البراني، فجئت فوجدت البراني والجراب ملأي، فأعطيته شيئا كثيرا، فقال لي: ما هذا، أليس قلتَ أن ما عندي شيء؟! قال: قلت: خذه واسكت، فقال: ما آخذُه أو تَصدُقني! فخبَّرته بالقصة، فقال لي: لا تحدث به أحدا ما دمتُ حيا.
(مصنفاته):
«التفسير».
«الناسخ والمنسوخ».
«القراءات».
«السنن» في الفقه.
مصادر الترجمة:
الفهرست.
تاريخ بغداد.
تهذيب الكمال.
سير الأعلام.
تهذيب التهذيب.
(نقلا عن: موقع جامع الحديث)', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


