    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('بشر بن مطر الدقاق', 'مؤلف', 'جاء في تاريخ بغداد:
بشر بن مطر بن ثابت أبو أحمد الدقاق الواسطي
- نزل سر من رأى، وحدث بها عن: سفيان بن عيينة، ومحمد بن يزيد الواسطي، ويزيد بن هارون، وإسحاق الأزرق روى عنه: الحسن بن علي المعمري، ويحيى بن صاعد، وإسماعيل بن العباس الوراق، ويوسف بن يعقوب بن إسحاق بن البهلول، ومحمد بن مخلد، ومحمد بن جعفر المطيري، وأبو العباس الأثرم، وغيرهم
- وقال ابن أبي حاتم سئل أبي عنه، فقال: صدوق
- قَالَ سُفْيَانُ: فِي حَقِّهِ حدثني الحسن بن محمد الخلال، عن أبي الحسن الدارقطني، قال: بشر بن مطر ثقة
وفاته
- أخبرنا السمسار، قال: أخبرنا الصفار، قال: حدثنا ابن قانع: أن بشر بن مطر مات في سنة تسع وخمسين ومائتين، وقرأت بخط محمد بن مخلد: سنة اثنتين وستين ومائتين فيها مات بشر بن مطر بن ثابت أبو أحمد الدقاق', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
