INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('أبو عبد الله الفاكهي', 'مؤلف', 'الفاكهي (٠٠٠ - بعد ٢٧٢ هـ = ٠٠٠ - بعد ٨٨٥ م)
محمد بن إسحاق بن العباس الفاكهي أبو عبد الله المكي: مؤرخ، من أهل مكة.
كان معاصرا للأزرقي، متأخرا عنه في الوفاة.
له (أخبار مكة - ط) قسم منه، ومنه قسم في جامعة الرياض الرقم (٢٢٥ ص) يراجع على القسم المطبوع منه (١).
من شيوخه: سعيد بن منصور، والزبير بن بكار، ويعقوب بن حميد.
من تلاميذه: محمد بن سهل العماني، وأبو محمد الفاكهي.
قال في العقد الثمين فى تاريخ البلد الأمين (٢/ ١٠٩)
مؤلف أخبار مكة، روى فيه عن: ابن أبى عمر العدنى، وبكر بن خلف، وحسين بن حسن المروزى، وجماعة.
وكتابه فى أخبار مكة، كتاب حسن جدا لكثرة ما فيه من الفوائد النفيسة وفيه غنية عن كتاب الأزرقى.
وكتاب الأزرقى لا يغنى عنه؛ لأنه ذكر فيه أشياء كثيرة حسنة مفيدة جدا لم يذكرها الأزرقى. وأفاد فى المعنى الذى ذكره الأزرقى أشياء كثيرة، لم يفدها الأزرقى.
_________
(١) عن الزركلي، ومصادره فيه: رونق الألفاظ - خ. وكشف الظنون ٣٠٦ والتيمورية ٣: ٢٢٤ ومعجم المطبوعات ١٤٣١ ومخطوطات الرياض ١٢١.', NULL, '0272-01-01', '0885-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


