INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('أبو حنيفة الدينوري', 'مؤلف', 'أبو حنيفة الدينوري (؟ - ٢٨١ هـ،؟ - ٨٩٤ م).
أحمد بن داود، ويكنى بأبي حنيفة، ويُسمّى أيضًا عبد الله بن علي العشاب.
من علماء المسلمين الذين أحبوا الرحلات، حيث زار كثيرًا من بلاد العرب مثل: المدينة المنورة، وبغداد وفلسطين. عُرف الدينوري بتفوقه في علم النبات؛ حيث أسسه على التجربة والاستنتاج، وقضى حياته في البحث والتأليف والتعليم، ودرس تربة بلاد العرب والطريقة العلمية لزراعة النباتات المهمة وهو أول من ألف في الفلورا العربية.
ألف الدينوري كتابًا في علم النبات في ستة مجلدات على هيئة موسوعة مفصّلة بعنوان: كتاب النبات والشجر، جمع فيه ملاحظاته الشخصية بعد معاينة النباتات في مواطنها، فاقتصر الكتاب على نباتات بلاد العرب والنباتات الأجنبية التي تأقلمت فيها. فكان الدينوري بحق أول المؤلفين العرب في علم النبات.
وبالإضافة إلى هذا الكتاب، له عدة مؤلفات في العلوم الأخرى تزيد على العشرين كتابًا.
ولد الدينوري في دينور بإقليم همدان، وعاش في القرن الثالث للهجرة (التاسع الميلادي).
نقلا عن
الموسوعة العربية العالمية http://www.mawsoah.net', NULL, '0281-01-01', '0894-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


