INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('إبراهيم بن عبد الصمد', 'مؤلف', 'إبراهيم بن عبد الصمد (٠٠٠ - ٣٢٥ هـ = ٠٠٠ - ٩٣٦ م)
إبراهيم بن عبد الصمد بن موسى بن محمد بن إبراهيم بن محمد بن علي بن عبد الله بن العباس بن عبد المطلب القرشي الهاشمي، أبو إسحاق البغدادي، من رجال الحديث. كان أبوه أمير الحاج في زمان المتوكل، غير مرة، ورحل معه.
تاريخ الوفاة: ٣٢٥هــ. وتوفي بسامراء.
شيوخه:
أبو مصعب أحمد بن أبي بكر الزهري.
الحسين بن الحسن المروزي.
سعيد بن عبد الرحمن المخزومي.
محمد بن الوليد البسري.
خلاد بن أسلم.
عبيد بن أسباط بن محمد.
عبد الصمد بن موسي.
تلاميذه:
أبو الحسين بن البواب المقرىء.
أبو الحسن الدارقطني.
أبو حفص بن شاهين.
يوسف بن عمر القواس.
أبو حفص الكتاني.
أحمد بن محمد بن الصلت المجبر.
زاهر بن أحمد الفقيه.
مكانته:
قال الذهبي: الأمير، المسند، الصدوق.
كان أبوه أمير الحاج مدة، وكان إبراهيم يسكن «سر من رأى»، وحدث بها، وببغداد. وهو آخر من روي في الدنيا عن أبي مصعب «الموطأ».
توفي بسامراء في أول المحرم، قال الذهبي: عن بضع وتسعين سنة، وقد أملي عدة مجالس في سنة أربع، سمعها ابن الصلت منه.
مصنفاته:
«جزء الهاشمي».
مصادر الترجمة:
تاريخ بغداد.
التقييد.
سيرأعلام النبلاء.
تاريخ الإسلام.
ميزان الإعتدال.
لسان الميزان.
شذرات الذهب.
(نقلا عن: موقع جامع الحديث)', NULL, '0325-01-01', '0936-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
