INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('ابن أبي حاتم', 'مؤلف', 'ابن أَبي حاتِم (٢٤٠ - ٣٢٧ هـ = ٨٥٤ - ٩٣٨ م)
عبد الرحمن بن محمد أبي حاتم ابن إدريس بن المنذر التميمي الحنظليّ الرازيّ، أبو محمد
• حافظ للحديث، من كبارهم.
• كان منزله في درب حنظلة بالريّ، وإليهما نسبته.
له تصانيف، منها:
• (الجرح والتعديل - ط) ثمانية مجلدات منه
• (التفسير) عدة مجلدات، منها جزآن مخطوطان [طُبِع]
• (الرد على الجهمية) كبير
• (علل الحديث - ط) جزآن
• (المسند) كبير
• (الكنى)
• (الفوائد الكبرى)
• (المراسيل - ط)
• (تقدمة المعرفة بكتاب الجرح والتعديل - خ) في دار الكتب (٩٠ مصطلح)
• (زهد الثمانية من التابعين - خ) في الظاهرية.
• (آداب الشافعيّ ومناقبه - ط)
• (بيان خطأ أبي عبد الله محمد بن إسماعيل البخاري في تاريخه - ط) (١).
_________
(١) تذكرة الحفاظ ٣: ٤٦ وفوات الوفيات ١: ٢٦٠ وطبقات الحنابلة ٢: ٥٥ والمقصد الأرشد - خ. وفيه: وفاته سنة ٣٢٩ هـ ومخطوطات الظاهرية ٢٧٧ والفهرس التمهيدي ٣٧٧ ومعجم المطبوعات ٢٨ والخزانة التيمورية ٢: ٣٠٤ والمخطوطات المصورة، التاريخ ٢ القسم الرابع ١١٨.
نقلا عن: «الأعلام» للزركلي [مع إضافة بين معقوفين]', 'المذهب الشافعي', '0854-01-01', '0938-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('ابن عبد ربه الأندلسي', 'مؤلف', 'ابن عبد ربه (٢٤٦ - ٣٢٨ هـ = ٨٦٠ - ٩٤٠ م)
أحمد بن محمد بن عبد ربه ابن حبيب ابن حدير بن سالم، أبو عمر: الأديب الإمام صاحب العقد الفريد.
من أهل قرطبة.
كان جده الأعلى (سالم) مولى لهشام بن عبد الرحمن بن معاوية.
وكان ابن عبد ربه شاعرا مذكورا فغلب عليه الاشتغال في أخبار الأدب وجمعها.
له شعر كثير.
منه ما سماه (الممحصات) وهي قصائد ومقاطيع في المواعظ والزهد، نقض بها كل ما قاله في صباه من الغزل والنسيب.
وكانت له في عصره شهرة ذائعة.
وهو أحد الذين أثروا بأدبهم بعد الفقر.
أما كتابه (العقد الفريد - ط) فمن أشهر كتب الأدب.
سماه (العقد) وأضاف النساخ المتأخرون لفظ (الفريد) .
وله أرجوزة تاريخية ذكر فيها الخلفاء وجعل معاوية (رضي الله عنه) رابعهم ولم يذكر عليا (رضي الله عنه) فيهم.
وقد طبع من ديوانه (خمس قصائد) وأصيب بالفالج قبل وفاته بأيام.
ولجبرائيل سليمان جبور اللبناني كتاب سماه (ابن عبد ربه وعقده - ط) ولفؤاد أفرام البستاني (ابن عبد ربه - ط) .
نقلا عن: الأعلام للزركلي', NULL, '0860-01-01', '0940-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('ابن الأنباري', 'مؤلف', 'ابن الأنباري (٢٧١ - ٣٢٨ هـ = ٨٨٤ - ٩٤٠ م)
[أبو بكر، محمد بن القاسم بن محمد بن بشار بن الحسن بن بيان بن سماعة بن فَروة بن قَطَن بن دعامة الأنباري]
• من أعلم أهل زمانه بالأدب واللغة، ومن أكثر الناس حفظا للشعر والأخبار، قيل: كان يحفظ ثلاثمائة ألف شاهد في القرآن.
• ولد في الأنبار (على الفرات) وتوفي ببغداد.
• وكان يتردد إلى أولاد الخليفة الراضي بالله، يعلمهم.
من كتبه:
• (الزاهر - خ) [ثم طُبع] في اللغة
• (شرح القصائد السبع الطوال الجاهليات - ط)
• (إيضاح الوقف والابتداء في كتاب الله عز وجل - ط) [ثم طُبع]
• (الهاآت - خ)
• (عجائب علوم القرآن - خ)
• (شرح الألفات - ط) رسالة نشرت في مجلة المجمع بدمشق
• (خلق الإنسان)
• (الأمثال)
• (الأضداد - ط)
• وأجل كتبه (غريب الحديث) قيل إنه ٤٥٠٠٠ ورقة.
• وله (الأمالي) اطلعت على قطعة منها كتبت في المدرسة النظامية، وعليها خط الحافظ عبد العزيز ابن الأخضر، سنة ٦٠٩ هـ.
نقلا عن: «الأعلام» للزركلي [بزيادات بين معكوفات]', NULL, '0884-01-01', '0940-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('أبو محمد البربهاري', 'مؤلف', 'البربهاري (٢٣٣ - ٣٢٩ هـ = ٨٤٧ - ٩١٤ م)
الحسن بن علي بن خلف البربهاري، أبو محمد: شيخ الحنابلة في وقته.
من أهل بغداد.
كان شديد الإنكار على أهل البدع، بيده ولسانه.
وكثر مخالفوه فأوغروا عليه قلب القاهر العباسي (سنة ٣٢١ هـ) فطلبه، فاستتر.
وقبض على جماعة من كبار أصحابه ونفوا إلى البصرة.
وعاد إلى مكانته في عهد الراضي، ونودي ببغداد: لا يجتمع من أصحاب البربهاري نفسان ! واستتر البربهاري فمات في مخبأه.
له مصنفات، منها (شرح كتاب السنة).
والبربهاري نسبة إلى (البربهار) وهي أدوية كانت تجلب من الهند ويقال لجالبها البربهاري، ولعلها ما يسمى اليوم بالبهارات (١).
_________
(١) طبقات الحنابلة ٢٩٩ وفيه: بلغ من كثرة أصحاب البربهاري أنه عطس وهو يجتاز بالجانب الغربي من بغداد، فشمته أصحابه، فارتفعت ضجتهم حتى سمعها الخليفة - الراضي - وهو في روشنه، فسأل عن الحال، فأخبر بها، فاستهولها !
نقلا عن : الأعلام للزركلي', NULL, '0847-01-01', '0914-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('أبو القاسم حامض رأسه', 'مؤلف', 'قال الذهبي في «السير» :
أَبُو القَاسِمِ ، عَبْدُ اللهِ بنُ مُحَمَّدِ بنِ إِسْحَاقَ بنِ يَزِيْدَ، المَرْوَزِيُّ الأَصل، البَغْدَادِيُّ، وَيُعْرَفُ بحَامض رَأْسه.
سَمِعَ:سَعْدَان بنَ نَصْرٍ، وَالحَسَنَ بنَ أَبِي الرَّبِيْع، وَأَبَا يَحْيَى مُحَمَّدَ بنَ سَعِيْدٍ العَطَّار، وَأَبَا أُمَيَّة الطَّرَسُوْسِيَّ وَجَمَاعَةً.
حَدَّثَ عَنْهُ:أَبُو عُمَرَ بنُ حَيَّوَيه، وَالقَاضِي أَبُو بَكْرٍ الأَبْهَرِيُّ، وَأَبُو الحَسَنِ الدَّارَقُطْنِيّ، وَعُمَر بنُ شَاهِيْنٍ، وَالمُعَافَى الجُرَيْرِيّ، وَأَبُو الحُسَيْنِ بنُ جُمَيْع.
وَنقل الخَطِيْبُ أَنَّهُ ثِقَةٌ .
تُوُفِّيَ فِي شَهْرِ رَمَضَانَ سَنَةَ تِسْعٍ وَعِشْرِيْنَ وَثَلَاثِ مائَةٍ.', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


