INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('ابن المرزبان الباحث', 'مؤلف', 'أبو منصور محمد بن سهل بن المَرْزُبان الكرخي (ت نحو ٣٣٠ هـ)
قال ابن النديم في «الفهرست»:
«الباحث عن معتاص العلم»، من أهل الكرخ، أحد البلغاء الفصحاء وقال لي من رآه أنه أشل اليد وله من الكتب كتاب «المنتهى في الكمال» ويحتوي على اثني عشر كتابا وهي:
١- كتاب مدح الأدب
٢- كتاب صفة البلاغة
٣- كتاب الدعاء والتحاد
٤- كتاب الشوق والفراق
٥- كتاب الحنين إلى الأوطان
٦ - كتاب التهاني والتعازي
٧ - كتاب الأمل والمأمول
٨ - كتاب التسبيبات والطلب
٩ - كتاب الحمد والذم
١٠ -كتاب الاعتذارات
١١- كتاب الألفاظ
١٢ -كتاب نفائس الحكم.
قال «حامد صادق قنيبي»، محقق كتاب الألفاظ: تجمع المصادر الآتية على نسبة كتاب الألفاظ إلى ابن المرزبان الباحث، وهي: الفهرست ١٥٢، الوافي ٣ / ١٤١، هدية العارفين ٢ / ٢٧، معجم الأدباء ١٠ / ٥٨، ولكن صاحب الأعلام شذ عن هذا الإجماع إذ نسب «كتاب الألفاظ» لأبي نصر، سهل بن المرزبان، وهو خطأ لتوهمه تطابق الأسماء', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('محمد بن مخلد العطار', 'مؤلف', 'العطار (٢٣٣ - ٣٣١ هـ = ٨٤٨ - ٩٤٣ م)
محمد بن مخلد بن جعفر، أبو عبد الله الدوري العطار: من رجال الحديث.
مولده ووفاته ببغداد.
ونسبته إلى الدور (محلة بطرفها) قال الدارقطني: ثقة مأمون.
وقال الذهبي: له تصانيف وتخاريج.
منها (الأمالي - خ) و (ما رواه الأكابر عن مالك بن أنس - خ) و (فوائد - خ) [ثم طُبعت] كلها في الظاهرية، و (المنتقى - خ) الثاني منه، في جامعة الرياض (الفيلم ١١٧) ٢٢ ورقة
نقلا عن : الأعلام للزركلي', NULL, '0848-01-01', '0943-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('أبو زيد السيرافي', 'مؤلف', 'كان (سليمان السيرافي) تاجراً إيرانياً من أهالي ميناء السيراف المطل على الخليج الفارسي فسافر إلى الصين ودوّن ذكريات رحلته هذه في كتاب ألفه باللغة العربية وقد تلقفها عنه ورواها وهذّبها أبو زيد حسن بن يزيد السيرافي (صاحب الترجمة) ونحن لا نعرف شيئاً عن حياته أو عن تاريخ ولادته ووفاته، سوى أنه كان يعيش في النصف الأول من القرن الرابع. قضى أبو زيد فترة الطفولة والمراهقة في مسقط رأسه سيراف، ثم هاجر عام ٣٣٠ هـ إلى البصرة وأقام فيها. وهو لم يكن في الحقيقة رحالة ولا عالماً بل كان على ما يظهر من المغرمين بأمثال هذه القصص التي كان من السهل جمع روايات كثيرة منها سواء في مسقط رأسه سيراف أو في البصرة.
وكان خير مثال للتجار العرب والفرس الذين توجهوا إلى الصين، وقد محّص ما ورد عنه وتابع خطواته على ضوء الخرائط الحديثة المستشرق الفرنسي فيرن فوجدها من حيث الدقة والأمانة العلمية بمكانة سامية.', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('ابن ولاد', 'مؤلف', 'ابن وَلَّاد (٠٠٠ - ٣٣٢ هـ = ٠٠٠ - ٩٤٤ م)
أحمد بن محمد بن الوليد، أبو العباس التميميّ، ابن وَلَّاد المِصريّ
• من كبار النحاة، وكذا أبوه وجده. سافر إلى العراق، وأخذ عن أبي إسحاق الزّجاج، وطبقته ورجع.
• صنَّف كتاب «الانتصار لسيبويه على المبرّد» وهو من أحسن الكتب. وله: «المقصور والممدود».
• وكان هو وأبو جعفر النّحّاس شيخيْ مصر في زمانهما. وقيل: هو بغدادي سكن مصر. وقد روى عن المبرد أيضًا.
• حَدَّثَ عَنْهُ: عبد الله بن محمد بن سعيد المصريّ الشّاعر.
نقلا عن «تاريخ الإسلام» للذهبي', NULL, '0332-01-01', '0944-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


