INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('أبو علي الشاشي الحنفي', 'مؤلف', 'أحمد بن محمد بن إسحاق، أبو على الشّاشىّ، الفقيه
سكن بغداد، ودرّس بها.
تفقّه على أبى الحسن الكرخىّ. قاله الخطيب فى «تاريخه».
وقال الصّيمرىّ: صار التدريس بعد أبى الحسن الكرخىّ إلى أصحابه، منهم أبو على الشّاشىّ، وكان أبو على شيخ الجماعة.
وكان أبو الحسن الكرخىّ جعل التدريس له حين فلج، والفتوى إلى أبى بكر الدّامغانىّ.
وكان يقول: ما جاءنا أحفظ من أبى علىّ.
قال: وحدثنى القاضى أبو محمد النّعمان، قال: حضرت أبا على الشّاشىّ، فى مجلس إملائه، وقد جاءه أبو جعفر الهندوانىّ، فسلّم عليه، وأخذ يمتحنه بمسائل الأصول، وكان أبو علىّ الشّاشىّ عارفا بها، فلما فرغ امتحن أبو على أبا جعفر بشئ من مسائل النّوادر، فلم يحفظها، فكان ذلك سبب حفظ الهندوانىّ للنّوادر، وقال لأبى على: جئتك زائرا لا متكلّما.
توفّى سنة أربع وأربعين وثلاثمائة.
[الجواهر المضية في طبقات الحنفية ١/ ٢٦٢]', 'المذهب الحنفي', NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
