INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('أبو بكر النجاد', 'مؤلف', 'أبو بكر النجاد (٢٥٣ - ٣٤٨ هـ = ٨٦٧ - ٩٦٠ م)
تاريخ الميلاد: ٢٥٣ هـ.
تاريخ الوفاة: ٣٤٨ هـ.
شيوخه:
أبو داود السجستاني.
