INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('محمد بن الحسن الجوهري', 'مؤلف', 'قال محقق «نوادر الفقهاء» د. محمد فضل عبد العزيز المراد:
• هو محمد بن الحسن التميمي الجوهري كما ذُكر في أول الكتاب وكما ذكر تلميذه الذي روي عنه هذا الکتاب وهو القاضي أبو القاسم عبد الرحمن عبد الله بن أحمد المازري البغدادي. كل ذلك مذكور في أول صفحة من المخطوطة.
• وبعد جهد كبير بذلته لم أستطع الحصول على ترجمة للمؤلف، ومع الرجوع إلي المصادر التي أمکنني الرجوع إليها، والبحث العميق، وسؤال بعض العلماء، لم أعثر على من ترجم لهذا المؤلف رحمه الله.
• وفي «فهرس المخطوطات العربية المحفوظة في الخزانة العامة للكتب والوثائق بالمغرب» والذي طبعته وزارة الأوقاف والشؤون الإسلامية والثقافة بالمغرب، جاء في الجزء الأول من القسم الثالث منه، (ص ٢٤٧)، وتحت رقم مسلسل (٣٤٧٣) ما نصه:
«نوادر الفقهاء ـ تأليف محمد بن الحسن التميمي الجوهري، وهو في الأقوال الشاذة للفقهاء المجتهدين ـ مرتب على أبواب الفقه. . .» إلى أن قال: «لم نعثر علي هذا الکتاب ولا علي مؤلفه في جميع المصادر التي تصفحناها». اهـ.
• والذي يترجح لدي أن المؤلف عاش في القرن الرابع الهجري، وهذا مبني على النص الذي ورد في کتاب «التقييد والإيضاح» للحافظ زين الدين العراقي، (ص ١٤٣)، حيث جاء ما نصه:
«وذكر صاحب كتاب «الإنصاف» محمد بن الحسن التميمي الجوهري المصري: أن هذا مذهب الأكثر من أصحاب الحديث الذي لا يحصيهم أحد، وأنهم جعلوا «أخبرنا» علماً يقوم مقام قول قائله: «أنا قرأته عليه» لا أنه لفظ به لي، قال: وممن كان يقول به من أهل زماننا أبو عبد الرحمن النسائي في جماعة مثله من محدثينا». اهـ.
فإذا كان هذا المذكور هو نفس المصنف - وهو على الأرجح - فيكون من معاصري الإمام النسائي، ومن تلامذة بعض المحدثين الذين هم من طبقة الإمام النسائي، والإمام النسائي توفي عام ٣١٠ هـ فيكون المصنف ممن قد عاش في القرن الرابع الهجري على الوجه الأرجح والله أعلم.
وبعد البحث الدقيق ومساعدة أهل الخبرة في هذا الفن لم نعثر على ترجمة للمصنف في علماء ذلك العصر، ولعله في المستقبل القريب إن شاء الله نصل إلى ترجمة له. والله الموفق', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


