INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('اسبهبد مرزبان', 'مؤلف', 'اسبهبد مرزبان بن شروين بن رستم بن شهريار واحد من أربعة أنجال لـ «شروين» أحد ملوك طبرستان من سلالة آل باوند
لما توفي «شروين» خلف من الذكور خمسة أنفار كل منهم صالح للسلطنة فاستولى على الملك بعده أكبر أولاده.
وكان «مرزبان» واضع هذا الكتاب هو أصغرهم، فاستمر الأخوة الأربعة في خدمة أخيهم الأكبر مدة، ثم إنه حصل في خواطر الأخوة مما يخاطر ببال الناس من المخالفة فخاف مرزبان من ذلك على نفسه وأنه لا يستطيع أن يكون في جهة أحد منهم إذ كل منهم أخوه. . . فأراه اجتهاده إلى أن يتوجه إلى جهة من جهات المملكة وينحاز عن دائرة ما يقع بين أخ، وته من المخالفة والمناكدة بينهم وبين أخيهم الملك حتى لا ينسب إليه شيء من ذلك ويسلم من تلك الكدورات ..
وألف كتابه «مرزبان نامه» في أواخر القرن الرابع الهجري', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('إسحاق بن الحسين المنجم', 'مؤلف', 'إسحاق بن الحسين المنجم
شبه مجهول، لا يعرف عنه سوى اسمه.
لقد قام جماعة من المستشرقين ببعض التحريات حول المؤلف، ومنهم مينورسكي وأرمنياكوف وبروكلمان، دون الوصول إلى نتيجة حاسمة. وخلاصة هذه التحريات، أن المؤلف عاش في القرن الثالث للهجرة، ورأي آخر يقول إنه عاش في حدود ٣٤٠ هـ، ورأي ثالث أنه عاش في فترة لا تتعدى ٤٥٤ هـ، العام الذي أسست فيه مدينة مراكش، التي لم يرد ذكرها لديه. وهناك من قال بأن المؤلف أندلسي، بدليل وجود صدى لهجة الأندلس في كتابه آكام المرجان.', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
