INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('أبو عمر الكندي', 'مؤلف', 'أبو عمر الكنديّ صاحب ولاة مصر (٢٨٣ - ٣٥٠ هـ)
• محمد بن يوسف بن يعقوب بن حفص بن يوسف بن نصير بن زيد بن عبد الله بن قيس بن الحارث بن عميس بن ضبيع بن عبد العزيز بن عامر بن مالك بن براءة بن أذاة بن عديّ بن أشرس بن شيبة بن السكون بن الأشرس ابن كندة، التجيبيّ، أبو عمر، الكنديّ، المصريّ، المؤرّخ، الفقيه، الحنفيّ.
• ولد يوم النحر سنة ثلاث وثمانين ومائتين.
• روى عن عليّ بن الحسن بن خلف بن قديد الأزديّ، وأبي عبد الرحمن النسائيّ، وجماعة.
• وروى عنه أبو محمد عبد الرحمن بن عمر ابن النحّاس.
• وصنّف الكثير في أخبار مصر، فمنها: كتاب الأمراء، وكتاب الرايات، وكتاب القضاة، وكتاب الموالي، وكتاب الجند الغربيّ، وكتاب الخندق والتراويح، وكتاب الخطط، وكتاب أخبار السريّ بن الحكم.
• وكان عارفا بأحوال الناس وسير الملوك. قال أبو محمد عبد الله بن أحمد الفرغانيّ: كان من أعلم الناس بالبلد وأهله وأعماله وثغوره. وله مصنّفات فيه، وفي غيره من صنوف الأخبار والأنساب. وكان من جلّة أهل العلم بالحديث والنسب، عالما بكتب الحديث، صحيح الكتاب، نسّابة، عالما بعلوم العرب. سمع من النسائيّ وغيره، وحدّث في آخر عمره وسمع منه. وكان يتفقّه على مذهب العراقيّين.
• وتوفّي يوم الثلاثاء لثلاث خلون من شهر رمضان سنة خمسين وثلاثمائة بمصر، ودفن بمقابر غافق وكندة
نقلا عن: «المقفى الكبير» للمقريزي (٧/ ٢٦٤)', 'المذهب الحنفي', '0283-01-01', '0350-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


