INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('الطبراني', 'مؤلف', 'الطبراني، أبو القاسم (٢٦٠ - ٣٦٠هـ، ٨٧٣ - ٩٧١م).
سليمان بن أحمد بن أيوب بن مطير اللخمي الشامي، أبو القاسم. محدِّث مشهور، ثقة حافظ، معمر. والطبراني نسبة إلى بلدة طبرية، فإن أصله منها. وُلد بعكا في فلسطين، وبدأ بسماع الحديث سنة ٢٧٣هـ. كان أبوه حريصًا عليه فرحل به لطلب العلم. رحل إلى بلدان كثيرة منها: بغداد والكوفة، والبصرة وإلى مدائن الشام والحجاز ومصر واليمن وأصبهان وغيرها. وامتدت رحلاته ثلاثين سنة. استقر به المقام في أصفهان. سمع من إسحق الدبري وعلي بن عبد العزيز البغوي، وأبي عبد الرحمن النسائي. روى عنه ابن عقدة، وأبو بكر بن مردويه، وأبو نعيم الأصبهاني، وعبد الرحمن بن أحمد الصفار. من مصنفاته المعجم الكبير؛ المعجم الأوسط؛ المعجم الصغير؛ كتاب الدعاء والمناسك؛ عُشرة النساء؛ السنة؛ مسند شعبة؛ مسند سفيان؛ الأوائل؛ مسند الشاميين؛ مكارم الأخلاق وله تفسير كبير الحجم. سرد الذهبي مصنفات الطبراني نقلاً عن يحيى بن منده، فكانت ٧٦ مؤلفًا. عاش مائة سنة وعشرة أشهر. وتُوفي في أصفهان.
نقلا عن
الموسوعة العربية العالمية http://www.mawsoah.net', NULL, '0873-01-01', '0971-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('الدراج', 'مؤلف', 'جاء في تاريخ بغداد:
عُثْمَان بْن عُمَر بْن خفيف أَبُو عُمَر المقرئ المعروف بالدراج
حدث عَن هارون بْن علي المزوق، وعلي بْن حماد بْن هشام العسكري، وأحمد بْن مُحَمَّد بْن هشام الطالقاني، وأحمد بْن حبيب النهرواني، وأبي بكر بْن أَبِي داود، ومحمد بْن هارون بْن المجدر، وغيرهم.
حَدَّثَنَا عنه أَبُو الحسن بْن رزقويه، ومكي بْن علي الحريري، ومحمد بْن جعفر بْن علان، وأبو بكر البرقاني، وعلي بْن عَبْد العزيز الطاهري، ومحمد بْن طلحة النعالي، ومحمد بْن عُمَر بْن بكير النجار، وكان ثقة.
قرأت يوما على البرقاني حديثا عَن عُثْمَان الدراج، فقال : كان بدلا من الأبدال، وذكر لي عنه أنه، قَالَ يوما فِي مرضه الذي توفي فيه لرجل كان يخدمه.
امض فصل ثم ارجع سريعا، فإنك تجدني قد مت، وكانت صلاة الجمعة قد حضرت، فمضى الرجل إِلَى الجامع، وصلى الجمعة، ورجع إليه بسرعة، فوجده قد مات.
قَالَ مُحَمَّد بْن أَبِي الفوارس : توفي أَبُو عَمْرو المقرئ المعروف بالدراج يوم السبت لسبع خلون من شهر رمضان سنة إحدى وستين وثلاث مائة، وكان من أهل القرآن والثقة والديانة والستر، جميل المذهب، وكانت وفاته فُجَاءة.', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
