INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('ابن السني', 'مؤلف', 'ابن السُّنّي، أبو بكر (٢٨٠ - ٣٦٤هـ ، ٨٩٤ - ٩٧٤م).
أحمد بن محمد بن إسحاق أبو بكر بن السني. مُحدِّث ثقة، يُعَدُّ راويةً للنسائي. كان كثير الرحلة، رحل إلى العراق ومصر والشام والجزيرة. من أبرز شيوخه: النسائي صاحب السنن، وزكريا الساجي، والباغندي. ألّف من الكتب: عمل اليوم والليلة؛ القناعة؛ الطب النبوي؛ الصراط المستقيم؛ فضائل الأعمال. ويُقال: هو الذي اختصر سنن النسائي وسماه المجتبى. والأرجح عند الكثيرين أن الذي تولى ذلك هو النسائي نفسه تحقيقًا لرغبة أمير الرملة عندما أهدى إليه النسائي سننه الكبرى في تجريد الصحيح منها فكان المجتبى. مات وله أكثر من ثمانين سنة.
نقلا عن
الموسوعة العربية العالمية http://www.mawsoah.net', NULL, '0894-01-01', '0974-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
