INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('أبو هلال العسكري', 'مؤلف', 'أبُو هِلال العَسكري (٠٠٠ - بعد ٣٩٥ هـ = ٠٠٠ - بعد ١٠٠٥ م)
أبو هلال، الحسن بن عبد الله بن سهل بن سعيد ابن يحيى بن مهران العَسْكَري:
عالم بالأدب له شعر.
نِسبتُه الى (عسكر مُكرَم) من كور الأهواز.
وهو ابن أخت (أبي أحمد، الحسن بن عبد الله بن سعيد العسكري) وتلميذه.
[قال الزركلي: وكان من الخطأ في الطبعة الأولى مزج ترجمتَي أبي هلال هذا وأبي أحمد، في ترجمة واحدة، لاتفاق الاسمين والأبوين والنسبتين].
مِن كتبه:
(التلخيص) في اللغة،
و (معجم - خ) في اللغة،
و (جمهرة الأمثال - ط)
و (الحث على طلب العلم - خ) رسالة،
و (كتاب الصناعيتن: النظم والنثر - ط)
و (شرح الحماسة)
و (الأوائل - خ) رسالة، قال صاحب كشف الظنون: وهو أول من صنف في الأوائل، وعلى رسالته هذه بنى السيوطي كتابه (الوسائل إلى معرفة الأوائل).
و (الفرق بين المعاني)
و (العمدة)
و (ما تلحن فيه الخاصة)
و (المحاسن) في تفسير القرآن، خمس مجلدات،
و (كتاب من احتكم من الخلفاء إلى القضاة)
و (التبصرة)
و (أسماء بقايا الأشياء - ط)
و (فضل العطاء على العسر - ط) رسالة،
و (الدرهم والدينار)
و (ديوان شعره)
و (الفروق - ط) في اللغة،
و (ديوان المعاني - ط) جزآن.
قال ياقوت: أما وفاته فلم يبلغني فيها شيء غير أني وجدت في آخر كتاب (الأوائل) من تصنيفه: (وفرغنا من إملاء هذا الكتاب يوم الأربعاء لعشر خلت من شعبان سنة خمس وتسعين وثلاثمائة).
ومن مستطرف الأسجاع ما كتبه عنه الباخرزي في «دُمية القصر» قال: «بلغني أن هذا الفاضل كان يحضر السوق، ويحمل إليها الوسوق، ويحلب دَرّ الرزق ويمتري، بأن يبيع الأمتعة ويشتري، فانظر كيف يحدو الكلام ويسوق، وتأمّل هل غضّ من فضله السوق، وكان له في سوقة الفضلاء أسوة، أو كأنه استعار منهم لأشعاره كسوة، وهم: نصر بن أحمد الخبزرزي، وأبو الفرج الوأواء الشامي، والسريّ الرفّاء الموصلي. أما نصر فكان يدحو لرفاقه الأرْزِيّة، ويشكو في أشعاره تلك الرَزيّة، وأما أبو الفرج فكان يسعى بالفواكه رائحا وغاديا، ويتغنى عليها مناديا، وأما السريّ فكان يطري الخَلَق، ويرفو الخِرَق، ويصف تلك العبرة، ويزعم أنه يسترزق بالإبرة. وكيف كان فهذه حِرفة لا تنجو من حُرفة، وصنعة لا تنجو من صنعة، وبضاعة لاتَسلم من إضاعة، ومتاع ليس لأهله استمتاع!» (*).
_________
(*) خزانة الأدب للبغدادي ١: ١١٢ ومعجم البلدان ٦: ١٧٧ ودمية القصر - خ - وإرشاد الأريب: القسم الأول من الجزء الثالث ١٣٥ - ١٣٩ والبعثة المصرية ٣٧.
نقلا عن «الأعلام» للزركلي.', NULL, '0395-01-01', '1005-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
