INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('ابن زنبور الوراق', 'مؤلف', 'قال الذهبي في ميزان الاعتدال:
محمد بن عمر بن خلف بن زنبور البغدادي الوراق.
روى عن أبي بكر ابن أبي داود، وجماعة.
آخر من حدث عنه أبو نصر الزيبنى.
قال أبو بكر الخطيب : ضعيف جدا.
