INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('ابن القصار', 'مؤلف', 'أبو الحسن علي بن عمر بن أحمد البغدادي المالكي المعروف بابن القصار
• شيخ المالكية.
• حدث عن: علي بن الفضل الستوري وغيره.
• روى عنه: أبو ذر الحافظ، وأبو الحسين بن المهتدي بالله.
• وثقه الخطيب. وكان من كبار تلامذة القاضي أبي بكر الأبهري، يذكر مع أبي القاسم الجلاب.
• قال أبو إسحاق الشيرازي: له كتاب في مسائل الخلاف كبير، لا أعرف لهم كتابا في الخلاف أحسن منه.
• قال القاضي عياض: كان أصوليا نظارا، ولي قضاء بغداد.
• وقال أبو ذر: هو أفقه من لقيت من المالكيين، وكان ثقة قليل الحديث.
• قال ابن أبي الفوارس: مات في ثامن ذي القعدة، سنة سبع وتسعين وثلاث مائة.
ويقال: مات سنة ثمان، والأول أصح.
نقلا عن «سير أعلام النبلاء» للذهبي', 'المذهب المالكي', NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('بديع الزمان الهمذاني', 'مؤلف', 'بديع الزمان (٣٥٨ - ٣٩٨ هـ = ٩٦٩ - ١٠٠٨ م)
أحمد بن الحسين بن يحيى الهمذاني، أبو الفضل: أحد أئمة الكتاب.
له (مقامات - ط) أخذ الحريري أسلوب مقاماته عنها.
وكان شاعرا وطبقته في الشعر دون طبقته في النثر.
ولد في همذان وانتقل إلى هراة سنة ٣٨٠ هـ فسكنها، ثم ورد نيسابور سنة ٣٨٢ هـ ولم تكن قد ذاعت شهرته، فلقي أبا بكر الخوارزمي، فشجر بينهما ما دعاهما إلى المساجلة، فطار ذكر الهمذاني في الآفاق.
ولما مات الخوارزمي خلا له الجو فلم يدع بلدة من بلدان خراسان وسجستان وغزنة إلا دخلها ولا ملكا ولا أميرا إلا فاز بجوائزه.
كان قوي الحافظة يضرب المثل بحفظه.
ويذكر أن أكثر (مقاماته) ارتجال، وأنه كان ربما يكتب الكتاب مبتدئا بآخر سطوره ثم هلم جرا إلى السطر الاول فيخرجه ولا عيب فيه ! وله (ديوان شعر - ط) صغير.
و (رسائل - ط) عدتها ٢٣٣ رسالة، ووفاته في هراة مسموما
نقلا عن : الأعلام للزركلي', NULL, '0969-01-01', '1008-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


