INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('الباقلاني', 'مؤلف', 'الباقِلَّاني ، أبو بكر (٣٣٨ - ٤٠٣ هـ، ٩٥٠ - ١٠١٣م).
محمد بن الطيب بن محمد بن جعفر بن القاسم، القاضي أبو بكر الباقلاني المالكي. فقيه بارع، ومحدث حجة، ومتكلم على مذهب أهل السنة والجماعة وطريقة الأشعري. انتهت إليه رئاسة المالكية بالعراق في عصره. كان قائد الكتيبة في الحرب التي دارت رحاها بين الدولة العباسية والدولة الفاطمية. وكان لقلمه الأثر القوي في تمزيق حجج الفاطميين.كان رحمه الله ذكيًا، غاية في الذكاء والفطنة وكان مسددًا في نقاشه، محافظًا على كرامة الإسلام، عفيفاً في لفظه. قال له طاغية الروم: خبرني عن عائشة زوجة نبيكم؟ فقال له الباقلاني: هما اثنتان قيل فيهما ما قيل: زوج نبينا ومريم ابنة عمران، فأما زوج نبينا فلم تلد وكان لها بعل، وأما مريم: فجاءت بولد، وليس لها بعل، وكل قد برأها الله مما رميت به. فسكت طاغية الروم ولم يُحِر جوابًا. قال أبو بكر الخوارزمي يصف سعة علم أبي بكر الباقلاني: كل مصنِّف في بغداد، إنما ينقل من كتب الناس إلى تصانيفه، إلا القاضي أبا بكر الباقلاني، فإن صدره يحوي علمه وعلم الناس. له مؤلفات كثيرة، وقد قال ابن كثير في البداية والنهاية: كان الباقلاني لا ينام حتى يكتب عشرين ورقة في كل ليلة مدة طويلة من عمره. ومن هذه المؤلفات الكثيرة التي كتبها الباقلاني: شرح الإبانة؛ شرح اللمع؛ الإمامة الكبرى والإمامة الصغرى؛ التبصرة بدقائق الحقائق؛ أمالي إجماع أهل المدينة؛ المقدمات في أصول الديانات؛ إعجازالقرآن؛ مناقب الأئمة؛ حقائق الكلام؛ التعريف والإرشاد؛ التمهيد في أصول الفقه؛ المقنع في أصول الفقة؛ كتاب في الرد على الباطنية الفاطميين، سماه: كشف الأسرار وهتك الأستار؛ تمهيد الأوائل وتلخيص المسائل. توفي ببغداد.
نقلا عن
الموسوعة العربية العالمية http://www.mawsoah.net', 'المذهب المالكي', '0950-01-01', '1013-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


