INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('ابن الفرضي', 'مؤلف', 'أبو الوليد ابن الفَرَضي (٣٥١ - ٤٠٣ هـ = ٩٦٢ - ١٠١٣ م)
أبو الوليد، عبد الله بن محمد بن يوسف بن نصر الأزدي، المعروف بابن الفرضيّ:
مؤرخ حافظ أديب.
ولد بقرطبة، وتولى قضاء بلنسية في دولة محمد المهدي المرواني.
ورحل إلى المشرق سنة ٣٨٢ هـ فحج وعاد، فاستقر بقرطبة إلى أن قتله البربر -يوم فتحها- شهيدا في داره.
من مصنفاته:
١ - «تاريخ علماء الأندلس» - ط جزآن منه.
٢ - «المؤتلف والمختلف» في الحديث.
٣ - «المتشابه» في أسماء رواة الحديث وكناهم، [طبع بتحقيق د. عبد الله لنصاري، عن وزارة الأوقاف والشؤون الإسلامية المغربية ١٤٣٨ هـ= ٢٠١٧ م، ثم بتحقيق د. جمال القديم عن الرابطة المحمدية للعلماء بالمغرب سنة ١٤٤٠ هـ= ٢٠٢٩ م]
٤ - «أخبار شعراء الأندلس» (*).
٥ - [«الألقاب» طُبِع منتخبٌ منه لأبي القاسم ابن حبيش الأندلسي ت ٥٨٤ هـ عدة طبعات].
_________
(*) الصلة لابن بشكوال ٢٤٨ وفيه: «وهو صاحب تاريخ علماء الأندلس الّذي وصلناه بكتابنا هذا». والتبيان - خ. وجذوة المقتبس ٥٣٧ و. Brock I: ٤١٢ S I: ٥٧٧. ونفح الطيب ١: ٣٨٩ وفهرسة ابن خليفة ٢١٨ وابن خلكان ١: ٢٦٨ والذخيرة: المجلد الثاني من القسم الأول ١٣٠ وفيه «مقتله سنة ٤٠٠ هـ» كما في بغية الملتمس ٣٢١ والمغرب ١٠٣.
نقلا عن: «الأعلام» للزركلي، مع زيادات بين [معوقفات] من فريق المكتبة الشاملة', NULL, '0962-01-01', '1013-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


