INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('ابن حمكان', 'مؤلف', 'جاء في تاريخ بغداد:
الْحَسَن بن الْحُسَيْن بن حمكان أَبُو عَلِيّ الهمذاني أحد فقهاء الشافعيين، نزل بغداد فِي درب يونس بقرب دار القطن.
وحدث عَنْ عَبْد الرَّحْمَنِ بن حمدان الجلاب الهمذاني، ومحمد بن هارون الزنجاني، والزبير بن عبد الواحد الأسداباذي، وجعفر بن مُحَمَّدِ بْنِ نصير الخلدي، ومحمد بن الْحَسَن بن زياد النقاش، وغيرهم من البغداديين، والبصريين.
حَدَّثَنَا عنه أَبُو الْقَاسِمِ الأزهري، وأحمد بن عَلِيّ ابن التوزي، وغيرهما.
حَدَّثَنِي أَبُو الفضل عبد الصمد بن مُحَمَّد الخطيب، قَالَ : قَالَ لي أَبُو عَلِيّ بن حمكان : كتبت بالبصرة وحدها عَنْ أربع مائة ونيف وسبعين شيخا ! قَالَ أَبُو الفضل وقد كتبت بغيرها من البلدان، وكان فِي شبيبته عني بالحديث، ثم طلب الفقه بعد ودرس عَلَى أَبِي حامد المروروذي .
سمعت الأزهري، يَقُولُ : أَبُو عَلِيّ بن حمكان ضعيف ليس بشيء فِي الحديث.
حَدَّثَنِي العتيقي، قَالَ : سنة خمس وأربع مائة فيها توفي أَبُو عَلِيّ بن حمكان الهمذاني الفقيه يوم أربعاء فِي جمادى الأولى.
حَدَّثَنِي الْحَسَن بن مُحَمَّد الخلال، قَالَ : مات أَبُو عَلِيّ بن حمكان الفقيه الشافعي لعشر بقين من جمادى الأولى سنة خمس وأربع مائة، ودفن فِي منزله.', 'المذهب الشافعي', NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


