INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('أبو الفضل التميمي', 'مؤلف', 'أبو الفضل التميمي (٣٤٢ - ٤١٠ هـ)
عبد الواحد بن عبد العزيز بن الحارث بن أسد، أبو الفضل التميمي الحنبلي
• فقيه حنبلي، محَدّث. حدث عن: أبي بكر النجاد، وأحمد بن كامل … في آخرين. قال الخطيب البغدادي: كتبنا عنه بانتخاب أحمد بن أبي الفوارس، وكان صدوقا. اهـ
• وكانت له حلقة في جامع المدينة للوعظ والفتوى.
• وخرج إلى خراسان في الأيام القادرية.
مستفاد من «طبقات الحنابلة» (٢/ ١٧٩ ط الفقي) لابن أبي يعلى، و «تاريخ بغداد» للخطيب (١٢/ ٢٦٥ ت بشار)
• ونقل الذهبي في ترجمته بـ «تاريخ الإسلام» (٩/ ١٥٣ ت بشار) عنه أنه قال: اجتمع رأسي ورأس القاضي أبي بَكْر الباقلاني على مِخدة واحدة سبع سِنين .... إلخ.
ثم عَقَّب الذهبي: قلت: ما هذا إلا وُدّ عظيم بين هذا الأشعريّ وبين هذا الحنبليّ، والتّميميّون معروفون بشيءٍ من الانحراف عَنْ طريقة أحمد، كما انحرف ابنُ عَقيل وابن الجَوزي وابن الزاغوني، وغيرهم. اهـ.
• قال شيخ الإسلام ابن تيمية في «مجموع الفتاوى» ٤/ ١٦٧ - ١٦٨: كان أبو الحسن الأشعري وأصحابه منتسبين إلى السنة والجماعة … وكان من أعظم المائلين إليهم: التميميون -أبو الحسن التميمي وابنُه وابنُ ابنِه ونحوهم-، وكان بين أبي الحسن التميمي وبين القاضي أبي بكر بن الباقلاني من المودة والصحبة ما هو معروف مشهور، ولهذا اعتمد الحافظ أبو بكر البيهقي في كتابه الذي صنفه في مناقب الإمام أحمد -لمَّا ذكر اعتقاده- اعتمد على ما نقله من كلام أبي الفضل عبد الواحد بن أبي الحسن التميمي، وله في هذا الباب مصنف ذكر فيه مِن اعتقاد أحمد ما فهمه، ولم يذكر فيه ألفاظه، وإنما ذكر جمل الاعتقاد بلفظ نفسه؛ وجعل يقول: «وكان أبو عبد الله .. »! وهو بمنزلة مَن يصنف كتابا في الفقه على رأي بعض الأئمة ويذكر مذهبه بحسب ما فهمه ورآه، وإن كان غيره بمذهب ذلك الإمام أعلم منه بألفاظه وأفهم لمقاصده؛ فإن الناس في نقل مذاهب الأئمة قد يكونون بمنزلتهم في نقل الشريعة، ومن المعلوم أن أحدهم يقول: «حكم الله كذا أو حكم الشريعة كذا» بحسب ما اعتقده عن صاحب الشريعة بحسب ما بلغه وفهمه، وإن كان غيره أعلم بأقوال صاحب الشريعة وأعماله وأفهم لمراده. اهـ كلامه.', 'المذهب الحنبلي', '0342-01-01', '0410-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('ابن نصر', 'مؤلف', 'قال الذهبي في «السير» :
الشَّيْخُ، العَالِمُ، المُؤَدِّبُ، أَبُو القَاسِمِ عَبْدُ الرَّحْمَنِ بنُ عُمَرَ بنِ نَصْرِ بن مُحَمَّدٍ الشَّيْبَانِيُّ، السَّامَرِّيُّ، ثُمَّ الدِّمَشْقِيُّ، البَزَّازُ.
سَمِعَ: ابْنَ حَبِيْبٍ الحَصَائِرِي، وَخَيْثَمَة بن سُلَيْمَانَ، وَعُثْمَانَ بنَ مُحَمَّدٍ الذَّهبِي، وَأَبَا يَعْقُوْب الأَذْرَعِي، وَخلقاً سِوَاهُم.
حَدَّثَ عَنْهُ: العَتِيْقِيّ، وَعَلِيُّ بنُ صَصْرَى، وَأَبُو عَلِيٍّ الأَهْوَازِيُّ، وَمُحَمَّدُ بنُ عَلِيٍّ الحَدَّادُ، وَالشَّيْخُ عَبْدُ العَزِيْزِ الكَتَّانِيُّ، وَغَيْرُهُم.
قَالَ الكَتَّانِيُّ: كتب الكَثِيْرَ، وَاتُّهُم فِي لِقَاءِ أَبِي إِسْحَاقَ بنِ أَبِي ثَابِتٍ، وَكَانَ يُتَّهَمُ بِالاعتزَالِ.
تُوُفِّيَ: فِي رَجَبٍ، سَنَةَ عَشْرٍ وَأَرْبَعِ مائَةٍ.
قُلْتُ: لَهُ جَمَاعَةُ أَجزَاءٍ مَرويَّة، وَلَمْ يَقَعْ لِي حَدِيْثُهُ إِلاَّ بِنُزول.', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


