INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('أبو عبد الرحمن السلمي', 'مؤلف', 'أبو عبد الرحمن السلمي (٣٢٥ - ٤١٢ هـ = ٩٣٦ - ١٠٢١ م)
محمد بن الحسين بن محمد بن موسى الأزدي السلمي النيسابوري، أبو عبد الرحمن: من علماء المتصوفة.
قال الذهبي: (شيخ الصوفية وصاحب تاريخهم وطبقاتهم وتفسيرهم، قيل: كان يضع الأحاديث للصوفية).
بلغت تصانيفه مئة أو أكثر، منها (حقائق التفسير - خ) مختصر، على طريقة أهل التصوف، في المكتبة المحمودية بالمدينة (٥٢ تفسير) كما في مجلة المجمع (٤٩: ٧٣) و (طبقات الصوفية - ط) و (مقدمة في التصوف - خ) رسالة، و (مناهج العارفين - خ) و (رسالة في غلطات الصوفية - خ) و (رسالة الملامتية - ط) و (آداب الفقر وشرائطه - خ) و (بيان زلل الفقراء ومناقب آدابهم - خ) و (الفتوة - خ) و (آداب الصحبة - ط)
و (السؤالات - خ) و (سلوك العارفين - خ) و (عيوب النفس ومداواتها - ط) و (الفرق بين الشريعة والحقيقة - خ) و (آداب الصوفية - خ) و (كتاب الاربعين في الحديث - ط) و (درجات المعاملات - خ).
مولده ووفاته في نيسابور .
نقلا عن : الأعلام للزركلي', NULL, '0936-01-01', '1021-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


