    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('أبو منصور الثعالبي', 'مؤلف', '[أبو منصور] الثَّعَالِبي (٣٥٠ - ٤٢٩ هـ = ٩٦١ - ١٠٣٨ م)
عبد الملك بن محمد بن إسماعيل، أبو منصور الثعالبي: من أئمة اللغة والأدب. من أهل نيسابور.
كان فراءاً يخيط جلود الثعالب، فنسب إلى صناعته. واشتغل بالأدب والتاريخ، فنبغ. وصنّف الكتب الكثيرة الممتعة.
من كتبه
• «يتيمة الدهر - ط» أربعة أجزاء، في تراجم شعراء عصره
• «فقه اللغة - ط»
• «سحر البلاغة - ط»
• «من غاب عنه المطرب - ط»
• «غرر أخبار ملوك الفرس - ط»
• «لطائف المعارف - ط»
• «ما جرى بين المتنبي وسيف الدولة - ط»
• «طبقات الملوك - خ»
• «الإعجاز والإيجاز - ط»
• «خاص الخاص - ط»
• «نثر النظم وحل العقد - ط»
• «مكارم الأخلاق - ط»
• «ثمار القلوب في المضاف والمنسوب - ط»
• «سر الأدب - ط»
• «الكناية والتعريض - ط» ويسمى «النهاية في الكناية»
• «المؤنس الوحيد - ط» مختارات منه
• «نثر النظم وحل العقد - ط»
• «التجنيس - خ»
• «غرر البلاغة - خ»
• «برد الأكباد - ط»
• «الأمثال - ط» واسمه «الفرائد والقلائد» من إنشائه
• «مرآة المروآت - ط»
• «الغلمان - خ»
• «تحفة الوزراء - خ»
• «أحسن المحاسن - خ»
• «أحسن ما سمعت - ط»
• «اللطائف والظرائف - ط»
• «يواقيت المواقيت - ط»
• «الشكوى والعتاب - خ» [طُبع]
• «المقصود والممدود - خ»
• «المتشابه - ط» رسالة
• «المبهج - ط»
• «التمثيل والمحاضرة - خ» طبعت منتخبات منه
• «لباب الأدب - خ» في مكتبة أسعد أفندي باستامبول (الرقم ٢٨٧٩) (١).
_________
(١) معاهد التنصيص ٣: ٢٦٦ ومفتاح السعادة ١: ١٨٧ و ٢١٣ و Brock I: ٣٣٧ S I: ٤٩٩.
وابن خلكان ١: ٢٩٠ وشذرات الذهب ٣: ٢٤٦ وآداب اللغة ٢: ٢٨٤ والفهرس التمهيدي ٢٧٥ و ٥٤٩ ومعجم المطبوعات ٦٥٦ والكتبخانة ٤: ٢٢٠. وكان مما نسب إليه كتاب «المنتحل - ط» ثم تبين أنه من تأليف عبيد الله بن أحمد المكيالي الآتية ترجمته وانظر الطبعة المعادة من كتاب «تاريخ غرر السير»: مقدمة محتبى مينوي، الصفحة ز. [ينسب الكتاب في كثير من كتب التراجم والأدب إلى أبي الفضل الميكالي ممدوح الثعالبي وصديقه الأكبر، وقد رجح د. الجارد أن يكون الكتاب من تأليفهما معاً على غرار الخالديين، وأن الأدلة مجتمعة تقود الباحث إلى طريق مسدود فيما إذا أراد أن يحدد نسبة الكتاب إلى أحد الرجلين. وفي مكتبة أيا صوفيا مخطوطة منه منسوبة إلى الميكالي، وأخرى في دار الكتب بمصر منسوبة إلى الثعالبي. (الثعالبي ناقداً وأديباً، د. محمود عبد الله الجادر صفحة ٥٨)]
نقلا عن: «الأعلام» للزركلي [مع إضافات بين معكوفين]', NULL, '0961-01-01', '1038-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('عبد القاهر البغدادي', 'مؤلف', 'عَبْد القَاهر البَغْدادي (٠٠٠ - ٤٢٩ هـ = ٠٠٠ - ١٠٣٧ م)
عبد القاهر بن طاهر بن محمد بن عبد الله البغدادي التميمي الأسفراييني، أبو منصور: عالم متفنن، من أئمة الأصول. كان صدر الإسلام في عصره. ولد ونشأ في بغداد، ورحل إلى خراسان فاستقر في نيسابور. وفارقها على أثر فتنة التركمال (قال السبكي: ومن حسرات نيسابور اضطرار مثله إلى مفارقتها !) ومات في اسفرائين. كان يدرس في سبعة عشر فنّا. وكان ذا ثروة. من تصانيفه «أصول الدين - ط» و «الناسخ والمنسوخ - خ» و «تفسير أسماء الله الحسنى - خ» و «فضائح القدرية» و «التكملة، في الحساب - خ» و «تأويل المتشابهات في الأخبار والآيات - خ» و «تفسير القرآن» و «فضائح المعتزلة» و «الفاخر في الأوائل والأواخر» و «معيار النظر» و «الإيمان وأصوله» و «الملل والنحل - خ» و «التحصيل» في أصول الفقه، و «الفرق بين الفرق - ط» و «بلوغ المدى في أصول الهدى» و «نفي خلق القرآن» و «الصفات»
نقلا عن : الأعلام للزركلي', NULL, '0429-01-01', '1037-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
