    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('الهروي، أبو ذر', 'مؤلف', 'الهروي، أبو ذر ( ٠٠٠ - ٤٣٤ هـ = ٠٠٠ - ١٠٤٣ م)
عبيد بن أحمد بن محمد بن عبد الله بن غفير، أبو ذر الأنصاري الهروي: عالم بالحديث، من الحفاظ.
من فقهاء المالكية. يقال له ابن السماك. أصله من هراة. نزل بمكة، ومات بها.
له تصانيف، منها (تفسير القرآن) و (المستدرك على الصحيحين) و (السنة والصفات) و (معجمان) أحدهما فيمن روى عنهم الحديث، والثاني فيمن لقيهم ولم يأخذ عنهم .
نقلا عن : الأعلام للزركلي', 'المذهب المالكي', '0434-01-01', '1043-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('المهلب بن أبي صفرة', 'مؤلف', 'قال الذهبي في السير:
• المُهَلَّبُ بنُ أَحْمَدَ بنِ أَبِي صُفْرَةَ أَسِيْدِ بنِ عَبْدِ اللهِ الأَسَدِيُّ الأَنْدَلُسِيُّ، المَرِيِيُّ، مُصَنِّفُ (شَرْحِ صَحِيْحِ البُخَارِيِّ).
• وَكَانَ أَحَدَ الأَئِمَّةِ الفُصحَاء، الْمَوْصُوفين بِالذَّكَاء.
• أَخذ عَنْ: أَبِي مُحَمَّدٍ الأَصِيْلِي، وَفِي الرّحلَة عَنْ أَبِي الحَسَنِ القَابِسِي، وَأَبِي الحَسن عَلِيِّ بنِ بُنْدَار القَزْوِيْنِيّ، وَأَبِي ذَرٍّ الحَافِظ.
• رَوَى عَنْهُ: أَبُو عُمَرَ بنُ الحَذَّاء، وَوصفَه بِقَوَّة الفهمِ وَبَرَاعَةِ الذِّهن.
• وحَدَّثَ عَنْهُ أَيْضاً: أَبُو عَبْدِ اللهِ بنُ عَابِد، وَحَاتِمُ بنُ مُحَمَّد.
• وَلِي قَضَاءَ المَرِيَّة.
• تُوُفِّيَ: فِي شَوَّالٍ سَنَةَ خَمْسٍ وَثَلَاثِيْنَ وَأَرْبَعِ مائَةٍ.', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('الشريف المرتضى', 'مؤلف', 'قال الذهبي في ميزان الاعتدال:
على بن الحسين [العلوي] الحسينى الشريف المرتضى المتكلم الرافضى المعتزلي، صاحب التصانيف.
حدث عن سهل الديباجي، والمرزباني، وغيرهما.
وولى نقابة العلوية، ومات سنة ست وثلاثين وأربعمائة، عن إحدى وثمانين سنة، وهو المتهم بوضع كتاب نهج البلاغة، وله مشاركة قوية في العلوم، ومن طالع كتابه نهج البلاغة جزم بأنه مكذوب على أمير المؤمنين على رضي الله عنه، ففيه السب الصراح والحط على السيدين: أبي بكر، وعمر رضي الله عنهما، وفيه من التناقض والأشياء الركيكة والعبارات التي من له معرفة بنفس القرشيين الصحابة وبنفس غيرهم ممن بعدهم من المتأخرين جزم بأن الكتاب أكثره باطل.', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
