INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('العتيقي', 'مؤلف', 'جاء في تاريخ بغداد:
أَحْمَد بْن مُحَمَّد بْن أَحْمَد بْن مُحَمَّد بْن منصور أَبُو الحسن المجهز المعروف بالعتيقي
روياني الأصل، ولد ببغداد وبكر بِهِ في سماع الحديث من علي بْن مُحَمَّد بْن أَحْمَد بْن كيسان النحوي، وإسحاق بْن سعد النسوي، وعلي بْن مُحَمَّد بْن سعيد الرزاز، وَالحسين بْن مُحَمَّد بْن عبيد الدقاق، وإبراهيم بْن أَحْمَد بْن جعفر الخرقي، وعبد العزيز بْن جعفر الخرقي، وأبي حفص الزيات، وأبي العباس عَبْد اللَّه بْن موسى الهاشمي، وأبي القاسم الداركي، وأبي بكر الأبهري، ومحمد بْن المظفر، وأبي حفص بْن شاهين، وأبي عمر بْن حيويه، ونحوهم.
كتبت عنه، وكَانَ صدوقا، وسألته عَن مولده فقال: ولدت صبيحة يوم الخميس التاسع عشرة من المحرم سنة سبع وستين وثلاث مائة، قلت له: فالعتيقي نسبه إلى أيش؟ فقال: بعض أجدادي كَانَ يسمى عتيقا فنسبها إليه.
سمعت أبا القاسم الأزهري ذكر أبا الحسن العتيقي، فأثنى عَلَيْهِ خيرا ووثقه.
مات العتيقي سحر يوم الثلاثاء الحادي وَالعشرين من صفر سنة إحدى وأربعين وأربع مائة، وصلينا عَلَيْهِ في ضحى ذلك اليوم بباب مسجد ابن المبارك، وأمنا القاضي أَبُو الحسين بْن المهتدى بالله، ودفن في مقبرة الشونيزي.', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
