INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('الماوردي', 'مؤلف', 'الماوردي، أبو الحسن (٣٦٤ -٤٥٠هـ ، ٩٧٤- ١٠٥٨م).
أبو الحسن علي بن محمد بن محمد بن حبيب البصري البغدادي، الشهير بالماوردي. مفكر إسلامي. من وجوه فقهاء الشافعية وإمام في الفقه والأصول والتفسير، وبصير بالعربية. كان من رجال السياسة البارزين في الدولة العباسية وخصوصًا في مرحلتها المتأخرة.
نشأ الماوردي بالبصرة، وتعلّم وسمع الحديث من جماعة من العلماء، وتولى القضاء في كورة (أستوا) من ناحية نيسابور، ولقب بأقضى القضاة عام ٤٢٩هـ. تألق نجم الماوردي عند عودته إلى بغداد وقيامه بالتدريس، ولكن نجمه السياسي برز عندما عمل سفيرًا بين رجالات الدولة في بغداد وبني بويه في الفترة بين عامي ٣٨١ و ٤٢٢هـ، لحل الخلافات الناشبة بين أقطار الدولة العباسية.
اشتهر الماوردي بكثرة التأليف وغزارة الإنتاج، ولكن لم يصل إلينا من مؤلفاته إلا القليل. ويمكن تصنيف مؤلفاته في مجموعات دينية ولغوية وأدبية وسياسية واجتماعية. ومن أبرزها: أدب الدنيا والدين؛ أعلام النبوة؛ الحاوي الكبير؛ الإقناع وهو مختصر لكتاب الحاوي الكبير.
ومن أشهر كتبه في مجال السياسة قوانين الوزارة وسياسة الملك؛ نصيحة الملوك؛ تسهيل النظر وتعجيل الظفر؛ الأحكام السلطانية الذي يُعد من أشهر كتب الماوردي وأعظمها أثرًا.
نقلا عن
الموسوعة العربية العالمية http://www.mawsoah.net', 'المذهب الشافعي', '0974-01-01', '1058-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


