INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('ابن باديس، المعز', 'مؤلف', 'المُعِزّ بن بادِيس (٣٩٨ - ٤٥٤ هـ = ١٠٠٨ - ١٠٦٢ م)
المعز بن باديس بن المنصور التَّميمي الصنهاجي: من ملوك الدولة الصنهاجية بإفريقية. ولد بالمنصورية (من أعمال إفريقية) وولي بعد وفاة أبيه (سنة ٤٠٦ هـ) وأقره الحاكم الفاطمي (صاحب مصر والمغرب) ولقبه بشرف الدولة. وساد الأمن في أيامه. وبنى بنايات ومساجد أنفق عليها أموالا وافرة، وقرب العلماء وأكرمهم. ونشبت بينه وبين قبائل زناتة حروب انتصر في جميعها.
وكانت خطبته للفاطميين، فقطعها (سنة ٤٤٠) وجعلها للعباسيين، فوجه إليه المستنصر الفاطمي أعراب بني هلال وبني سليم من قبائل الحجاز، وأباح لهم الغارة على المغرب، فاحتلوا القيروان.
وحاربهم المعتز فتغلبوا عليه، فتقهقر إلى المهدية. واستمر وادعا إلى أن توفي فيها من ضعف الكبد. وهو أول من حمل الناس بإفريقية على مذهب مالك وكان الأغلب عليهم مذهب أبي حنيفة
نقلا عن: الأعلام للزركلي', NULL, '1008-01-01', '1062-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


