INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('ابن حزم', 'مؤلف', 'ابن حَزْم (٣٨٤ - ٤٥٦ هـ = ٩٩٤ - ١٠٦٤ م)
علي بن أحمد بن سعيد بن حزم الظاهري، أبو محمد
• عالم الأندلس في عصره، وأحد أئمة الإسلام.
• كان في الأندلس خلق كثير ينتسبون إلى مذهبه، يقال لهم «الحزْمية».
• ولد بقرطبة. وكانت له ولأبيه من قبله رياسة الوزارة وتدبير المملكة، فزهد بها وانصرف إلى العلم والتأليف، فكان من صدور الباحثين فقيها حافظا يستنبط الأحكام من الكتاب والسنة، بعيدا عن المصانعة. وانتقد كثيرا من العلماء والفقهاء، فتمالأوا على بغضه، وأجمعوا على تضليله وحذروا سلاطينهم من فتنته، ونهوا عوامهم عن الدنو منه، فأقصته الملوك وطاردته، فرحل الى بادية ليلة (من بلاد الأندلس) فتوفي فيها.
• رووا عن ابنه الفضل أنه اجتمع عنده بخطه أبيه من تآليفه نحو ٤٠٠ مجلد، تشتمل على قريب من ثمانين ألف ورقة. وكان يقال: لسان ابن حزم وسيف الحجاج شقيقان.
أشهر مصنفاته:
• «الفصل في الملل والأهواء والنحل - ط»
• وله «المحلى - ط» في ١١ جزءا، فقه
• و «جمهرة الأنساب - ط»
• و «الناسخ والمنسوخ - ط»
• و «حجة الوداع - ط» غير كامل
• و «ديوان شعر - خ» جزء منه - ذكر في حجة الوداع ١٤٦ الهامش -
• و «جوامع السيرة - ط» ومعه خمس رسائل له
• و «التقريب لحدّ المنطق والمدخل إليه - ط»
• و «مراتب العلوم - خ» رسالة في الرباط (٢٠٩ ق) [طُبع]
• و «الإعراب - خ» ٢١٤ ورقة كتب سنة ٧٦١ في شستربتي (٣٤٨٢) [طُبع]
• و «ملخص إبطال القياس - ط» حققه الأفغاني ورجح نسبته إلى ابن حزم
• و «فضائل الأندلس - ط»
• و «أمهات الخلفاء - ط»
• و «رسائل ابن حزم - ط»
• و «الأحكام لأصول الأحكام - ط» ثماني مجلدات
• و «إبطال القياس والرأي - خ»
• و «المفاضلة بين الصحابة - ط» رسالة مما اشتمل عليه كتاب «الفصل» المتقدم ذكره، نشرها سعيد الأفغاني
• و «مداواة النفوس - ط» رسالة في الأخلاق
• و «طوق الحمامة - ط» أدب، وغير ذلك
وللدكتور عبد الكريم خليفة «ابن حزم الأندلسي - ط» (١).
_________
. (١) نفح الطيب ١: ٣٦٤ وسير النبلاء - خ. المجلد الخامس عشر. وآداب اللغة ٣: ٩٦ وأخبار الحكماء ١٥٦ وإرشاد الأريب ٥: ٨٦ - ٩٧ ولسان الميزان ٤: ١٩٨ وابن بسام في الذخيرة: المجلد الأول من القسم الأول ١٤٠ وفيه كلام لابن حيان، يحط به من ابن حزم، وينال من علمه ومكانته. وبغية الملتمس ٤٠٣ وفيه: «أصله من الفرس، وأول من أسلم من أسلافه جدّ له يدعى يزيد كان مولى ليزيد بن أبو سفيان» وابن خلكان ١: ٣٤٠ وللمستشرق أرندنك van Arendonk C. في دائرة المعارف الإسلامية ١: ١٣٦ - ١٤٤ بحث مفيد في ترجمته.
اللباب ١: ٢٩٧ والتبيان - خ. وفيه: «مات ابن حزم مبعدا عن سكنه مشردا عن وطنه من قبل الدولة». وجذوة المقتبس ٢٩٠ ومجلة المقتبس ١: ٢ و ٩٦ ويستفاد من الإعلام بتاريخ الإسلام - خ. لابن قاضي شهبة، حوادث سنة ٤٥٦ أن كتب ابن حزم لم يخرج أكثرها من بيته - في أيامه - لزهد الفقهاء فيها، وأن بعضها أحرق ومزق علانيه بإشبيلية. وفي «المغرب في حلى المغرب» ٣٥٤ ما محصله: «ابن حزم، من أهل قرية الزاوية، من قرى أونبة بالاندلس، كان جده حزم من موالي بني أميه، فارسي الاصل، اشتغل بالفلسفة، وقيل: إنه زل وضل فأقصاه الملوك، وكان متشيعا لبني أمية منحرفا عمن سواهم من قريش» و «المخطوطات المصورة»، القسم ٢ من الجزء ٢ ص ١٧٠.
نقلا عن: «الأعلام» للزركلي [مع إضافات بين معقوفين]', NULL, '0994-01-01', '1064-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
