INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('الهذلي، أبو القاسم', 'مؤلف', 'أبو القاسم الهُذَلي (٤٠٣ - ٤٦٥ هـ = ١٠١٢ - ١٠٧٣ م)
هو يوسف بن علي بن جبارة بن محمد بن عقيل بن سواده أبو القاسم الهذلي اليشكري المغربي
قال الزركلي في الأعلام:
متكلم، عالم بالقراآت المشهورة والشاذة. كان ضريرا. من أهل بسكرة بإقليم الزاب الصغير. رحل إلى أصبهان وبغداد. وقرره نظام الملك مقرئا في مدرسته بنيسابور (سنة ٤٥٨) فاستمر الى أن توفي. من كتبه «الكامل» في القراآت، ذكر فيه أنه لقي من الشيوخ ٣٦٥ شيخا من آخر ديار الغرب إلى باب فرغانة
وقال المرصفي في هداية القاري:
الأستاذ الكبير والعلم الشهير الجوال. ولد في حدود التسعين وثلثمائة تخميناً وطاف البلاد في طلب القراءات فلا أعلم أحداً في هذه الأمة رحل في القراءات رحلته ولا لقي من لقي من الشيوخ قال في كتابه «الكامل» فجملة من لقيت في هذا العالم ثلثمائة وخمسة وستون شيخاً من آخر المغرب إلى باب فرغانة يميناً وشمالاً وجبلاً وبحراً ولو علمت أحداً تقدم علي في هذه الطبقة في جميع بلاد الإسلام لقصدته قال: وألفت هذا الكتاب فجعلته جامعاً للطرق المتلوة والقراءات المعروفة ونسخت به مصنفاتي كالوجيز والهادي قلت: كذا ترى همم السادات في الطلب وكانت رحلته في سنة خمس وعشرين وبعدها.
قال الأمير ابن ماكولا: كان يدرس علم النحو ويفهم الكلام وذكره عبد الغافر ونعته بأنه ضرير فيحتمل أنه عمي في آخر عمره وكان قد قرره الوزير نظام الدين في مدرسته بنيسابور فقعد سنين وأفاد وكان مقدماً في النحو والصرف', NULL, '1012-01-01', '1073-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


