    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('الحداد المهدوي', 'مؤلف', 'أبو الحسن علي بن محمد بن ثابت الخولاني المعروف (بالحداد المهدوي) لأنه ينسب إلى (المهدية) في تونس، كان من القراء المعروفين، وكان شاعرا، وصل إلينا من شعره:
قالتْ وأبدتْ صفحةً … كالشمس من تحت القناعِ
بعتَ الدفاترَ وهي آ … خر ما يبُاع من المتاعِ
فأجبتُها ويدي على … كبدي وهمَّت بانصداعِ
لا تعجبي مما رأيـ … ـتِ فنحن في زمن الضياعِ
له من الكتب:
- الإشارة في النحو: مقدمة في علم النحو له عليها شرح
- حصر حرف الظاء: حصر فيه الكلمات التي فيها حرف الظاء
- المفيد في معرفة التحقيق والتجويد: نقل عنه السيوطي في (الأشباه والنظائر)
(التعريف مقتبس من مقدمة د / حاتم الضامن لكتاب «حصر حرف الظاء»)', NULL, NULL, NULL, NOW(), NOW())
