INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('أبو الرجاء الجركاني', 'مؤلف', 'أبو رجاء محمد بن أحمد بن محمد بن عبد الله الجركاني المفيد من أهل أصبهان
كان مفيد أصبهان في عصره وكان حريصا على سماع الحديث وطلبه مكثرا منه سمع أبا طاهر محمد بن أحمد بن عبد الرحيم الكاتب وأبا الفتح منصور بن الحسين بن علي الكاتب وأبا الفضل عبد الرحمن بن أحمد الرازي المقرئ وأبا بكر أحمد بن الفضل الباطرقاني وجماعة كثيرة كتب إلي الإجازة بجميع مسموعاته ومجازاته في سنة ثمان وخمسمئة ومن جملة مسموعاته كتاب العتق والمدبر والمكاتب لأبي الشيخ بروايته عن أبي طاهر الكاتب عنه وكتاب الأمثال لأبي عروبة الحراني بروايته عن أبي طاهر بن عبد الرحيم عن ابن المقرئ عنه وكتاب السنة لأبي مسعود الرازي بروايته عن أبي المظفر بن شبيب عن جده أبي بكر ابن أبي زكريا عن الفضل بن الحصيب عنه وكتاب الناسخ والمنسوخ تأليف أبي الحسن روح بن عبد المؤمن بروايته عن عبد الرازق بن همزجي عن أبي بكر ابن المقرىء عن أبي يعلى الموصلي عنه وكتاب الأسامي والكنى لأبي عمرو خليفة بن خياط المعروف بشباب يرويه عن عبد الرزاق بن همزجي عن أبي بكر ابن المقرئ عن أبي حفص الأهوازي عنه وكتابا في معاني قول النبي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أنزل القرآن على سبعة أحرف لأبي الفضل الرازي بروايته عنه وأحاديث مسعر بن كدام لأبي عروبة الحراني بروايته عن أبي الفتح بن القاسم عن ابن المقرئ عنه وكتاب اللباس لأبي أحمد إسماعيل بن يزيد القطان بروايته عن أحمد بن الفضل الباطرقاني عن أبي علي الحسن بن أحمد بن محمد بن داود التاجر الباطرقاني عن أبي عبد الله محمد بن أحمد بن أبي يحيى الزهري عنه وتوفي يوم الخميس الثاني والعشرين من شهر رمضان سنة أربع عشرة وخمسمئة ودفن يوم الجمعة بالمصلي
