    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('هبة الله ابن الأكفاني المحدث', 'مؤلف', 'هبة الله ابن الأكفاني (٤٤٤ - ٥٢٤ هـ = ١٠٥٢ - ١١٢٩ م)
أبو محمد، هبة الله بن أحمد بن محمد بن هبة الله، الأمين، الأنصاري الدمشقيّ، ابن الأكفاني:
من حفاظ الحديث. له عناية بالتأريخ. وهو شافعيّ، كان من كبار العدول.
قال ابن قاضي شهبة: محدث دمشق، كتب ما لم يكتبه أحد من أبناء زمنه بالشام. قلت: وهو الّذي روى «وفيات ابن الحبال - خ» وفي مقدمتها: «أنبأنا. السلفي أن الشيخ الأمين أبا محمد هبة الله بن أحمد ابن الأَكْفَاني أخبرهم بدمشق قال: كتب إليّ أبو إسحاق إبراهيم بن سعيد بن عبد الله الحافظ المعروف بالحبال من مصر هذه الوفيات من جمعه عمّا ثبت عنده .. إلخ» وكانت وفاته في دمشق
[وفي «الأنساب» للسمعاني: (الأكفاني) بفتح الألف وسكون الكاف وفتح الفاء وفي آخرها النون: هذه النسبة إلى بيع الأكفان].
نقلا عن: الأعلام للزركلي', NULL, '1052-01-01', '1129-01-01', NOW(), NOW())
