INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('زاهر الشحامي', 'مؤلف', 'جاء في المستفاد من ذيل تاريخ بغداد:
زاهر بن طاهر بْنُ مُحَمَّدِ بْنِ مُحَمَّدِ بْنِ أَحْمَدَ بْنِ مُحَمَّد بْن يوسف بن محمد ابن المرزبان بن علي بن عبد الله بن المرزبان الشحامي، أبو القاسم بن أبي عبد الرحمن بن أبي بكر المستملي:
من أهل نيسابور- شيخ وقته في علو الإسناد، بكر به أبوه فأسمعه من أبي سعد محمد بن عبد الرحمن الكنجروذي وأبي عثمان سعيد بن محمد النجيرمي وأبي سعد أحمد بن إبراهيم المقرئ وأبي القاسم عبد الكريم بن هوازن القشيري وأبي عثمان سعيد بن أحمد العيار وأبي بكر أحمد بن الحسين البيهقي في آخرين. وسمع بنفسه وجمع لنفسه مشيخة. وكان يستملى على الشيوخ، وحدث بالكثير، وكتب عنه الحفاظ. قدم بغداد في سنة خمس وعشرين وخمسمائة، وحدّث بها، سمع منه ابن ناصر في آخرين.
أخبرنا شهاب الحاتمي بهراة، قال: حدثنا أبو سعد بن السمعاني قال: زاهر بن طاهر الشحامي أبو القاسم شيخ متيقظ مكثر، جمع ونسخ بخطه، وكان صاحب أصول، وعمّر حتى حمل عنه الكثير، ورحل في رواية الحديث ونشره مثل ما يرحل الطلاب في جمعه، ورد علينا مرو قاصدا للرواية بها وحجّ، وسمع منه الكثير ببغداد وهمذان والري والحجاز، ورجع إلى نيسابور؛ وكان صبورا لا يضجر من القراءة عليه حتى قرأت عليه «تاريخ نيسابور» للحاكم أبي عبد الله في أيام قلائل، كنت أمضي قبل طلوع الشمس فأقرأ إلى وقت غروبها، وكان يقعد ويستمع، ولكنه كان يخل بالصلوات إخلالا ظاهرا، ووقت خروجه إلى أصبهان قال لي أخوه وجيه: أجهدت في قعوده ولا تخرج، فإن أمر صلاته مختل، ونفتضح من أهل أصبهان! فظهر الأمر كما قال أخوه، وعرف أهل أصبهان ذلك، وشنعوا عليه حتى ترك أبو الْعَلاءِ أَحْمَدَ بْنَ مُحَمَّدِ بْنِ الْفَضْلِ الْحَافِظَ الرواية عنه. وقيل لزاهر في ذلك، فقال: لي عذر، وأنا أجمع بين الصلوات كلها. ولعله تاب ورجع عن ذلك في آخر عمره. وكان صحيح السماع كثيره.
مولده رابع عشر ذي القعدة سنة ست وأربعين وأربعمائة.
وتوفي ليلة الرابع عشر من ربيع الآخر سنة ثلاث وثلاثين وخمسمائة بنيسابور.
ودفن بمقبرة يحيى بن يحيى- رحمه الله تعالى وإيانا.', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('ابن باجه', 'مؤلف', 'ابن باجه ( ٠٠٠ - ٥٣٣ هـ = ٠٠٠ - ١١٣٩ م)
محمد بن يحيى بن باجه، وقد يعرف بابن الصائغ، أبو بكر التجيبى الأندلسي السرقسطى: من فلاسفة الإسلام.
ينسب إلى التعطيل ومذهب الحكماء. ولد في سرقسطة، واستوزره أبو بكر بن إبراهيم والي غزناطة ثم سرقسطة. وذهب إلى فاس فاتهم بالإلحاد، ومات فيها، قيل: مسموما، قبل سن الكهولة. والإفرنج يسمونه (Avenpace)حمل عليه الفتح بن خاقان (في قلائد العقيان) حملة شديدة. وكان مع اشتغاله بالفلسفة والطبيعيات والفلك والطب والموسيقى، شاعراً مجيدا، عارفا بالأنساب. شرح كثيرا من كتب أرسطاطاليس وصنف كتبا ذكرها ابن أبى أصيبعة (في طبقات الأطباء) ضاع أكثرها وبقى ما ترجم منها إلى اللاتينية والعبرية. ومما بقي من كتبه (مجموعة في الفلسفة والطب والطبيعيات - خ) و (رسالة الوداع - ط) مع رسالتين من تأليفه، هما (اتصال العقل) و (النبات) وكتاب (النفس - ط) و (تعليق على كتاب العبارة للفار أبي - خ) من إملائه،
و (تعليق على كتاب الفارابى في القياس - خ) من تأليفه كلاهما في دار الكتب، مصوران عن الاسكوريال (٦١٤ / ٤ و ٢١٢ / ٥) كما في المخطوطات المصورة (١: ٢٠٣)
نقلا عن : الأعلام للزركلي', NULL, '0533-01-01', '1139-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


