INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('النيسابوري، أبو البركات', 'مؤلف', 'جاء في تاريخ دمشق لابن عساكر:
إسماعيل بن أحمد بن محمد أبو البركات بن أبي سعد الصوفي المعروف بشيخ الشيوخ
كان أبوه من أهل نيسابور واستوطن بغداد وولد له أبو البركات بها وسمع أبو البركات محمدا الكوفي وأبا علي إسماعيل بن علي الجاجرمي وأبا الخطاب نصر بن البطر وأبا القاسم عبد العزيز بن علي بن أحمد بن بنت السكري وأبا نصر وأبا الفوارس الزينبيين وأبا منصور بن العطار وأبا محمد رزق الله بن عبد الوهاب ومالكا البانياسي وأبا القاسم علي بن مسعدة الجرجاني وأبو الفضل بن خيرون وأبا بكر الطريثيثي كتبت عنه شيئا يسيرا وكان قدم دمشق لزيارة بيت المقدس ونزل في دويرة السميساطي. . .
حدثنا أبو سعد بن السمعاني قال سألت شيخ الشيوخ أبا البركات عن مولده فقال في جمادى الآخرة سنة خمس وستين وأربعمائة ومات ليلة الثلاثاء التاسع عشر من جمادى الأولى سنة إحدى وأربعين وخمسمائة ببغداد', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
