INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('النيسابوري، بيان الحق', 'مؤلف', 'النيسابوري، بيان الحق (المتوفى بعد ٥٥٣ هـ)
مفسر لغويّ، له تصانيف منها «باهر البرهان فى معانى مشكلات القرآن» و «إيجاز البيان في معاني القرآن» و «خلق الإنسان» و «جمل الغرائب» في غريب الحديث
• نشأ على أرض نيسابور
• ورحل إلى غزنة، ولعله ألف كتابه «باهر البرهان» فيها إذ يقول فيه «قال بعض كتاب هذه الدولة» يعني الدولة الغزنوية
• وبعد أن استولى علاء الدين الغوري على غزنة في ٥٤٨ هـ، ونكل بأهلها وعلمائها، رحل المؤلف عنها متجها إلى «الخجندة» وظل فيها حتى عام ٥٥٣ هـ حيث فرغ ذلك العام من تأليف كتابه «إيجاز البيان» بها
• ثم رحل إلى حلب ثم دمشق واستقر بها حتى مات
• ولا ريب أن هذا التنقل (إلى حلب ودمشق) استغرق زمنا، فغالب الظن أن حياته امتدت إلى ما بعد ٥٥٣ هـ بسنوات ليست قليلة
(التعريف بالمؤلف مستفاد - كله - من مقدمة د سعاد بابقي في تحقيق كتاب «باهر البرهان»)', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


