INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('بنيامين التطيلي', 'مؤلف', 'الرابي بنيامين بن الرابي يونة التطيلي النباري
عالم ورحّالة يهودي أسباني توفي في سنة ١١٧٣ م / ٥٦٩ هـ.
على كثرة ما عالج المؤرخون رحلة بنيامين بحثاً وتمحيصاً، ودققوا النظر في محتوياتها، وراجعوا حوادثها وقايسوا بين نصوصها المخطوطة والمطبوعة، لم يتوصلوا إلى ما يلقي الضوء على سيرة هذا الرحالة الكبير ومولده ونشأته ومركزه العلمي والاجتماعي. وكل ما يعرف عنه مأخوذ عن المقدمة الوجيزة التي صدر بها الرحلة كاتب مجهول الهوية، ربما كان معاصراً لبنيامين، لأنها وردت في أقدم النسخ المعروفة للرحلة. وقد جاء في هذه المقدمة أنه: «الرابي بنيامين بن الرابي يونة التطيلي النباري» وأنه «جاب المدن البعيدة وسجّل ما شاهده عياناً في الأمصار التي مر بها أو ما نقله عن الثقات ذوي الأمانة المعروفين لدى يهود أسبانية» وبالأخير «إنه دوّن هذا الكتاب عند أوبته إلى قشطالة سنة ٤٩٣٣ للخليقة» (٥٦٩ هـ- ١١٧٣ م) وفي رواية أنه توفي في السنة نفسها. ويستمر صاحب المقدمة في تعريفنا بهذا الرحالة ويقول: «إنه كان من الثقات العارفين بالتوراة والشرع، وأن التدقيق والتمحيص قد أيدا ما رواه في رحلته» . أما المؤرخون من القرن الثالث عشر وما والاه فيكتفون بتسميته بنيامين صاحب الرحلة.
فهل كان بنيامين من علماء اليهود الذين ازدهر بهم القرن الثاني عشر في أسبانية الإسلامية والنصرانية؟ إننا نشك في ذلك. لأن كتب الأنساب اليهودية الخاصة بذلك الجيل، التي سجلت بإسهاب تراجم جميع العلماء المعروفين وفصلت ذكر مؤلفاتهم وآثارهم العلمية والأدبية، لا تذكر اسم بنيامين إلا مقروناً بهذه الرحلة. وأغلب الظن أن هذا الرجل كان وجيهاً من وجهاء اليهود في قشطالة، بل تاجراً تعنيه الشؤون الاقتصادية، بدلالة هذا الاهتمام الفريد الذي يبديه في الأحوال التجارية للبلدان التي زارها، أكثر من اهتمامه بالعلماء الكبار الذين عرفهم في أثناء تجواله.
وصفوة القول عن بنيامين: إنه كان تاجراً وإنه يجمع إلى إلمامه بالاقتصاد وفنون التجارة إلماما كافيا بالتوراة والتلمود، كما هو شأن الكثيرين من أمثاله في ذلك العصر الذي كانت العلوم الدينية وحدها تميز المتعلّم عن الأمي، وإنه خرج في رحلته هذه بدافع الاطلاع الشخصي، ووجهته بالدرجة الأولى الشرق الإسلامي, هذا الشرق الذي استهوت خيراته وعمرانه وتجارته عدداً غير يسير من الأوروبيين خلال العصور المتوسطة والأخيرة.', NULL, '0569-01-01', '1173-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('عمارة اليمني', 'مؤلف', 'عمارة اليمني (٠٠٠ - ٥٦٩ هـ = ٠٠٠ - ١١٧٤ م)
عمارة بن علي (أبي الحسن) بن زيدان الحكمي المذحجي اليمني، أبو محمد، نجم الدين: مؤرخ ثقة، وشاعر فقيه أديب، من أهل اليمن. ولد في تهامة ورحل إلى زبيد سنة ٥٣١ هـ وقدم مصر برسالة من القاسم بن هشام (أمير مكة) إلى الفائز الفاطمي سنة ٥٥٠هـ في وزارة «طلائع ابن رزيك» فأحسن الفاطميون إليه وبالغوا في إكرامه، فأقام عندهم، ومدحهم. ولم يزل مواليا لهم حتى دالت
دولتهم وملك السلطان «صلاح الدين» الديار المصرية، فرثاهم عمارة واتفق مع سبعة من أعيان المصريين على الفتك بصلاح الدين، فعلم بهم فقبض عليهم وصلبهم بالقاهرة، وعمارة في جملتهم. له تصانيف، منها «أرض اليمن وتاريخها - ط» و «النكت العصرية، في أخبار الوزراء المصرية - ط» وفيه كثير من أخباره، تحدث بها عن نفسه، وقصائد ومختارات أوردها من شعره ونثره،
في مجلدين ضخمين، نشرهما المستشرق «هرتويغ درنبرغ» كما سمى نفسه بالعربية، وهو Hartwig Derenbourg وأتبعهما بمجلد، بالفرنسية، في سيرته وأخباره سماه son Oeuvre oumara du Yemen و «المفيد في أخبار زبيد - خ» رأيته بجدة عند بائع كتب يمني، لعله المسمى أيضا «مختصر المفيد في أخبار زبيد» المخطوط في شستربتي (٥٢٢٣)، ولعمارة «ديوان شعر - خ» جمعه أحد الأدباء ورتبه على الحروف، منه نسخة غير تامة، في دار الكتب المصرية (٥٣٠٣ أدب).
نقلا عن : الأعلام للزركلي', NULL, '0569-01-01', '1174-01-01', NOW(), NOW())
