INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('أبو القاسم بن الفراء', 'مؤلف', 'جاء في تاريخ الإسلام للذهبي:
عُبَيْد الله بن علي بن محمد بن محمد بن الحسين ابن الفرّاء، أبو القاسم بن أبي الفرج بن أَبِي خازم ابْن القاضي أَبِي يَعْلَى البغدادي، الحنبلي. [المتوفى: ٥٨٠ هـ]
سمعه أَبُوهُ الكثير من أَبِي منصور عَبْد الرَّحْمَن القَزَّاز، وأبي منصور بْن خيرون، وأبي عَبْد اللَّه السلال، وأبي الْحَسَن بْن عَبْد السلام. وطلب هُوَ بنفسه، وأكثر عَن أصحاب عاصم بْن الْحَسَن، وطِراد، وبالغ حتى سمع من أصحاب ابْن الحُصَيْن. وكتب وحصل الأصول.
قال ابْن النجار: وكانت داره مجمعًا لأهل العِلم والشيوخ، وينفق عليهم ويتكرَّم. وكان لطيفًا حَسَن الأخلاق ذا مروءة. قرأ الفقه وشهد عند القضاة، ثم عُزِل لما ظهرت منه أشياء لَا تليق بأهل الدين قبل موته بقليل، سمع منه ابْن الأخضر، وكان يصفه بالسخاء والعطاء، وقال لي ابْن القطيعي: كان عَدْلًا فِي روايته ضعيفًا فِي شهادته، مات سنة ثمانين فِي آخرها. مرض بالفالج أسبوعًا. ومولده سنة سبْعٍ وعشرين.
قلت: رَوَى عَنْهُ الشَّيْخ الموفق وقال: كان آخر مَن بقي مِن ذرية القاضي أَبِي يَعْلَى ممن لَهُ حشمة وجاه ومنصب. وكان لَهُ دار واسعة، وعنده أكثر كتب أَبِي يَعْلَى، ثم افتقر فباع أكثرها.', 'المذهب الحنبلي', NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
