INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('أبو اليمن الكندي', 'مؤلف', 'أَبُو اليُمْن الكِنْدي (٥٢٠ - ٦١٣ هـ = ١١٢٦ - ١٢١٧ م)
زيد بن الحسن بن زيد بن سعيد الحميري، من ذي رعين، أبو اليمن، تاج الدين الكندي: أديب، من الكتاب الشعراء العلماء. ولد ونشأ ببغداد. وسافر إلى حلب سنة ٥٦٣ هـ وسكن دمشق، وقصده الناس يقرأون عليه. وكان مختصا بفرخ شاه ابن أخي صلاح الدين، وبولده الملك الأمجد صاحب بعلبكّ. وهو شيخ المؤرخ سبط ابن الجوزي. وكان الملك المعظم (عيسى) يقرأ عليه دائما كتاب سيبويه، متنا وشرحا، والإيضاح والحماسة وغيرهما. قال أبو شامة: كان المعظم يمشي من القلعة راجلا إلى دار تاج الدين، والكتاب تحت إبطه. واقتنى مكتبة نفيسة. وتوفي في دمشق. له تصانيف، منها كتاب شيوخه على حروف المعجم، كبير، و (شرح ديوان المتنبي) و (ديوان شعر)
نقلا عن: الأعلام للزركلي', NULL, '1126-01-01', '1217-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('ابن ظافر الأزدي', 'مؤلف', 'ابن ظافر (٥٦٧ - ٦١٣ هـ = ١١٧١ - ١٢١٦ م)
علي بن ظافر بن حسين الأزدي الخزرجي، أبو الحسن جمال الدين: وزير مصري، من الشعراء الأدباء المؤرخين
مولده ووفاته في القاهرة، ولي وزارة الملك الأشرف مدة، وصرف عنها، فولي وكالة بين المال، ثم اعتزل الأعمال، من كتبه «بدائع البدائه - ط» و«الدول المنقطعة - خ» أربعة أجزاء، قال ابن قاضي شهبة: وهو كتاب مفيد في بابه جدا، و «ذيل المناقب النورية - خ» و «شفاء الغليل في ذم الصاحب والخليل» اختصره السيوطي وسماه «الشهاب الثاقب في ذم الخليل والصاحب - ط» رسالة و «أساس السياسة» و «أخبار ملوك الدولة السلجوقية» و «أخبار الشجعان - خ» وغير ذلك. وشعره رقيق
