INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('عبد اللطيف البغدادي', 'مؤلف', 'عبد اللطيف البَغْدادي (٥٥٧ - ٦٢٩ هـ = ١١٦٢ - ١٢٣١ م)
عبد اللطيف بن يوسف بن محمد بن علي البغدادي، موفق الدين، ويعرف بابن اللباد، وبابن نقطة: من فلاسفة الإسلام، وأحد العلماء المكثرين من التصنيف في الحكمة وعلم النفس والطب والتاريخ والبلدان والأدب. مولده ووفاته ببغداد.
أقام مدة بحلب، وزار مصر والقدس ودمشق وحران وبلاد الروم وملطية والحجاز وغيرها.
وحظي عند الملوك والأمراء. وكان دميم الخلقة قليل لحم الوجه، قويّ الحافظة. له من الآثار «الإفادة والاعتبار بما في مصر من الآثار - ط» رسالة، و «قوانين البلاغة» و «الإنصاف بين ابن بري وابن الخشاب» في كلامهما على المقامات، و «الجامع الكبير» في المنطق الطبيعي والالهي، عشر مجلدات، و «بلغة الحكيم» و «الكلمة في الربوبية» و «الحكمة الكلامية» و «تهذيب كلام أفلاطون» و «القياس» أربع مجلدات، و «السماع الطبيعي» و «غرب الحديث» و «المغني الجلي
- خ» في الحساب، و «التجريد - خ» في اللغة، و «ملخص مقالات التاج - خ» في الحلية النبويّة، و «ذيل الفصيح - ط» لثعلب، و «شرح أحاديث ابن ماجة المتعلقة بالطب» واختصر كتبا كثيرة، منها الحيوان للجاحظ، وكتاب في النبات، وكتب رحلات وصف بها أسفاره والبلدان التي زارها. وله رسائل صغيرة سماها «مقالات» منها «النفس» و «العلم الإلهي» و «الماء» و «الحركات المعتاصة» و «العادات» و «حقيقة الدواء والغذاء» و «الحواس» و «النفس والصوت والكلام» و «المدينة الفاضلة» و «العلوم الضارة» و «تزييف ما يعتقده ابن سينا» و «إبطال الكيمياء» و «اللغات وكيفية تولدها» و «القدر»
نقلا عن: الأعلام للزركلي', NULL, '1162-01-01', '1231-01-01', NOW(), NOW())
