INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('المنتجب الهمذاني', 'مؤلف', 'المُنْتَجَب (٠٠٠ - ٦٤٣ هـ = ٠٠٠ - ١٢٤٥ م)
المُنْتَجَب بن أبي العز بن رشيد، أبو يوسف، مُنْتَجَب الدين الهمذاني: عالم بالعربية والقراآت. اشتهر وتوفي بدمشق.
