INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('ابن الأبار', 'مؤلف', 'ابن الأبار (٥٩٥ - ٦٥٨ هـ = ١١٩٩ - ١٢٦٠ م)
محمد بن عبد الله بن أبي بكر القضاعي البلنسي، أبو عبد الله، ابن الأبار: من أعيان المؤرخين، أديب.
من أهل بلنسية (بالأندلس) ومولده بها.
رحل عنها لما احتلها الإفرنج، واستقر بتونس فقربه صاحبها السلطان أبو زكرياء، وولاه كتابة (علامته) في صدور الرسائل، مدة، ثم صرفه عنها، وأعاده.
ومات أبو زكرياء وخلفه ابنه المستنصر، فرفع هذا مكانته.
ثم علم المستنصر أن ابن الأبار كان يزري عليه في مجالسه، وعزيت إليه أبيات في هجائه، فأمر به فقتل (قعصا بالرماح) في تونس.
من كتبه (التكملة لكتاب الصلة - ط) في تراجم علماء الأندلس، و (المعجم - ط) في التراجم، و (الحلة السيراء - ط) في تاريخ أمراء المغرب، و (إعتاب الكتاب - ط) في أخبار المنشئين، و (إيماض البرق في أدباء الشرق) و (الغصون اليانعة في محاسن شعراء المائة السابعة - ط) و (مظاهرة المسعى الجميل ومحاذرة المرعى الوبيل - ط) في معارضة ملقى السبيل، للمعري، و (تحفة القادم) نشرت مجلة المشرق مختصرا له، و (درر السمط في خبر السبط - خ) في الرباط (٢٠٨١ ك) ينال فيه من بني أمية.
وله شعر رقيق. ولعبد العزيز عبد المجيد كتاب (ابن الأبار، حياته وكتبه - ط) يرجع إليه .
نقلا عن : الأعلام للزركلي', NULL, '1199-01-01', '1260-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
