INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('ناصر الدين ابن المنير السكندري', 'مؤلف', 'ابن المنير (٦٢٠ - ٦٨٣ هـ)
جاء في «فوات الوفيات» ما مُلخّصُه:
[أبو العباس] ناصر الدين ابن المنير الجذامي الجروي الإسكندراني
أحمد بن محمد بن منصور بن القاسم بن مختار القاضي.
ولد سنة عشرين وستمائة.
وكان عالماً فاضلاً مفننًا، وكان في علومه له اليد الطولى في الأدب وفنونه.
وسمع الحديث من ابن رواج وغيره.
وله مصنفات مفيدة، وتفسير نفيس.
وله تأليف على تراجم صحيح البخاري
وله كتاب الاقتفا، عارّض به الشفا للقاضي عياض.
وله ديوان خطب.
وتفسير حديث الإسراء، في مجلد، على طريقة المتكلمين.
ووِلي قضاء الإسكندرية وخطابتها مرتين، ودرس بعدة مدراس.
وقيل إن الشيخ عز الدين ابن عبد السلام كان يقول: ديار مصر تفتخر برجلين في طرفيها: ابن المنير بالإسكندرية، وابن دقيق العيد بقوص.
وتوفي في مستهل ربيع الأول سنة ثلاث وثمانين وستمائة.
انتهى مُلَخّصا.
وجاء في «حسن المحاضرة» ما ملخصه:
أحد الأئمة المتبحرين في العلوم من التفسير والفقه والأصلين والنظر والعربية والبلاغة والأنساب.
أخذ عن جماعة منهم ابن الحاجب …
ومن تصانيفه:
والانتصاف من الكشاف
ومناسبات تراجم البخاري.
ومختصر التهذيب في الفقه.
وجاء في «طبقات النسابين»
وهو الذي يشير إليه ابن حجر في: الفتح في مناسبات البخاري، وقد طبع كتابه هذا باسم: «المتواري».', NULL, '0620-01-01', '0683-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('عز الدين ابن شداد', 'مؤلف', 'ابن شداد (٦١٣ - ٦٨٤ هـ = ١٢١٧ - ١٢٨٥ م)
محمد بن علي بن إبراهيم، أبو عبد الله، عز الدين ابن شداد الأنصاري الحلبي:
مؤرخ، من رؤساء الكتاب.
ولد بحلب، وقام برحلة إلى حران ومصر.
وناب عن الملك السعيد بركة خان في مأتم الملك الظاهر بيبرس، في دمشق، سنة ٦٧٦
وكان معظما عند الأمراء محبوبا لديهم.
تولى ديوان الرسائل عند هولاكو وغيره من الملوك.
واستوطن الديار المصرية بعد استيلاء التتار على حلب.
وتوفي بالقاهرة.
له:
(الأعلاق الخطيرة في ذكر أمراء الشام والجزيرة - ط) جزآن منه عن دمشق وحلب، ولم ينشر قسم الجزيرة
و (سيرة الملك الظاهر)
و (تاريخ حلب)
نقلا عن: الأعلام للزركلي', NULL, '1217-01-01', '1285-01-01', NOW(), NOW())
