INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('ابن النفيس', 'مؤلف', 'ابن النفيس (٠٠٠ - ٦٨٧ هـ = ٠٠٠ - ١٢٨٨ م)
علي بن أبي بالحزم القرشي، علاء الدين الملقب بابن النفيس: أعلم أهل عصره بالطب.
أصله من بلدة قرش (بفتح القاف وسكون الراء، في ما وراء النهر) ومولده في دمشق، ووفاته
بمصر.
له كتب كثيرة، منها «الموجز - ط» في الطب، اختصر به قانون ابن سينا، و «فاضل بن ناطق - خ» على نمط «حي بن يقظان» لابن الطفيل، و «بغيه الطالبين وحجة المتطببين» و «شرح الهداية لابن سينا» في المنطق، و «الهذب - خ» في الكحل، و «الشامل» في الطب، كبير جدا، منه مجلد مخطوط ضخم في الظاهرية بدمشق، وثلاثة مجلدات مخطوطة في جامعة ستانفورد، بكاليفورنيا (وصفها نقولا هير في مجلة معهد المخطوطات ٦: ٢٠٣) [ثم طُبع ما وجد منه] و «شرح فصول أبقراط - خ» في الطب، و «بغية الفطن من علم البدن - خ» في الطب، رأيته في الفاتيكان (١٠٦٩ عربي) و «الرسالة الكاملية في السيرة النبوية - ط» وكانت طريقته في التأليف أن يكتب من حفظه وتجاربه ومشاهداته ومستنبطاته، وقل أن يراجع أو ينقل.
وخلف مالا كثيرا، ووقف كتبه وأملاكه على البيمارستان المنصوري بالقاهرة.
ومات في نحو الثمانين من عمره.
وورد اسمه في كثير من المصادر (علي أبي بالحرم «والصواب» ابن أبي الحرم «بزاي ساكنة، كما هو بخطه
نقلا عن: الأعلام للزركلي', NULL, '0687-01-01', '1288-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
