INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('شهاب الدين الخويي', 'مؤلف', 'شهاب الدين الخُوَيِّي (٦٢٦ - ٦٩٣ هـ = ١٢٢٩ - ١٢٩٤ م)
محمد بن أحمد بن خليل بن سعادة الخويي، شهاب الدين، أبو عبد الله
• قاضي دمشق، وابن قاضيها. مولده ووفاته فيها.
• ولي قضاء القدس سنة ٦٥٧ ثم قضاء حلب، فقضاء الديار المصرية، ونقل إلى قضاء الشام.
• وكان فقيها شافعيا باحثا
له تصانيف منها:
• «أقاليم التعاليم - خ» في إحصاء العلوم ٨٤ ورقة
• «شرح الفصول الخمسين، في النحو، لابن معطي - خ» في دار الكتب (١٩١٨)
• «الجبر والمقابلة»
• «الهيئة»
• منظومات في «البيان» و «الفرائض» و «العروض»
• كتاب يشتمل على عشرين فنا، في مجلد كبير،
• «نظم علوم الحديث» لابن الصلاح
• «نظم الفصيح» لثعلب
وغير ذلك.
وخرَّج له عبيد بن محمد الإسعردي «مشيخة» على حروف المعجم اشتملت على ٢٣٦ شيخا، وله نحو ٣٠٠ شيخ لم يذكروا في هذا المعجم.
والخويي: نسبة إلى «خُوى» من أعمال أذربيجان (١).
_________
(١) الأنس الجليل ٢: ٤٦٦ وفوات الوفيات ٢: ١٨٢. والبداية والنهاية ١٣: ٣٣١ وبغية الوعاة ١٠ والدارس ١: ٢٣٧ وانظر فهرسته. والفهرس والتمهيدي ٥٦١ وقرأت في كتاب «مشيخة» مخطوط، أنه انتقل من قضاء القدس إلى مصر بسبب ورود التتار إلى بلاد الشام، فولي قضاء البهنسا والمحلة، ثم انتقل إلى قضاء حلب فالديار المصرية، فالشام «وكان كثير المداراة للناس، فيه حب للمنصب وخوف عليه، قليل المنافرة، يحب طريق السلامة» وانفردت هذه المشيخة بالتعريف به بابن سعادة الخويي «المهلبي» وفي طبقات السبكي ٥: ٨ ترجمة لأبيه، عرفه فيها بالخويي «البرمكي» ووقع اسمه في الشذرات ٥: ٤٢٣ «شهاب الدين، أحمد» والصواب «محمد» ودار الكتب ٧: ٤٧.
نقلا عن: «الأعلام» للزركلي', NULL, '1229-01-01', '1294-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


