INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('البقوري', 'مؤلف', 'محمد بن إبراهيم البَقّوري (ت ٧٠٧ هـ)
• محمد بن إبراهيم بن محمد أبو عبد الله البَقّوري [وبقور بباء موحدة مفتوحة وقاف مشددة وراء مهملة بلد بالأندلس].
• سمع من القاضي الشريف أبي عبد الله محمد الأندلسي ووضع كتاباً سماه إكمال الإكمال للقاضي عياض
• وله كلام على كتاب شهاب الدين القرافي في الأصول.
• قدم إلى مصر وأرسل معه بعض السلاطين بالمغرب ختمة كبيرة بخط مغربي منسوب ليوقفها بمكة أو بالمدينة ورجع إلى مراكش فتوفي بها سنة سبع وسبعمائة.
نقلا عن «الديباج المذهب في معرفة أعيان علماء المذهب» (٢/ ٣١٦)', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('ابن الزبير الغرناطي', 'مؤلف', 'ابن الزبير الغرناطي (٦٢٧ - ٧٠٨ هـ = ١٢٣٠ - ١٣٠٨ م)
أحمد بن إبراهيم بن الزبير الثقفي الغرناطي، أبو جعفر: محدث مؤرخ، من أبناء العرب الداخلين إلى الأندلس. انتهت إليه الرياسة بها في العربية ورواية الحديث والتفسير والأصول.
ولد في جيان (Jaen)وأقام بمالقة (Malaga) فحدثت له فيها شؤون ومنغصات، فغادرها إلى غرناطة فطاب بها عيشه وأكمل ما شرع فيه من مصنفاته. وتوفي فيها. من كتبه (صلة الصلة - ط) قطعة منه، وهو مخطوط كاملا اقتنيت تصويره، وصل به صلة ابن بشكوال. وله (ملاك التأويل في المتشابه اللفظ في التنزيل - خ) [ثم طُبع] في خزانة الرباط (٢٠٧٣ كتاني) و (البرهان في ترتيب سور القرآن - خ) [ثم طُبع] في خزانة الرباط، ذكره المنوني (٧٠١) و (الأعلام بمن ختم به القطر الأندلسي من الأعلام) و (معجم) جمع فيه أسماء شيوخه وتراجمهم. قال ابن حجر: كانت له مع ملوك عصره وقائع، وكانت بينه وبين أميري مالقة وغرناطة صداقة، وكان معظما عند الخاصة والعامة .
نقلا عن : الأعلام للزركلي', NULL, '1230-01-01', '1308-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
