INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('العباسي الصفدي', 'مؤلف', 'الحسن الصفدي (؟ - بعد ٧١٧ هـ)
الحسَن بن أبي محمّد عبد الله بن عمر بن محاسن بن عبد الكريم الهَاشِمِي العبّاسي الصَّفَدِي
• عبّاسيّ، هاشميّ، من قريش، ومن أهل مدينة صفد بشمال فلسطين، ولذلك عرف بالعبّاسي الصفدي. ومن ذراري هارون الرشيد. فالخليفة العباسي هو جدّه التاسع.
• كان كاتبا متمرّسا في ديوان الإنشاء بمصر، وكان شاعرا له نظم في المديح (مديح سلاطين عصره)، وهذا يقتضي أن يكون كاتبا أديبا، عارفا باللغة، والنحو، والصرف، والبلاغة، والبيان، والعروض، وما يتّصل بذلك من معارف أدبية
• لا يعرف متى ولد، ولا متى مات، فالمصادر لم تترجم له، لكنه كان حيا حتى سنة ٧١٧ هـ / ١٣١٧ م على الأقلّ (بدليل أنه يروي حادثة السّيل الذي خرّب بعلبك في السنة المذكورة)، ما يعني أنه من مواليد القرن السابع، ويحتمل أنه ولد في منتصف القرن السابع، أو قبل ذلك بقليل، أو بعده بقليل.
كتبه
١ - آثار الأول في ترتيب الدول: نشره الدكتور عبد الرحمن عميرة
٢ - نزهة المالك والمملوك في مختصر سيرة من ولي مصر من الملوك
٣ - التذكرة الكاملية في السياسة الملوكية
(الترجمة مختصرة من مقدمة د عمر عبد السلام تدمري لكتاب «نزهة المالك والمملوك في مختصر سيرة من ولي مصر من الملوك»)', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('أبو بكر بن عبد الدائم', 'مؤلف', 'جاء في ذيل التقييد في رواة السنن والأسانيد - (٢ / ٣٣٧)
أبو بكر بن أحمد بن عبد الدائم بن نعمة بن أحمد بن نعمة بن بكير النابلسي المقدسي الصالحي. سمع على الحسين بن المبارك ابن الزبيدي البغدادي بدمشق «صحيح البخاري» و«مسند الشافعي» و«جزء أبي الجهم» والأربعين الطائية.
وعلى ابي المنجا بن اللتي «مسند الدارمي» ومسند عبد بن حميد.
وحدث بمسموعاته أو أكثرها سمع منه الأعيان.
وروى لنا عنه حضورا شيخنا أبو هريرة عبد الرحمن ابن الحافظ الذهبي وروى عنه إجازة البرهان التنوخي. مات في شهر رمضان سنة ثمان عشرة وسبعمائة بصالحية دمشق وله ثلاث وتسعون سنة.', 'المذهب الشافعي', NULL, NULL, NOW(), NOW())
