INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('ابن تيمية', 'مؤلف', 'ابن تَيْمِيَّة (٦٦١ - ٧٢٨ هـ = ١٢٦٣ - ١٣٢٨ م)
أحمد بن عبد الحليم بن عبد السلام ابن عبد الله بن أبي القاسم الخضر النميري الحراني الدمشقيّ الحنبلي، أبو العباس، تقي الدين ابن تيمية
• الإمام، شيخ الإسلام. ولد في حران وتحول به أبوه إلى دمشق فنبغ واشتهر.
• وطلب إلى مصر من أجل فتوى أفتى بها، فقصدها، فتعصب عليه جماعة من أهلها فسجن مدة، ونقل إلى الإسكندرية.
• ثم أطلق فسافر إلى دمشق سنة ٧١٢ هـ واعتقل بها سنة ٧٢٠ وأطلق
• ثم أعيد، ومات معتقلا بقلعة دمشق، فخرجت دمشق كلها في جنازته.
• كان كثير البحث في فنون الحكمة، داعية إصلاح في الدين. آية في التفسير والأصول، فصيح اللسان، قلمه ولسانه متقاربان.
• وفي الدرر الكامنة أنه ناظر العلماء واستدل وبرع في العلم والتفسير وأفتى ودرّس وهو دون العشرين.
أما تصانيفه ففي الدرر أنها ربما تزيد على أربعة آلاف كراسة، وفي فوات الوفيات أنها تبلغ ثلاث مئة مجلد، منها
• (الجوامع - ط) في السياسة الإلهية والآيات النبويّة، ويسمى (السياسة الشرعية)
• (الفتاوى - ط) خمس مجلدات
• (الإيمان - ط)
• (الجمع بين النقل والعقل - خ) الجزء الرابع منه، والثالث في ٢٦٧ ورقة كتب سنة ٧٣٧ في شستربتي (٣٥١٠)
• (منهاج السنة - ط)
• (الفرقان بين أولياء الله وأولياء الشيطان - ط)
• (الواسطة بين الحق والخلق - ط)
• (الصارم المسلول على شاتم الرسول - ط)
• (مجموع رسائل - ط) فيه ٢٩ رسالة
• (نظرية العقد - ط) كما سماه ناشره، واسمه في الأصل (قاعدة) في العقود
• (تلخيص كتاب الاستغاثة - ط) يعرف بالرد على البكري
• (الرد على الأخنائي - ط)
• (رفع الملام عن الأئمة الأعلام - ط) رسالة
• (شرح العقيدة الأصفهانية - خ) رأيته في المكتبة السعودية بالرياض [طُبع]
• (القواعد النورانية الفقهية - ط)
• (مجموعة الرسائل والمسائل - ط) خمسة أجزاء
• (التوسل والوسيلة - ط)
• (نقض المنطق - ط)
• (الفتاوي - خ)
• (السياسة الشرعية في إصلاح الراعي والرعية - خ) [طُبع]
• (مجموعة - ط) أخرى اشتملت على أربع رسائل:
الأولى رأس الحسين (حقق فيها أن رأس الحسين حمل إلى المدينة ودفن في البقيع)
والثانية الرد علي ابن عربي والصوفية
والثالثة العقود المحرمة
والرابعة قتال الكفار.
ولابن قدامة كتاب في سيرته سماه (العقود الدرية في مناقب شيخ الإسلام أحمد بن تيمية - ط)
وللشيخ مرعي الحنبلي، كتاب (الكواكب الدرية - ط) في مناقبه، ومثله لسراج الدين عمر بن علي ابن موسى البزار، وللشهاب أحمد بن يحيى بن فضل الله العمري (١).
_________
(١) فوات الوفيات ١: ٣٥ - ٤٥ والمنهج الأحمد - خ - والدرر الكامنة ١: ١٤٤ والبداية والنهاية ١٤: ١٣٥ وابن الوردي ٢: ٢٨٤ وآداب اللغة ٣: ٢٤٣ والنجوم الزاهرة ٩: ٢٧١ ودائرة المعارف الإسلامية ١: ١٠٩ والتبيان - خ. وتعليق على مخطوطة من (شرح العقيدة الأصفهانية) بخط محمود شكري الآلوسي.
نقلا عن: «الأعلام» للزركلي [مع إضافات بين معقوفين]', 'المذهب الحنبلي', '1263-01-01', '1328-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


