INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('الأمير ابن بلبان الفارسي', 'مؤلف', 'ابن بلبان (٦٧٥ - ٧٣٩ هـ = ١٢٧٦ - ١٣٣٩ م)
علاء الدين، علي بن بلبان بن عبد الله الفارسي، المنعوت بالأمير:
