INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('الزريراني، شرف الدين عبد الرحيم', 'مؤلف', 'شرف الدين عبدالرحيم الزَّرِيراني (٧١١-٧٤١هـ)
عبد الرحيم بن عبد الله بن محمد بن أبي بكر بن إسماعيل الزريراني، البغدادي، شرف الدين، أبو محمد.
وهو ابن شيخ العراق تقي الدين أبي بكر. قاله ابن رجب، ونعتَ الأب في ترجمته بـ«مفتي الآفاق… انتهت إليه رئاسة العلم ببغداد من غير مدافع، وأقر له الموافق والمخالف»، ونعتَ الصفديُّ الأبَ أيضًا بـ«شيخ الإسلام» في ترجمة تلميذه نجم الدين النهرماري بـ«الوافي».
• و«الزَّرِيراني»: نسبة إلى «زَرِريران»: «بفتح الزاي، وكسر الراء، وياء ساكنة، وراء أخرى، وآخره نون: قرية بينها وبين بغداد سبعة فراسخ». قاله ياقوت في «معجم البلدان»، واعتمده د. عبدالرحمن العثيمين في تحقيقه لـ«ذيل ابن رجب»، والشيخ بكر أبو زيد في «المدخل»، والشيخ عبدالله التركي في «المذهب الحنبلي».
• أما صاحب الترجمة (الابن):
فهو: فقيه حنبلي، محدث.
ولد ببغداد [سنة ٧١١ كما في «المعجم المختص بالمحدثين» لشيخه الذهبي]، ونشأ بها وقرأ القرآن، وحفظ «المحرر» وسمع الحديث واشتغل. ثم رحل إلى دمشق، ثم إلى مصر ولقي بها أبا حيان وغيره. وأقام بدمشق مدة، ثم رجع إلى بغداد بفضائل.
وناب في القضاء ببغداد، واشتهرت فضائله.
وخطه في غاية الحسن.
من مصنفاته:
• «إيضاح الدلائل في الفرق بين المسائل»، اختصره من «فروق السامري» وزاد عليها فوائد واستدراكات من كلام أبيه وغيره.
• و«اختصر طبقات الأصحاب» للقاضي أبي الحسين، وذيَّل عليها. قال ابن رجب: «وتطلَّبتُها فلم أجدها».
• واختصر «المطلع» لابن أبي الفتح… وغير ذلك.
توفي يوم الثلاثاء ١٢ من ذي الحجة عام ٧٤١هـ، وله من العمر نحو (٣٠) سنة -رحمه الله-.
[ملخص من ترجمة المؤلف وترجمة أبيه في «ذيل طبقات الحنابلة» لابن رجب، مع زيادات من مصادر أخرى. مع التنبيه إلى أنه تحرفت نسبته إلى «الزريراتي» (بالتاء) في كثير من المصادر]', 'المذهب الحنبلي', '0711-01-01', '0741-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
