INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('المزي، جمال الدين', 'مؤلف', 'الحافظ المزي (٦٥٤ - ٧٤٢ هـ = ١٢٥٦ - ١٣٤١ م)
يوسف بن عبد الرحمن بن يوسف، أبو الحجاج، جمال الدين ابن الزكي أبي محمد القضاعي الكلبي المزي: محدث الديار الشامية في عصره.
ولد بظاهر حلب، ونشأ بالمزة (من ضواحي دمشق) وتوفي في دمشق.
مهر في اللغة، ثم في الحديث ومعرفة رجاله.
وصنف كتبا، منها «تهذيب الكمال في أسماء الرجال - خ» اثنا عشر مجلدا، و «تحفة الاشراف بمعرفة الاطراف - خ» في الحديث ، ثماني مجلدات، قال ابن طولون: ومن المعلوم أن المحدثين بعده عيال على هذين الكتابين.
وله «المنتقى من الأحاديث - خ» و «الكنى، المختصر من تهذيب الكمال - خ» في ١٠١ ورقة (كما في فهرس المخطوطات المصورة: القسم ٢ ج ٢: ١٢٠) قال ابن ناصر الدين: قال الحافظ أبو عبد الله الذهبي: أحفظ من رأيت أربعة: ابن دقيق العيد، والدمياطي، وابن تيمية، والمزي، فابن دقيق العيد أفقههم في الحديث، والدمياطي أعرفهم بالأنساب، وابن تيمية أحفظهم للمتون، والمزي أعرفهم بالرجال.
وقال الكتاني: أفرده الحافظ أبو سعيد العلائي بمؤلف سماه «سلوان التعزي بالحافظ أبي الحجاج المزي»
نقلا عن : الأعلام للزركلي', NULL, '1256-01-01', '1341-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
