INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('أبو الثناء الأصبهاني', 'مؤلف', 'أبو الثناء الأَصْبَهاني (٦٧٤ - ٧٤٩ هـ = ١٢٧٦ - ١٣٤٩ م)
محمود بن عبد الرحمن (أبي القاسم) ابن أحمد بن محمد، أبو الثناء، شمس الدين الأصفهاني، أو الأصبهاني: مفسر، كان عالما بالعقليات. ولد وتعلم في أصبهان. ورحل إلى دمشق فأكرمه أهلها، وأعجب به ابن تيمية. وانتقل إلى القاهرة فبنى له الأمير (قوصون) الخانقاه بالقرافة، ورتبه شيخا فيها، فاستمر الى أن مات بالطاعون في القاهرة. من كتبه (التفسير - خ) في صوفية (دار الكتب الشعبية ١: ٤٣) مخطوطة كاملة نفيسة (٨٤٣ ورقة) كبير، منه الجزء الرابع مخطوط، سماه (أنوار الحقائق الربانية) قال الصفدي: رأيته يكتب في تفسيره من خاطره من غير مراجعة، و (تشييد القواعد - خ) في شرح تجريد العقائد للنصير الطوسي، و (شرح فصول النسفي - خ) و (مطالع الأنظار في شرح طوالع الأنوار للبيضاوي - ط) و (ناظرة العين - خ) مصور في معهد المخطوطات، في المنطق، مع (شرحه - خ) - ناضرة العين - لأحمد بن عمر المالكي (٧٩٥) ، و (البيان - خ) في شرح مختصر ابن الحاجب، أصول [ثم طُبع]، و (بيان معاني البديع - خ) شرح البديع لابن الساعاتي في أصول الفقه، و (شرح مطالع الأنوار) للأرموي في المنطق، و (شرح كافية ابن الحاجب - خ) و (شرح منهاج البيضاوي)
نقلا عن: الأعلام للزركلي', 'المذهب المالكي', '1276-01-01', '1349-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('المزي، عبد الرحمن', 'مؤلف', 'جاء في كتاب «ذيل التقييد في رواة السنن والأسانيد» (ج ٢ / ص ١٠٤)
عبد الرحمن بن يوسف بن الزكي عبد الرحمن زين الدين أبو الفرج، ابن الحافظ الحجة جمال الدين المزي.
سمع على القاضي تاج الدين عبد الخالق بن عبد السلام بن علوان جميع «سنن ابن ماجه».
وسمع على الحافظ شرف الدين أبي الحسين علي بن محمد اليونيني من أول الجزء الثالث من «سنن ابن ماجه» إلى آخرها.
وسمع من قوله فيها باب الأمل والوجل وهو الجزء السابع عشر إلى آخرها على إسماعيل بن عبد الرحمن وأخته أم محمد صفية.
وحدث بها بدمشق والقاهرة.
ومات سنة تسع وأربعين وسبعمائة.', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('ابن أيبك الدمياطي', 'مؤلف', 'ابن أَيْبَك [الدمياطي] (٧٠٠ - ٧٤٩ هـ = ١٣٠٠ - ١٣٤٨ م)
أحمد بن أيبك بن عبد الله، أبو الحسين، شهاب الدين الحسامي الدمياطي
مؤرخ محدّث مصري. سمع في القاهرة والإسكندرية ودمشق. ومات بالطاعون بمصر.
له:
• (ذيل) على كتاب (صلة التكملة لوفيات النقلة) تأليف عزّ الدِّين أحمد بن محمد الحسيني، في التراجم، من سنة ٦٩٥ إلى عام وفاته
• وخرج (معاجم) للدبوسي والسبكي وغيرهما من شيوخه
• وجمع (مجاميع)
• وانتخب الذهبي (جزءا) من حديثه، قال ابن حجر: رأيته بخط الذهبي.
• وشرع في (تخريج أحاديث الرافعي) ولم يكمله
• و (المستفاد من ذيل تاريخ بغداد) - (خ) ثمانية أجزاء في مجلد، بخطه في دار الكتب [طُبع] (١).
_________
(١) الدرر الكامنة ١: ١٠٨ وكشف الظنون ٢٠٢٠ والإعلام لابن قاضي شهبة - خ. وهو فيه: أبو العباس، ويقال أبو الحسين. ودار الكتب ٥: ٣٤٤
نقلا عن: «الأعلام» للزركلي [مع إضافة بين معكوفين]', NULL, '1300-01-01', '1348-01-01', NOW(), NOW())
