INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('تقي الدين البعلبكي', 'مؤلف', 'تقي الدين البعلبكي (٧٠١ - ٧٦٨)
تقي الدين محمد بن محمد بن عيسى البعلبكي، ذكره الذهبي في المعجم المختص، وقال ابن كثير في البداية والنهاية: هو أحد الفضلاء المشهورين. وأثنى على علمه. وترجم له ابن حجر في الدرر الكامنة ، وقال ابن فهد في الذيل : دأب واجتهد في الطلب وكان من العلماء الراسخين والأئمة الحفاظ المعتبرين. وله ترجمة في ذيل العبر لابن العراقي', NULL, '0701-01-01', '0768-01-01', NOW(), NOW())
