    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('يوسف بن ماجد بن أبي المجد المقدسي', 'مؤلف', 'جمال الدين، أبو العباس، يوسف بن ماجد بن أبي المجد بن عبد الخالق المرداوي المقدسي
من فضلاء الحنابلة. حَدث عن الحجار وابن الرضي والشرف بن الحافظ وابن الشحنة وغيرهم.
صحب شيخ الإسلام ابن تيمية، وتأثر به، فكان كثير الاعتناء بالنظر في كلامه، وينصر مسائله الأصولية، مثابرًا على فتواه في الطلاق وكذا في عدة مسائل، وسجن بسبب ذلك ولا يرجع عن قوله
من مؤلفاته:
١ - «شرح المحرر».
٢ - «النهاية في تصحيح الفروع».
٣ - «المقرر على أبواب المحرر».
وقال ابن عبد الهادي في «الجوهر المنضد» (ص: ١٨٠): «صنف كتابًا في الفقه، وحكى فيه خلافًا كثيرًا، وفيه أوهام كثيرة وفيه مواضع حسنة، ويذكر في بعض المواضع الخلاف بصيغة: أو».
[مستفاد من مقدمة تحقيق «المقرر على أبواب المحرر»]', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


