INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('علي بن محمد الخزاعي', 'مؤلف', 'علي بن محمد الخزاعي (٧١٠ - ٧٨٩ هـ = ١٣١٠ - ١٣٨٧ م)
علي بن محمد بن أحمد بن موسى ابن مسعود، أبو الحسن ابن ذي الوزارتين، الخزاعي: بحاثة مؤرخ أديب، أندلسي الأصل. مولده بتلمسان، ووفاته بفاس.
استكتبه السلطان إبراهيم المريني. ثم كتب في ديوان بني زيان بتلمسان. واستقر أخيرا في بلاط بني مرين.
وصنف للسلطان المتوكل على الله أبي فارس المريني (سنة ٧٨٦ هـ) كتابه «تخريج الدلالات السمعية، على ما كان في عهد رسول الله صلى الله عليه وسلم من الحرف والصنائع والعمالات الشرعية - خ» [ثم طُبع] اطلع عبد الحي الكتاني على نسخة منه غير تامة، فأضاف إليها زيادات كثيرة ونسب الكتاب كله إليه، وسماه «التراتيب الإدارية - ط» في مجلدين، وعلمت أن ما فات الكتاني من كتاب الخزاعي هو نحو ربعه ثم رأيت هذا الربع في إحدى خزائن تطوان الخاصة ونقلت عنه خزانة الرباط نسخة بالتوصير الشمسي .
نقلا عن : الأعلام للزركلي', NULL, '1310-01-01', '1387-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
