INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('ابن زريق', 'مؤلف', 'جاء في إنباء الغمر بأبناء العمر (٢/ ١٨٧):
محمد بن عبد الرحمن بن محمد بن أحمد بن التقي سليمان بن حمزة المقدسي ثم الصالحي ناصر الدين المعروف بابن زريق -تصغير أزرق-.
سمع الكثير من بقية أصحاب الفخر ومن بعدهم، تخرج بابن المحب وتمهر، وكان يقظاً عارفاً بفنون الحديث ذاكراً للأسماء والعلل، ولم يكن له اعتناء بصناعة الرواية من تمييز العالي والنازل، بل على طريق المتقدمين مع حظ من الفقه والعربية، رتب المعجم الأوسط على الأبواب فكتبه بخط متقن حسن جداً، ورتب صحيح ابن حبان، ورافقني كثيراً وأفادني من الشيوخ والأجزاء، وكان ديناً خيراً صيناً لم أر مَن يستحق أن يطلق عليه اسم الحافظ بالشام غيره، مات أسفاً على ولده أحمد في رمضان ولم يكمل الخمسين، وكان اللنكية قد أسروه وهو شاب له نحو العشر.', NULL, NULL, NULL, NOW(), NOW())
