INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('ابن الأحمر', 'مؤلف', 'ابن الأحمر (٠٠٠ - ٨٠٧ هـ = ٠٠٠ - ١٤٠٤ م)
إسماعيل بن يوسف بن محمد بن نصر الخزرجي الأنصاري النصري، أبو الوليد، المعروف بابن الأحمر: مؤرخ أديب.
غرناطي الأصل.
إقامته ووفاته بفاس.
من كتبه (نثر الجمان في شعر من نظمني وإياه الزمان - خ) في ١١ بابا، منها الباب الثالث: في شعر بني الأحمر (من بني نصر قومي وأبنائهم) والباب السابع: (فيما بلغني من شعر وزراء قومي بني الأحمر من بني نصر ملوك الأندلس) ينقص ورقة أو ورقتين من أوله.
ويكثر فيه من جملة (قال إسماعيل مؤلف هذا الكتاب) و (نثير أفراد الجمان في نظم فحول الزمان) من أهل المئة الثامنة، و (مشاهير بيوتات فاس) اختصره أبو زيد الفاسي في كتاب مطبوع، و (حديقة النسرين في أخبار بني مرين) المطبوع باسم (روضة النسرين) و (مستودع العلامة - ط) في ذكر من تولى كتابة العلامة من كتاب بعض الملوك
نقلا عن «الأعلام» للزركلي', NULL, '0807-01-01', '1404-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('الأقفهسي', 'مؤلف', 'ابن العماد (٧٥٠ - ٨٠٨ هـ = ١٣٤٩ - ١٤٠٥ م)
أحمد بن عماد بن يوسف بن عبد النبي، أبو العباس، شهاب الدين الأقفهسي ثم القاهري: فقيه شافعي، كثير الاطلاع، في لسانه بعض حبسة.
له (التعقبات على المهمات) للإسنوي، و (شرح المنهاج) و (السر المستبان مما أودعه الله من الخواص في أجزاء الحيوان - خ) و (التبيان في آداب حملة القرآن) منظومة، ومنظومة في (العقائد) و (المعفوات - خ) في الفقه، منظومة تائية وشرحها، و (الذريعة في أعداد الشريعة - خ) رأيت مسودته بخطه، في مكتبة لورانزيانا، بفلورنس (رقم ٩١ شرقي) و (كشف الأسرار عما خفي عن الأفكار - خ) في الإسكوريال، و (نيل مصر - خ) في مكتبة الحرم المكي.
نسبته إلى أقفهس، من عمل البهنسا بمصر .
نقلا عن : الأعلام للزركلي', NULL, '1349-01-01', '1405-01-01', NOW(), NOW())
