INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('محمد بن القاسم السبتي', 'مؤلف', 'مولده ونشأته بسبتة
يذكر المؤلف أن أبا العباس بن أبي الخير الأنصاري جده من جهة الأم وأن أبا العباس الدقاق من أصهار سلفه، ويظهر أن أصل هذا السلف من قرية بحوز سبتة تسمى بزبج، لأنه يسميها (قريتنا) عندما يذكرها، كانت لهم بها أملاك، ثم انتقلوا منها إلى سبتة حيث تملكوا بعض العقارات
(التعريف بالمؤلف من مقدمة محقق «اختصار الأخبار عما كان بثغر سبتة من سني الآثار»)', NULL, NULL, NULL, NOW(), NOW())
