INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('الخيربيتي', 'مؤلف', 'الخَيْربَيْتي ( ٠٠٠ - بعد ٨٤٣ هـ = ٠٠٠ - بعد ١٤٤٠ م)
محمود بن إسماعيل بن إبراهيم بن ميكائيل الخَيْربَيْتي : باحث، كان على اتصال بالملك الظاهر جقمق العلائي، ملك مصر. وألف له كتابا سماه (الدرة الغراء في نصيحة السلاطين والقضاة والأمراء - خ) [ثم طُبع] بخطه ، في دار الكتب المصرية (٢٣٢٩٢ ب) فرغ منه في غرة ذي الحجة ٨٤٣ ولم يشر إليه السخاوي (في الضوء) مع أنه استوفى ترجمة جقمق
نقلا عن : الأعلام للزركلي', NULL, '0843-01-01', '1440-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('علاء الدين الطرابلسي', 'مؤلف', 'الطرابلسي (٠٠٠ - ٨٤٤ هـ = ٠٠٠ - ١٤٤٠ م)
علي بن خليل الطرابلسي، أبو الحسن، علاء الدين: فقيه حنفي.
كان قاضيا بالقدس.
له «معين الحكام فيما يتردد بين الخصمين من الأحكام - ط» في فقه الحنفية
نقلا عن : الأعلام للزركلي', 'المذهب الحنفي', '0844-01-01', '1440-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
