INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('محمد بن السيد حسن', 'مؤلف', 'من ترجمته كما أوردها محقق كتابه «الراموز على الصحاح» :
اسمه
تذكر الكتب التي رجعت إليها أن اسم المؤلف السيد محمد بن السيد حسن وقيل السيد محمد بن حسين والمصنف نفسه ذكر هذا في مقدمة «الراموز» حيث قال يقول المفتقر إلى الله ذي المنن السيد محمد بن حسن
أما عن اسم جده فقد اختلفوا فيه فبعضهم يسميه عليا وبعضهم يسميه حسن بن علي والبعض الآخر يسميه حسن الشريف بن حسام الدين
حياته
لم تذكر لنا المراجع شيئا يذكر عن ذلك لأن السيد محمد بن حسن كان مغمورا لم يأخذ حظه من الشهرة وكل ما ذكره المستشرق الألماني كارل برولكمان أن المؤلف أكمل كتابه الراموز في بلده أدريانوبل سنة ٨٥٤ هـ ١٤٥٠ م ويذكرون أيضا أنه مات بالطريق إلى مكة حاجا إلى هنا وتلتزم المراجع التاريخية الصمت وليس لنا أن نذهب إلى أبعد من ذلك ولأننا لا نكاد نعلم شيئا محققا عن حياة المصنف فلا نستطيع أن التعرف على أساتذته وشيوخه وكل ما نعرفه هو مراجعه التي نقل عنها كالصحاح للجوهري والفائق للزمخشري والنهاية لابن الأثير والمغرب للمطرزي والقاموس للفيروز أبادي
مذهبه الفقهي
أستطيع الجزم بأن المصنف كان حنفي المذهب بدليل أنه نقل آراء الفقهاء عن المطرزي وهو من علماء الأحناف فإذا نقل رأيا آخر يختلف مذهبه صرح باسم المذهب الذي نقل عنه
مذهبه النحوي
من خلال استعراض مسائل النحو والصرف التي وردت في الكتاب يبدو لنا أن المصنف كان ينتهج المذهب البصري متحمسا له
وفاته
المتفق عليه أن السيد محمد بن حسن مات سنة ٨٦٦ هـ
مؤلفاته
ذكر المصنف في مقدمة «الراموز» أن له كتابا يسمى «الجامع» جامع اللغة الذي بنى عليه كتاب الراموز وكلا الكتابين على الصحاح وذكرهما أيضا حاجي خليفة والأستاذ عبد الغفور عطار وكارل بروكلمان', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
