(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('ابن غازي', 'مؤلف', 'ابن غازي المكناسي (٨٤١ - ٩١٩ هـ = ١٤٣٧ - ١٥١٣ م)
أبو عبد الله، محمد بن أحمد بن محمد بن محمد بن علي بن غازي العثماني المكناسي:
مؤرخ حاسب فقيه من المالكية.
[وهو المراد في كتب المالكية بـ (ابن غازي) عند الإطلاق].
مِن بِني عثمان (قبيلة من كتامة بمكناسة الزيتون) ولد بها وتفقه بها وبفاس، وأقام زمنا في كتامة، واستقر بفاس سنة ٨٩١ وتوفي بها.
له:
«الروض الهتون في أخبار مكناسة الزيتون» - خ [ثم طُبع].
و «الفهرسة المباركة - خ» في أسماء محدثي فاس وكتّابها، وتسمى «التعلل برسوم الأسناد - خ»
و «غنية الطلاب في شرح منية الحسّاب - ط» شرح أرجوزة له، في الحساب
و «كليات فقهية على مذهب المالكية - ط»
و «شفاء الغليل في حل مقفل خليل» - خ [ثم طُبع] أوضح به غوامض مختصر خليل
و «تفصيل الدرر - خ» في رسم القرآن
و «تفصيل الدرر - خ» في القراآت
و «نظم نظائر رسالة القيرواني - خ» فقه، شرحه الحطاب
و «إتحاف ذوي الاستحقاق - خ» شرح لألفية ابن مالك، في الرباط (د ٣٢٣)
و «إرشاد اللبيب إلى مقاصد حديث الحبيب - خ» في الرباط (الجزء الأول من القسم الثاني ٥٢، ٢٩٦)
وغير ذلك
وأفرد عبد الله كنون الرسالة الثانية عشرة من كتابه «ذكريات مشاهير المغرب» لترجمته.
ملخصا من: «الأعلام» للزركلي، مع إضافات بين [معقوفين].', 'المذهب المالكي', '1437-01-01', '1513-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('العز ابن فهد المكي', 'مؤلف', '[العز ابن فهد المكي] (٨٥٠ - ٩٢٠ هـ = ١٤٤٧ - ١٥١٥ م)
عبد العزيز بن عمر بن محمد، الشهير كأبيه وسلفه بابن فهد، أبو الخير وأبو فارس، عز الدين الهاشمي، من سلالة محمد ابن الحنفية
• مورخ، عالم بالحديث. من أهل مكة، مولدا ووفاة.
• زار فلسطين والشام ومصر، فأمضى أربع سنين، وعاد سنة ٨٧٥ هـ
له:
• «غاية المرام بأخبار سلطنة البلد الحرام - خ»
• «معجم شيوخه» نحو ألف شيخ
• «بلوغ القرى لذيل إتحاف الورى - خ» [طُبع] تتمة لتاريخ والده
• «فهرست مروياته»
• «رحلة»
• «تاريخ» على السنين ابتدأ فيه من سنة ٨٧٢ هـ
• «ترتيب طبقات القراء» للذهبي
وغير ذلك (١).
_________
(١) شذرات الذهب ٨: ١٠٠ والضوء اللامع ٤: ٢٢٤ والكواكب السائرة ١: ٢٣٨ و brock S ٢: ٢٢٤. والدهلوي في مجلة المنهل ٧: ٢٩٨.
نقلا عن: «الأعلام» للزركلي [مع إضافة بين معكوفين]', 'المذهب الحنفي', '1447-01-01', '1515-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('النخجواني', 'مؤلف', 'النخجواني ( ٠٠٠ - ٩٢٠ هـ = ٠٠٠ - ١٥١٤ م)
نعمة الله بن محمود النخجواني، ويعرف بالشيخ علوان: متصوف، من أهل «آقشهر» بولاية «قرمان» نسبته إلى «نخجوان» من بلاد القفقاس. رحل إلى الأناضول، واشتهر وتوفي بآقشهر.
له «الفواتح الإلهية والمفاتح الغيبية - ط» مجلدان في التفسير، على لسان القوم. قال صاحب الشقائق النعمانية: «كتبه بلا مراجعة للتفاسير، وأدرج فيه من الحقائق والدقائق ما يعجز عن إدراكه كثير من الناس، مع الفصاحة في عبارته» وله «شرح كتاب: كلشن راز - خ» بالفارسية، و «هداية الإخوان - خ» في التصوف
نقلا عن : الأعلام للزركلي', NULL, '0920-01-01', '1514-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
