INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('النعيمي', 'مؤلف', 'النعيمي (٨٤٥ - ٩٢٧ هـ = ١٤٤٢ - ١٥٢١ م)
عبد القادر بن محمد النعيمي الدمشقي، ولد في دمشق سنة ٨٤٥ هـ، وكان شديد الحب بمسقط رأسه الذي تولى فيه ولفترة منصب القضاء. وهو من أشهر من كتب في فضائل دمشق ولكنه ليس بآخرهم. تتلمذ على يديه ابن طولولن. وهو قد تتلمذ على يد العديد من الشيوخ أمثال إبراهيم الناجي، وزين الدين عبد الرحمن بن خليل، وزين الدين خطاب الغزاوي، وزين الدين مفلح بن عبد الله الحبشي المصري ثم الدمشقي وتجلبب على يد شيخه الأخير جلباب التصوف. كما وأفاد من بدر بن القاضي شهبة وشهاب بن قراء وقرأ كتابه« الإيذان» على برهان البقاعي وتسلم منه إجازة الرواية.
آثاره
خلّف آثاراً كثيرة أمثال: الدارس في تاريخ المدارس، تذكرة الإخوان في حوادث الزمان، التبيين في تراجم العلماء والصالحين، العنوان في ضبط مواليد ووفيات أهل الزمان، القول المبين المحكم في إهداء القرب للنبي( صلى الله عليه وسلم)، تحفة البررة في الأحاديث المعتبرة، إفادة النقل في الكلام على العقل وغيره.
توفي النعيمي في سنة ٩٧٨ هـ.
وجاء في الأعلام للزركلي، ما يلي:
عبد القادر بن محمد بن عمر بن محمد ابن يوسف بن عبد الله بن نعيم، أبو المفاخر: مؤرخ دمشق في عصره.
من علماء الحديث ، مولده ووفاته في دمشق.
من كتبه «الدارس في تاريخ المدارس - ط» مجلدان و «العنوان، في ضبط المواليد والوفيات لأهل الزمان - خ» و «تذكرة الإخوان في حوادث الزمان» و «التبيين في تراجم العلماء والصالحين» و «تحفة البررة في الأحاديث المعتبرة» و «إفادة النقل في الكلام على العقل»', NULL, '1442-01-01', '1521-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


