INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('ابن الحنبلي، رضي الدين', 'مؤلف', 'رضي الدين ابن الحنبلي (٩٠٨ - ٩٧١ هـ = ١٥٠٢ - ١٥٦٣ م)
محمد بن إبراهيم بن يوسف الحلبي القادري التاذفي، [الحنفي] رضي الدين [المعروف بـ] ابن الحنبلي، يتصل نسبه بابن الشحنة
مؤرخ. من علماء حلب، مولده ووفاته فيها. له نيف وخمسون مصنفا، منها «الزبد والضرب في تاريخ حلب - خ» [ثم طُبع] رسالة، و «در الحبب في تاريخ أعيان حلب - ط» و «المصابيح - خ» في الحساب، و «الدرر الساطعة - خ» في الطب و «مخايل الملاحة في مسائل الفلاحة - خ» و «تذكرة من نسي بالوسط الهندسي - خ» و «الحدائق الأنسية - خ» في العروض، و «رفع الحجاب عن قواعد الحساب - خ» و «ربط الشوارد - خ» في شرح شواهد شرح السعد على العزي في الصرف، و «روضة الأرواح - خ» فرائض و «ديوان شعره - خ» و «سوابغ النوابغ - خ» في شرح نوابغ الكلم للزمخشري، و «قفو الأثر في صفو علوم الأثر - ط» في مصطلح الحديث. و «الفوائد السرية في شرح الجزرية - خ» تجويد، و «حدائق أحداق الأزهار - خ» و «شقائق الأكم بدقائق الحكم - خ» و «تروية الظامي في تبرئه الجامي - خ» و «بحر العوام فيما أصاب فيه العوام - ط» [وتعليقة على «أنوار التنزيل» للبيضاوي، قفو الأثر في صفو علوم الَاثر (مطبوع)، أنوار الحلك في «شرح المنار» لابن ملك (مطبوع) في الأصول، «كحل العيون النجل في حلّ مسألة الكحل»، حاشية على «وقاية الرواية في مسائل الهداية» في الفقه الحنفي، حاشية على «شرح اللباب» في الفقه الشافعي، «ظلّ العريش في منع حلّ البنج والحشيش»، «ذبالة السراج على رسالة السراج» في الفرائض، «مغنى الحبيب عن مغني اللبيب»، «حدائق الأزهار ومصابيح أنوار الأنوار»، و «ديوان شعر»، وغير ذلك.]
نقلا عن: الأعلام للزركلي (مع زيادة)', 'المذهب الحنفي', '1502-01-01', '1563-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('جمال الدين الفاكهي', 'مؤلف', 'عبد الله بن أحمد الفاكِهي (٨٩٩ - ٩٧٢ هـ = ١٤٩٣ - ١٥٦٤ م)
عبد الله بن أحمد بن عبد الله بن أحمد ابن علي الفاكهي المكيّ، جمال الدِّين: عالم بالعربية، من فقهاء الشافعية. مولده ووفاته بمكة، أقام بمصر مدة.
من كتبه:
• «الفواكه الجنية على متممة الأجرومية - ط»
• «مجيب الندا إلى شرح قطر الندى - ط» كلاهما في النحو
• «حسن التوسل في آداب زيارة أفضل الرسل - ط»
• «كشف النقاب عن مخدرات ملحة الإعراب - ط» مع شرحها.
• واستنبط حدودا للنحو جمعها في كراسة ثم شرحها، وسماها «الحدود النحوية - خ» في جزأين [طُبع] (١).
_________
(١) النور السافر ٢٧٧ وتاريخ ابن العيدروس - خ. Brock ٢: ٤٩٩. وانظر فهرسته ومعجم المطبوعات ١٤٣٢ والكتبخانة ٧: ٢٥٣.
نقلا عن: «الأعلام» للزركلي [مع إضافة بين معقوفين]', 'المذهب الشافعي', '1493-01-01', '1564-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


