INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('عبد الباقي الحنبلي', 'مؤلف', 'عبد الباقي الحنبلي = ابن فقيه فصّة (١٠٠٥ - ١٠٧١ هـ = ١٥٩٦ - ١٦٦١ م)
تقيّ الدين، عبد الباقي بن عبد الباقي بن عبد القادر البعلي الأزهري الدمشقيّ، [الشهير بابن بدر، ثم بابن فقيه فصّة]:
فقيه حنبلي مُقرِئ من العلماء.
وُلد في (بعلبكّ)، ونِسبته إلى قرية (فصة) مِن قُراها [وهي بفاء مكسورة ومهملة؛ فيما قاله ابنُه أبو المواهب في أول «مشيخته»، وكذا في «السحب الوابلة»].
[وفي «تاج العروس»: وفُصة بالضم: قرية على فرسخ من بعلبك، نُسِب إليها جماعة من المحدثين والشيخُ زين الدين عبد القادر بن عبد الباقي ابن إبراهيم البعلي عُرِف بابن فقيه فُصّة، وهو جد الشيخ تقي الدين عبد الباقي بن عبد الباقي البعلي الحنبلي محدث الشام. اهـ. وعنه ضَبطها الزركليُّ].
رحل صاحب الترجمة إلى مصر سنة ١٠٢٩ هـ فتعلم في الأزهر، وعاد إلى دمشق، فتوفي فيها.
من تصانيفه:
١ - (العين والأثر في عقائد أهل الأثر)
٢ - (فيض الرزاق في تهذيب الأخلاق): [قال في «السحب الوابلة»: وقد ذَكر في «ثبته» أنّ من تصانيفه وهو أحسنها وأجمعها، قال: حرّرته بعد مطالعتي لكتاب الإمام أحمد بن عليّ بن مسكويه، وهو مؤلّف نفيس رصين التّأسيس]
٣ - (رياض أهل الجنة في آثار أهل السنَّة) - مخطوط، وهو ثبته، في خزانة الرباط (١٤٢٤ كتاني)
٤ - (رسالة في قراءة عاصم)
٥ - (شرح صحيح البخاري) لم يكمله.
قال صاحب السحب الوابلة: ولم تكن تصانيفه على قدر علمه (*).
[ثم نقل عنه قوله: وأَلّفتُ في العلوم رسائل لا تُضبَط كثرةً ولله الحمد].
[وهو والد أبي المواهب محمد بن عبد الباقي الحنبلي ت ١١٢٦ هـ كما سبق]
_________
(*) السحب الوابلة - خ. وخلاصة الأثر ٢: ٢٨٣ وفهرس الفهارس ١: ٣٣٨ والتاج [للزبيدي ١٨/ ٧٧ ط الكويت]: فُصّة.
نقلا عن: «الأعلام» للزركلي، مع زيادات بين [معقوفين] من جمع فريق الشاملة', 'المذهب الحنبلي', '1596-01-01', '1661-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


