INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('عبد الغني النابلسي', 'مؤلف', 'عبد الغني النابلسي (١٠٥٠ - ١١٤٣ هـ = ١٦٤١ - ١٧٣١ م)
عبد الغني بن إسماعيل بن عبد الغني النابلسي: شاعر، عالم بالدين والأدب، مكثر من التصنيف، متصوف.
ولد ونشأ في دمشق، ورحل إلى بغداد، وعاد إلى سورية، فتنقل في فلسطين ولبنان، وسافر إلى مصر والحجاز، واستقر في دمشق وتوفي بها.
له مصنفات كثيرة جدا، منها «الحضرة الأنسية في الرحلة القدسية - ط» و «وتعطير الأنام في تعبير المنام - ط» و «ذخائر المواريث في الدلالة على مواضع الأحاديث - ط» فهرس لكتب الحديث الستة، و «علم الفلاحة - ط» و «نفحات الأزهار على نسمات الأسحار - ط» و «إيضاح الدلالات في سماع الآلات - ط» و «ذيل نفحة الريحانة - خ» و «حلة الذهب الإبريز، في الرحلة إلى بعلبك وبقاع العزيز - خ» و «الحقيقة والمجاز، في رحلة الشام ومصر والحجاز - خ» و «قلائد المرجان في عقائد أهل الإيمان - خ» رسالة، و «جواهر النصوص - ط» جزآن، في شرح فصوص الحكم لابن عربي، و «شرح أنوار التنزيل للبيضاوي - خ» و «كفاية المستفيد في علم التجويد - خ» و «الاقتصاد في النطق بالضاد - خ» تجويد، و «مناجاة الحكيم ومناغاة القديم - خ» تصوف، و «خمرة الحان - ط» شرح رسالة الشيخ أرسلان، و «خمرة بابل وغناء البلابل - خ» من شعره، في الظاهرية، و «ديوان الحقائق - ط» من شعره، و «الرحلة الحجازية والرياض الأنسية - ط» و «كنز الحق المبين في أحاديث سيد المرسلين - خ» و «الصلح بين الإخوان في حكم إباحة الدخان - ط» و «شرح المقدمة السنوسية - خ» و «رشحات الأقلام في شرح كفاية الغلام - ط» في فقه الحنفية، و «ديوان الدواوين - خ» مجموع شعره، و «كشف الستر عن فرضية الوتر - ط» رسالة، و «لمعات (أو لمعان ؟) الأنوار في المقطوع لهم بالجنة والمقطوع لهم بالنار - ط» رسالة، و «خمس مجموعات - خ» فيها ٣٢ رسالة، ذكر الزيات أسماءها في «خزائن الكتب»
نقلا عن : الأعلام للزركلي', 'المذهب الحنفي', '1641-01-01', '1731-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
