INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('المشتولي', 'مؤلف', 'محمد بن حميد المشتولي ناسخ كتاب (سلوة الأحزان للاجتناب عن مجالسة الأحداث والنسوان) ، فرغ من نسخه في جمادى الأولى سنة (١١٦٧هـ)
واستظهر بعض المحققين أنه هو نفسه مؤلف الكتاب
طبع الكتاب لأول مرة بتحقيق طارق الطنطاوي (مكتبة ابن سينا: القاهرة:١٤١٠هـ)
ونُسب لأبي بكر الخفاف (ت٥٤٣هـ)
لكنه لا شك كتاب آخر غير كتاب الخفاف المسمى (سلوة الأحزان) والذي يفهم من نقولات الصفدي عنه أنه كتاب في رقائق الشعر ولطائف الأخبار.
وكيف يكون للخفاف وهو ينقل فيه أقوال الإمام النووي وابن قيم الجوزية وابن دقيق العيد والشيخ محمد المسعودي والعز ابن عبد السلام، وشهاب الدين ابن العماد، المولود عام (٧٥٠هـ) وابن الحاج صاحب المدخل', NULL, NULL, NULL, NOW(), NOW())
