INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('الأحمد نكري', 'مؤلف', 'القاضي عبد النبي بن عبد الرسول الأحمد نكري
قال في «الإعلام بمن في تاريخ الهند من الأعلام» (٦/ ٧٥٩ ط ابن حزم):
• الشيخ الفاضل القاضي عبد النبي بن عبد الرسول بن أبي محمد بن عبد الوارث العثماني الأحمد نكري.
• أحد العلماء المشهورين.
• وُلِد ونشأ بـ (أحمد نكر).
• وقرأ المختصرات على أبيه، وبعد وفاته على عبد الله الأحمد نكري، وسيد بخش الحسيني الكرماني الخير آبادي.
• ثم سافر إلى كجرات، وقرأ «الحاشية القديمة» وغيرها من الكتب الدرسية على الشيخ قطب الدين العثماني الكجراتي، وأكثرها على الشيخ محمد محسن ابن عبد الرحمن الصديقي الكجراتي، ولازمه مُدَّةً حتى صار أبدع أبناء العصر في النحو والمنطق.
• وولي القضاء بـ (أحمد نكر)، وكان يدرس ويفيد، أخذ عنه خلق كثير.
(ومن مصنفاته)
• «جامع الغموض ومنبع الفيوض»: شرح بسيط على كافية ابن الحاجب.
• و «دستور العلماء»، في اصطلاحات العلوم والفنون، في أربعة مجلدات.
• وحاشية بسيطة على شرح التهذيب لليزدي.
• وحاشية على مير زاهد ملا جلال.
• وحاشية دستور المبتدي: في الصرف.
• وحاشية على خلاصة الحساب للعاملي.
• وحاشية على أصول الحسامي.
• وحاشية على المطول.
• وحاشية على شرح العقائد للتفتازاني.
• وحاشية على حاشية الخيالي على شرح العقائد.
• وحاشية على الرشيدية شرح الشريفية في آداب البحث.
• وله «الأنموذج» المسمى بـ: «التحقيقات».
• وله «سيف المبتدين في قتل المفرورين».
• لم نعثر على سنة وفاته. وقد تم تأليف كتابه «دستور العلماء» في سنة ١١٨٣ هـ.
انتهى النقل من «الإعلام بمن في تاريخ الهند من الأعلام»، وقد قُيدَتْ سنة وفاته في مطبوعه رقمًا (١١٨٣) كما تقدم، لكن بالرجوع إلى خاتمة «دستوره» المطبوع ٤/ ١٣٦ نجده قد حَرّر تاريخ فراغه (بالحروف) فقال: «وخَتَمْتُ -بحسن توفيقه- هذا الكتاب: يوم الجمعة، رابع عشر من المحرم الحرام، المنتظم في سلك شهور ألف ومائة وثلاث وسبعين (١١٧٣) من الهجرة المقدسة، في البلدة الطيبة أحمد نكر» اهـ.', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('السويدي', 'مؤلف', 'السُّوَيْدي (١١٠٤ - ١١٧٤ هـ = ١٦٩٣ - ١٧٦١ م)
عبد الله بن حسين بن مرعي بن ناصر الدين البغدادي، أبو البركات السويدي: فقيه، متأدب، من أعيان العراق. وهو أول من عرف بالسويدي من هذا البيت. ولد في كرخ بغداد، وتوفي والده وهو طفل فكفله عمه لأمه (الشيخ أحمد سويد) وتعلم واشتهر. ورحل إلى بلاد الشام والحجاز وعاد إلى بغداد فتوفي فيها. له «الجمانة في الاستعارات - خ» و «إتحاف الحبيب - خ» حاشية على مغني اللبيب، و «أنفع الوسائل» في شرح دلائل الخيرات، و «شرح صحيح والبخاري» و «أسماء أهل بدر - ط» رسالة، و «الحجج القطعية لاتفاق الفرق الإسلامية - ط» رسالة، و «الأمثال السائرة - ط» مقامة وعظيمة، و «المحاكمة بين الدماميني والشمني» و «ديوان - خ» صغير، في الظاهرية يشتمل على منظوماته، و «النفحة المسكية في الرحلة المكية - خ» [ثم طُبع] وغير ذلك
نقلا عن: الأعلام للزركلي', NULL, '1693-01-01', '1761-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
