INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('الأنصاري، عبد الرحمن بن عبد الكريم', 'مؤلف', 'عبد الرحمن بن عبد الكريم الأنصاري(١١٢٤ هـ - ١١٩٥هـ)
جاء في سلك الدرر ، للمرادي ج٢ ص ٣٠٣ ما يلي :
عبد الرحمن بن عبد الكريم الحنفي المدني الشهير بالأنصاري الشيخ الفاضل الكامل المفنن الأديب الماهر وجيه الدين مؤرخ المدينة في عصره ولد بالمدينة المنورة ثاني عشر رجب سنة أربع وعشرين ومائة وألف (١١٢٤ هـ ) ونشأ بها وأخذ عن جملة من العلماء كالجمال عبد الله بن سالم البصري ومحمد أبي الطاهر بن إبراهيم الكوراني وأبي الطيب السندي ومحمد بن الطيب المغربي والشيخ سعيد سنبل وكان حافظاً متقناً خطيباً واماماً في المسجد النبوي وله تاريخ لطيف في أنساب أهل المدينة وخطب وشعر فمن شعره قوله وأرسله إلى علي أفندي الشرواني يستعير منه شرح الفقه الأكبر لعلي القاري
يا أيها المولى الذي أوصافه … كم أعجزت من كاتب مع قاري
امنن علي بشرح فقه امامنا … لسميك المنلا على القاري
لا زلت في عيش رغيد دائماً … أبداً وللعارفين نعم القاري
فأجابه
يا سيداً حاز المكارم والعلا … وسمت مكارمه على الأقدار
ل أشرقت آفاقنا من نير … من فضل مولانا على القاري
لسرى إلى أفلاككم مستكملاً … لضيائه كالكوكب السيار
لكنها قد عطلت أجيادها … فغدت لخجلتها ورا الأستار
فالعذر قد أبديته مستعفياً … وخيارنا العافون للأعذار
لا زلت في غر يدوم ورفعة … ما غرد القمري في الأسحار
وله غير ذلك من الأشعار والآثار الحسنة وكان آية باهرة في معرفة أنساب أهل المدينة وكانت وفاته في سابع عشر ذي القعدة سنة خمس وتسعين ومائة وألف (١١٩٥هـ) ودفن بالبقيع.', 'المذهب الحنفي', '1124-01-01', '1195-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


