    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('محمد بن علي بن غريب', 'مؤلف', 'محمد بن علي بن غَرِيب (٠٠٠٠ - ١٢٠٩ هـ)
الشيخ محمد بن علي بن غَرِيب، ويجعله بعض النسابين من بني (١) هاجر، وبعضهم يقول إنهم من الفداغمة من سنجارة من قبيلة شمر
• من كبار علماء نجد وفقهائهم
• ذكر محمد بن حميد في كتابه السحب الوابلة أنه صاهر الشيخ محمد بن عبد الوهاب رحمه الله، حيث تزوج ابنته التي مات عنها الشيخ حمد بن إبراهيم بن مشرف قاضي بلدة (مرات)، فهو من بيت علي النسب.
• من كبار تلاميذ الشيخ محمد بن عبد الوهاب وهو زميل لأبنائه. قال ابن حميد وردَّ على مخالفيهم - يعني المخالفين للدعوة السلفية - وأجاب عن عدة أسئلة في عدة فنون أرسلت إليهم من بغداد، فكان عندهم مقبولاً عظيماً
• ذكر ابن حميد أن المترجم تزوج بنت الشيخ محمد بن عبد الوهاب رحمه الله بعد أن توفي عنها زوجها الشيخ حمد بن إبراهيم المشرفي قاضي (مرات) فصار القاضي عبد العزيز بن حمد سبط الشيخ محمد بن عبد الوهاب وربيب صاحب هذه الترجمة.
• كان له نشاط في التعليم، وقد أخذ عنه الشباب النابه من طلاب العلم في الدرعية إبان نهضتها وزهرتها فكان من تلاميذه الشيخ الحافظ سليمان بن عبد الله ابن الشيخ محمد بن عبد الوهاب، ومنهم الشيخ النابغة القاضي عبد العزيز بن حمد بن مشرف، ومنهم الشيخ النبيل عبد العزيز بن حمد بن معمر وغيرهم م
