INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('عبد الهادي البكري', 'مؤلف', 'هذه نتفة من ترجمته مأخوذة من مقدمة محقق كتاب «تحقيق التجريد في شرح كتاب التوحيد»
اسمه ونسبه:
هو عبد الهادي [هادي] بن محمد بن عبد الهادي [هادي] بن بكري بن محمد بن مهدي بن موسى بن جعثم بن عجيل
.
ونلاحظ نسبته إلى البكري، وإلى العجيلي، وقد يطلق عليه وعلى أفراد أسرته آل الحفظي (أو الحفاظية) لأنه ولد لعبد القادر (أحد أبناء بكري) ولد اسمه أحمد اشتهر بالذكاء والحفظ فسمي أحمد الحفظي فغلب هذا الاسم وشمل حتى أبناء عمومته من أبناء عبد الهادي وغيره.
فالحفاظية من البكريين، والبكريون من العجيليين، فهي سلسلة نسب، والمؤلف متصل بهذه السلسلة فهو حفيد هادي بن بكري.
موطنه: وأما موطنه فبلاد عسير في قرية (رجال).
مولده ووفاته:
وأما عن مولده ووفاته فإن المصادر المخطوطة والمطبوعة التي وقفت عليها لم تذكر عنه شيئًا.
ثم قدر محقق الكتاب ذلك باجتهاده - بعد بحث - فقال : فمولده على ذلك بالتقدير لعله في العقد الثامن من القرن الثاني عشر (؟ ١١٧ هـ) ووفاته في العقد السابع من القرن الثالث عشر (؟ ١٢٦ هـ).', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


