INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('حمدان خوجة', 'مؤلف', 'حمدان خوجة (نحو ١١٨٩ - ١٢٥٥هـ / نحو ١٧٧٥ - ١٨٤٠م)
حمدان بن عثمان خوجة: كاتب سياسي، من رواد الحركة الوطنية الجزائرية.
ولد بمدينة الجزائر. وبها نشأ وتعلم. درس القانون على أبيه، ثم قام مقامه، بعد وفاته، وأصبح أستاذا في الحقوق المدنية والقوانين الإسلامية. وفي سنة ١٧٨٤م صحب خاله في زيارة لأهم مدن البلقان والقسطنطينية وغيرها. وفي سنة ١٨٢٠ زار فرنسا وتعلم اللغة الفرنسية. وبعد الاحتلال الفرنسي للجزائر، وعدم وفاء الفرنسيين بالشروط التي اشترطتها الحكومة التركية عليهم قبل أن تسلم لهم البلاد، نظم الجزائريون بزعامة حمدان أول حزب وطني سياسي عرف بلجنة المغاربة أو حزب المقاومة، فقارع حمدان الاستعمار الفرنسي بقلمه ولسانه، فنفاه الفرنسيون من الجزائر، فكان أول عربي مسلم يطرد من وطنه من قبل دولة أجنبية من أجل قضية وطنية. وبعد أن أقام مدة قصيرة في فرنسا (١٨٣٣ - ١٨٣٦م) سافر إلى القسطنطينية حيث اشتغل بالتأليف والترجمة، والتحرير لجريدة «تقويم وقائع» إلى حين وفاته.
من آثاره «المرآة» فرغ من تأليفه سنة ١٨٣٣م، و «إتحاف المنصفين والأدباء في الاحتراس عن الوباء». و «حكمة العارف بوجه ينفع لمسألة ليس في الإمكان أبدع» رسالة، شرح فيها قول الإمام الغزالي «ليس في الإمكان أبدع مما كان» فرغ منها سنة ١٢٥٢هـ (١٨٣٧ م). و «ستار الاتحاف» وهي ترجمة تركية لرسالة «الإتحاف» السابقة، وغير ذلك. وللدكتور محمد بن عبد الكريم كتاب «حمدان بن عثمان خوجه الجزائري ومذكراته» كما قام الدكتور بن عبد الكريم بنقل كتاب المرآة إلى العربية، وبتحقيق رسالة إتحاف المنصفين.
معجم أعلام الجزائر (ص: ١٣٦ - ١٣٧)', NULL, '1775-01-01', '1840-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('التسولي', 'مؤلف', 'التُّسُولي (٠٠٠ - ١٢٥٨ هـ = ٠٠٠ - ١٨٤٢ م)
علي بن عبد السلام بن علي، أبو الحسن التسولي: فقيه، من علماء المالكية، تسوليّ الأصل والمولد. يلقب «مديدش» نشأ بفاس.
وولي القضاء بها، ثم بتطوان وغيرا. وتوفي بفاس. له «شرح مختصر الشيخ بهرام» في الفقه و «الهجة - ط» شرح لتحفة الحكام لابن عاصم، مجلدان، و «شرح الشامل» في عدة مجلدات، و «حاشية على شرح التاودي للامية الزقاق - ط» فقه، و «وثائق الزياتي» جمعها ورتبها. و «النوازل - خ» مجلد منه، في خزانة الرباط (٨٨٢ د) و «جواب على سؤال لعبد القادر الجزائري - خ» ٣٣ ورقة في خزانة الرباط. وله فتاوى وتقاييد
نقلا عن: الأعلام للزركلي', 'المذهب المالكي', '1258-01-01', '1842-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
