INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('صبغة الله المدراسي الهندي', 'مؤلف', 'قاضي الملك محمد صبغة الله بن محمد غوث بن محمد ناصر الدين المدارسي الهندي الشافعي ت ١٢٨٠ هـ
و هو جد الدكتور محمد حميد الله المتوفى في صيف ٢٠٠٧م
