INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('عبد الرحمن بن حسن آل الشيخ', 'مؤلف', 'عبد الرحمن بن الحسن (١١٩٣ - ١٢٨٥ هـ = ١٧٧٩ - ١٨٦٩ م)
عبد الرحمن بن حسن بن محمد بن عبد الوهاب: فقيه حنبلي، من علماء نجد.
مولده في الدرعية. وهو حفيد العلامة ابن عبد الوهاب صاحب الدعوة إلى التوحيد، المعروفة باسمه.
ويعرف هذا البيت بآل الشيخ.
تفقه عبد الرحمن بنجد ثم بمصر.
وكان قد نقله إليها إبراهيم (باشا) بعد استيلائه على الدرعية، فيمن نقل من آل سعود وآل الشيخ.
وعاد إلى نجد (سنة ١٢٤١ هـ) فاشتهر في أيام
الإمام تركي بن عبد الله.
وتولى قضاء الرياض.
ثم كان مع الإمام فيصل بن تركي إلى أن خرج هذا من الرياض (سنة ١٢٥٢ هـ) فانصرف عبد الرحمن إلى الحوطة والحريق (من بلاد نجد) وعاد إلى الرياض، بعد عودة فيصل الأخيرة، فلازمه في السفر والإقامة والحرب والسلم.
وتوفي بها وقد قارب المئة.
له كتب، منها (الإيمان والرد على أهل البدع - ط) و (مجموعة رسائل وفتاوى - ط) و (فتح المجيد، شرح كتاب التوحيد - ط) والأصل لجده
نقلا عن : الأعلام للزركلي', NULL, '1779-01-01', '1869-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('اليازجي، ناصيف', 'مؤلف', 'ناصيف اليازجي (١٢١٤ - ١٢٨٧ هـ = ١٨٠٠ - ١٨٧١ م)
ناصيف بن عبد الله بن ناصيف بن جنبلاط، الشهير باليازجى، نصراني الديانة: شاعر من كبار الأدباء في عصره.
أصله من حمص (بسورية) ومولده في (كفرشيما) بلبنان، ووفاته ببيروت. استخدمه الأمير بشير الشه أبي في أعماله الكتابية نحو ١٢ سنة، انقطع بعدها للتأليف والتدريس في بعض مدارس بيروت، وتوفى بها. له كتب، منها (مجمع البحرين - ط) مقامات و (فصل الخطاب - ط) في قواعد اللغة العربية، و (الجوهر الفرد - ط) في فن الصرف، و(نار القرى في شرح جوف الفرا - ط) في النحو، و (مختارات اللغة - خ) بخطه، و (العرف الطيب في شرح ديوان أبى الطيب - ط) هذبه وأكمله إبراهيم، و (ثلاثة دواوين شعرية) سماها: (النبذة الأولى - ط) و (نفحة الريحان - ط) و (ثالث القمرين - ط) ولعيسى ميخائيل سابا كتاب (الشيخ ناصيف اليازجي - ط) في أدبه وسيرته
نقلا عن : الأعلام للزركلي', NULL, '1800-01-01', '1871-01-01', NOW(), NOW())
