INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('محمد بن المبارك الجزائري', 'مؤلف', 'محمَّد بن المُبَارَك الجزائري (١٢٦٣ - ١٣٣٠ هـ = ١٨٤٧ - ١٩١٢ م)
قال الزركلي في (الأعلام):
محمد بن محمد بن المُبارك الحسني الجزائري الدمشقيّ: فاضل، أصله من الجزائر. انتقلت عائلته إلى دمشق مع الأمير عبد القادر الجزائري. ولد في بيروت وتعلم بدمشق، وأقام وتوفي بها. له (ست رسائل - ط) في الأدب، اسم الأولى (غناء الهزار) وله (المقامات العشر لطلبة العصر - خ) اختارها من المقامات الحريرية (استدركه عبيد). وله شعر
وقال جمال الدين القاسمي في (تعطير المشام):
وكان يجيد تصحيح ما يقرؤه ويراجع لضبطه كتب اللغة ويقابله على أصوله، وله دقة في ذلك، وقد استعرتُ من مصححاته كتاب: «سيرة ابن هشام» وكتاب «الذريعة» للراغب الأصفهاني، وكتاب «المقصد الأسنى في شرح الأسماء الحسنى»، وكان قد عني بتصحيحها وضبطها', NULL, '1847-01-01', '1912-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
