INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('سليمان بن سحمان', 'مؤلف', 'ابن سحمان (١٢٦٨ - ١٣٤٩ هـ = ١٨٥٢ - ١٩٣٠ م)
سليمان بن سحمان بن مصلح بن حمدان النجدي، الدوسري بالولاء: كاتب فقيه، له نظم فيه جودة. من علماء نجد.
ولد في قرية (السقا) (بتخفيف القاف) من أعمال (أبها) في عسير.
وانتقل مع أبيه إلى الرياض، أيام فيصل بن تركي، فتلقى عن علمائها التوحيد والفقه واللغة.
وتولى الكتابة للإمام عبد الله بن فيصل، برهة من الزمن، ثم تفرغ للعلم.
وصنف كتبا ورسائل، منها (الضياء الشارق في رد شبهات الماذق المارق - ط) في الرد على كتاب لجميل صدقي الزهاوي، و (الهدية السنية - ط) و (تبرئة الشيخين - ط) و (منهاج أهل الحق والاتباع - ط) رسالة، و (الصواعق المرسلة - ط) و (إرشاد الطالب إلى أهم المطالب - ط) ورسالة في (الساعة - ط) وأنها صناعة لا سحر ! و (إقامة الحجة والدليل - ط) و (الفتاوى - ط) وديوان شعر سماه (عقود الجواهر المنضدة الحسان - ط) وغير ذلك.
وكف بصره في آخر حياته، توفي في الرياض
نقلا عن : الأعلام للزركلي', NULL, '1852-01-01', '1930-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('محمد عبد العزيز الخولي', 'مؤلف', 'محمد عبد العزيز الخَوْلي (١٣١٠ - ١٣٤٩ هـ = ١٨٩٢ - ١٩٣١ م)
محمد عبد العزيز بن علي الشاذلي الخَوْلي:
من علماء الشريعة بمصر.
ولد في (الحامول) من أعمال المنوفية، وتخرج بمدرسة القضاء الشرعي بالقاهرة، وتوفي بها.
له كتب، منها:
(مفتاح السنّة أو تاريخ فنون الحديث - ط)
و (الأدب النبوي - ط)
و (إصلاح الوعظ الديني - ط)
نقلا عن: الأعلام للزركلي', NULL, '1892-01-01', '1931-01-01', NOW(), NOW())
