INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('الشقيري', 'مؤلف', 'هو الشيخ العلامة محمد بن أحمد عبد السلام خضر الشقيري الحوامدي مؤسس الجمعية السلفية بالحوامدية بمحافظة الجيزة بمصر.
قال عنه الشيخ محمد حامد الفقي في تقديمه لكتاب السنن والمبتدعات: الصالح المجاهد الصابر المحتسب. انتهى.
وقال الشيخ رشيد رضا في تقريظه لهذا الكتاب: تأليف الداعي إلى السنة والصاد عن البدعة الشيخ محمد عبد السلام خضر الشقيري الحوامدي مؤسس الجمعية السلفية بالحوامدية.
وقال الشيخ الشقيري في خاتمة كتابه السنن والمبتدعات: قد كنت ابتدأت في تأليف هذا الكتاب بعد صلاة العشاء من يوم ٢٩ رجب الحرام سنة ١٣٥١، وانتهيت من ترتيبه قبل غروب شمس يوم السبت ٢٩ ذي الحجة سنة ١٣٥٢هجري.
وأما سنة وفاة الشيخ فلم نقف عليها. والله أعلم.
نقلا عن : فتاوى الشبكة الإسلامية', NULL, NULL, NULL, NOW(), NOW())
