INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('عبد الرحمن المباركفوري', 'مؤلف', 'عبد الرحمن المباركفوري (٠٠٠ - ١٣٥٣ هـ = ٠٠٠ - ١٩٣٤ م)
عبد الرحمن المباركفوري ، عالم مشارك في أنواع من العلوم.
ولد في بلدة مباركفور من أعمال أعظمكره، ونشأ بها، وقرأ العلوم العربية والمنطق والفلسفة والهيئة والفقه وأصول الفقه على علماء كثيرين.
من مؤلفاته: السنن في مجلدين.
وتحفة الأحوذي في شرح سنن الترمذي
نقلا عن : معجم المؤلفين لعمر رضا كحالة - بتصرف يسير ولم يذكر كتابه تحفة الأحوذي ضمن مؤلفاته
_________
(*) فائدة :
هناك مجموعة من العلماء يعرفون بالمباركفوري لكونهم ينتسبون إلى مدينة (مباركفور) بالهند منهم أبو العلا عبد الرحمن المباركفوري صاحب تحفة الأحوذي في شرح سنن الترمذي (ت : ١٣٥٣ هـ) ، وتلميذه عبيد الله المباركفوري صاحب مرعاة المفاتيح شرح مشكاة المصابيح (ت : ١٤١٤ هـ) ، وتلميذ عبيد الله وهو صفي الرحمن المباركفوري صاحب الرحيق المختوم وأمير جماعة أهل الحديث بالهند (ت : ١٤٢٧ هـ).', NULL, '1353-01-01', '1934-01-01', NOW(), NOW())
