    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('مصطفى السباعي', 'مؤلف', 'مصطفى بن حسني السباعي
• من مواليد مدينة حمص في سورية عام ١٩١٥ م
• نشأ في أسرة علمية عريقة معروفة بالعلم والعلماء منذ مئات السنين، وكان والده وأجداده يتولون الخطابة في الجامع الكبير بحمص جيلاً بعد جيل
(من مؤلفاته)
• شرح قانون الأحوال الشخصية (ثلاثة أجزاء)
