INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('عبد الله عبادى اللحجى', 'مؤلف', 'الشيخ: عبد الله بن سعيد بن محمد عبادي اللّحجي الحضرميّ الشحاري، ثم المراوعي، ثم المكي.
ولد سنة: ١٣٤٣ بقرية نوبة عياض من قرى لحج، ثم سافر إلى المراوعة قبل البلوغ؛ وهو في الثانية عشرة لطلب العلم،
فأخذ عن مشايخها ، ومنهم السيد عبد الرحمن بن محمد الأهدل
ومن شيوخ الشيخ اللحجي في المراوعة: الشيخ العلامة السيد: عبد الرحمن بن حسن بن عبد الله بن محمد معوّضه قاسم الأهدل المروعي
ومن شيوخ الشيخ عبد الله اللحجي في اليمن: الشيخ العلّامة الحبر البحر الفهّامة أبو الفضائل عزّ الدين السيد: محمد حسن هند بن عبد الباري بن محمد بن حسن بن عبد الباري الأهدل
رحل إلى مكة سنة: ١٣٧٤ هـ، ومكث بها سنة واحدة، ثم عاد إلى اليمن، ثم رجع إلى الحجاز عام: ١٣٧٧ هـ؛ واستقرّ به المقام في مكة المكرمة إلى وفاته.
ومن شيوخه بمكّة المكرمة، الشيخ: حسن بن محمد المشّاط المكّي المالكي
والشيخ محمد العربي ابن التبّاني الواحدي الجزائري المكي
وفاته
بعد حياة حافلة بالخير وطلب العلم والتدريس تحت أروقة الحرم المكي الشريف؛ انتقل الشيخ عبد الله اللحجي إلى رحمة الله تعالى ليلة الأحد الموافق للسادس والعشرين جمادى الأولى: ١٤١٠ هـ بمكّة المكرمة بعد مرض خفيف استمرّ يومين؛ أو ثلاثة.
وصلّي عليه يوم الأحد بالمسجد الحرام وشيعت جنازته التي حضرها حشد كبير من العلماء والطلاب ومحبّيه رحمه الله رحمة الأبرار والصالحين.', 'المذهب المالكي', NULL, NULL, NOW(), NOW())
