INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('مقداد يالجن', 'مؤلف', 'مِقْداد يالجن (١٣٥٦ - ١٤٤٢ هـ= ١٩٣٧ - ٢٠٢٠ م)
مقداد يالجن محمد علي:
أستاذ جامعي، تركي، التحق بمدرسة تحفيظ القرآن في إنطاكية (تركيا) لتعلم اللغة العربية وفهم القرآن، ثم درس في مدارس سوريا المتوسطة، والتحق بعد ذلك بالثانوية الأزهرية ثم بكلية أصول الدين بجامعة الأزهر. وقد حصل بعد ذلك على الليسانس في اللغة العربية والعلوم الإسلامية من كلية دار العلوم جامعة القاهرة عام ١٩٦٧ م، وعلى الماجستير في عام ١٩٧١ م، كما حصل على دبلوم في التربية.
وفي عام ١٩٧٦ م، حصل على درجة الدكتوراه. عمل بالتدريس في كلية الإلهيات بجامعة أنقرة، ثم عضوًا بهيئة التدريس في قسم التربية بكلية العلوم الاجتماعية بجامعة الإمام محمد بن سعود الإسلامية. من أشهر مؤلفاته التي نُشرت، اثنا عشر كتابًا في مجال التربية الإسلامية والمجالات القريبة، منها: جوانب التربية الإسلامية؛ أهداف التربية الإسلامية
علاوة على أكثر من عشرين بحثًا ومقالاً في مجالات مختلفة
حاز جائزة الملك فيصل العالمية للدراسات الإسلامية عام ١٤٠٨ هـ، ١٩٨٨ م.', NULL, '1937-01-01', '2020-01-01', NOW(), NOW())
ON DUPLICATE KEY UPDATE 
