INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('أحمد آل إبراهيم العنقري', 'مؤلف', 'هو الشيخ: أحمد بن عبد الرزاق بن الشيخ محمد بن زيد بن إبراهيم بن الشيخ عبد الوهاب آل إبراهيم العنقري التميمي (من آل إبراهيم الدورة الكويت) وكان جده الشيخ عبد الوهاب آل ابراهيم أكبر مالك للسفن الشراعية في الكويت والعناقر من سلالة الصحابي الجليل: قيس بن عاصم المنقري رضي الله عنه سيد أهل الوبر.
* تخصص الشيخ في علوم القرآن والقراءات العشر.
* قرأ الشيخ أحمد بن عبد الرزاق آل إبراهيم القرآن وحفظه على عدد من المشائخ منهم العلامة الشيخ / سيد محمد ساداتي الشنقيطي وعلى العلامة الزيات والعلامة الشيخ / محمد مهدي نصر الدين وعلى الشيخ العلامع محمد عبد الحميد وكذلك طلب العلم عند العلامة الشيخ / جمال القرش وقد أجازه بجميع كتبه بعد الاختبار منها (كتاب الوقف الازم في القرآن وكتاب كلا وبلى ونعم في القرآن , وكتاب المخارج والصفات ,, وكتاب التمهيد في علم التجويد) والشيخ موسى الافغاني وغيرهم.
* طلب علم الحديث على الشيخ العلامة المحدث الشيخ / عبد الله السعد .. واجازه بالكتب الستة وهي (البخاري ومسلم وابو داود والترمذي والنسائي وابن ماجة) وطلب الشيخ أحمد آل إبراهيم علم الفقه والعقيدة على الشيخ الفقيه إبراهيم التركي وقد حضر الشيخ أحمد خمس سنوات متواصلة عند العلامة الشيخ / عبد الرحمن البراك , وقد تعلم منه علم العقيدة والتوحيد على منهج أهل السنة والجماعة والسلف الصالح.
* يحفظ الشاطبية وهي ١٠٧٣بيت ويحفظ المقدمة الجزرية بسندها وغيرها.
* باحث في الأنساب … وله بحوث ومقالات في ذلك
* له مؤلفات منها كتابه الأربعون القرآنية
* له مجلس لتعليم علوم القرآن ودروس وهو مستقرا حاليا بالرياض.', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('محمد بن عبد الله المقشي', 'مؤلف', 'الدكتور محمد بن عبد الله المقشي من مواليد سنة ١٩٧٩ م في مديرية كحلان عفار، محافظة حجة، الجمهورية اليمنية.
• البكالوريوس من كلية الشريعة بجامعة الإيمان بتقدير ممتاز ١٤٢٣ هـ - ٢٠٠٣ م.
• الماجستير من نفس الجامعة في الفقه الإسلامي وأصوله بتقدير ممتاز ١٤٢٧ هـ - ٢٠٠٦ م.
• الدكتوراه في الفقه المقارن من جامعة أم درمان الإسلامية بتقدير ممتاز ١٤٣٢ هـ - ٢٠١١ م.
• وحصل على الكثير من الإجازات العلمية العامة والخاصة في مختلف فنون الشريعة، ومن أبرز الإجازات الخاصة:
١ - الإجازة العمرانية العلمية العليا في التدريس والفتوى والدعوة والقضاء من علامة اليمن ومفتيها القاضي/ محمد بن إسماعيل العمراني.
٢ - إجازة بالتدريس والإفتاء من الفقيه الأصولي الأستاذ الدكتور/ حسن محمد مقبولي الأهدل رحمه الله تعالى.
٣ - إجازتان علميتان في فقه المعاملات المالية وتطبيقاتها المعاصرة، وفقه الجنايات والحدود من العلامة الأستاذ الدكتور/ وهبة بن مصطفى الزحيلي رحمه الله تعالى.
٤ - إجازة الفقيه الزاهد العلامة/ حميد بن قاسم بن عقيل. مفتي مدينة جبلة.
٥ - إجازة الفقيه العلامة علي بن سالم بن سعيد بُكيِّر.
(من مؤلفاته)
١ - فتح الكريم اللطيف في شرح باكورة التعريف بالمهم من التصريف.
٢ - مذهب السلف والأئمة أن القرآن العربي المثبت بين دفتي المصحف كلام الله تعالى غير مخلوق كيفما تصرف.
٣ - مذهب جمهور الأشاعرة في القرآن باطنه الاعتزال وظاهره التستر بمذهب السلف.
٤ - المجموع الثمين في حكم دعاء غير رب العالمين.
٥ - المعنى في صفات الله تعالى معلوم والكيف مجهول.
٦ - القول في بعض صفات الله تعالى كالقول في البعض الآخر.
٧ - الإمام المقبلي وموقفه من أشهر الآراء الاعتزالية.
٨ - سُلَّم المتون في مختلف الفنون.', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


