INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('دبيان الدبيان', 'مؤلف', '•أبو عمر دُبْيَانِ بن محمد الدُّبْيَانِ
من مواليد بريدة عام ١٣٧٩ هـ.
• حاصل على درجة البكالوريوس بتقدير (ممتاز) من كلية الشريعة بجامعة الإمام محمد بن سعود الإسلامية فرع القصيم.
• يعمل حالياً مستشاراً شرعياً في وزارة الشؤون الإسلامية بالقصيم.
• صدر له الكتب التالية:
١ - موسوعة أحكام الطهارة (١٠ أجزاء ط ٣ المعتمدة).
٢ - موسوعة (المعاملات المالية أصالة ومعاصرة) (٢٠ جزءا)
٣ - الجامع في أحكام صفة الصلاة (٤ أجزاء)
٤ - موسوعة أحكام الصلوات الخمس (١٨ جزءا)
٥ - مظاهر الإنصاف في كتاب الإنصاف.
٦ - الإيجاب والقبول بين الفقه والقانون.', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


