INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('منصور الصقعوب', 'مؤلف', 'منصور بن محمد بن عبد الله الصقعوب
• عضو الدعوة والإرشاد بوزارة الشؤون الإسلامية بالمملكة العربية السعودية، فرع القصيم
• إمام وخطيب جامع الحبلين ببريدة.
• من مواليد عام ١٣٩٨ هـ في بريدة بمنطقة القصيم، بالمملكة العربية السعودية.
• أتم حفظ القرآن في عام ١٤١٣ هـ، وشرع في تلك السنة في حفظ السنّة، فحفظ مختصر صحيح مسلم للمنذري، ثم زيادات البخاري عليه، ثم زيادات الكتب الستة، وحفظ جملةً من المتون العلمية الأخرى.
• طلب العلم عند جماعة من أهل العلم، منهم: الشيخ عبد الكريم الخضير، والشيخ خالد المشيقح، والشيخ عبد الله الغنيمان، والشيخ عبد الله بن صالح الفوزان، والشيخ إبراهيم اللاحم، والشيخ تركي الغميز، وغيرهم.
(مؤهلاته العلمية)
• البكالوريس: جامعة الإمام محمد بن سعود الإسلامية، فرع القصيم، عام ١٤١٩ هـ/١٤٢٠ هـ.
• الماجستير: بامتياز من جامعة القصيم، قسم السنة وعلومها، عام ١٤٣٢ هـ، وكانت رسالته بعنوان: الاختلاف الوارد في القصص والأحداث في عهد النبي النبي صلى الله عليه وسلم بين اتحاد القصة وتعددها.
• الدكتوراه: بامتياز مع مرتبة الشرف الأولى: من الجامعة الإسلامية بالمدينة النبوية، كلية الحديث الشريف، قسم فقه السنة، وكان عنوان الرسالة: التحقيق في أحاديث التعليق لابن الجوزي، تحقيق ودراسة، من باب الغصب، حتى آخر الكتاب.
(من مؤلفاته)
• بغية المستفيد شرح كتاب التوحيد.
• تقريب الوصول إلى ثلاثة الأصول.
• التعليق المقنع على زاد المستقنع.
• شرح منظومة القواعد الفقهية لابن سعدي.
• الوقائع النبوية، بين اتحاد القصة وتعددها.
• الحلل البهية فى شرح الأربعين النووية', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


