INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('عبد العزيز بن فيصل الراجحي', 'مؤلف', 'عبد العزيز بن فيصل الراجحي
المؤهل: كلية الشريعة - جامعة الامام محمد بن سعود الإسلامية (لم يكمل).
تاريخ الميلاد: ١٩٧٤ م.
الجنسية: السعودية.
درس على مجموعة كبيرة من العلماء والمشايخ داخل المملكة وخارجها - منهم سماحة الشيخ عبد العزيز بن عبد الله بن باز - الشيخ عبد الله بن عبدالرحمن ابن جبرين - الشيخ صالح بن فوزان بن عبد الله الفوزان - الشيخ عبد الرحمن بن ناصر البراك. وغيرهم الكثير من العلماء والمشايخ.
المشاركات العلمية:
• مثل (مركز الملك فيصل للبحوث والدراسات الإسلامية) في بعض المؤتمرات الدولية كما شارك في بعض الدورات العلمية - واللقاءات الحوارية بالمركز وغيره والقى عدداً من المحاضرات والدروس.
عمله في (مركز الملك فيصل للبحوث والدراسات الإسلامية):
• مدير (اداراة المجموعات الخاصة) المشتملة على المخطوطات الأصلية والمصورة والوثائق والكتب النادرة.
له عدد من المؤلفات من كتب وتحقيقات ومقالات وبحوث، على سبيل المثال:
• ذخيرة المعاد، في حجية خبر الآحاد في الاعتقاد.
• قدوم كتائب الجهاد - لغزو أهل الزندقة والإلحاد، القائلين بعدم الأخذ بحديث الآحاد في مسائل الاعتقاد.
• قمع الدجاجلة، الطاعنين في معتقد أئمة الإسلام الحنابلة (رد على حسن بن فرحان المالكي في كتابه (قراءة في كتب العقائد).
• مجانبة أهل الثبور المصلين في المشاهد وعند القبور', 'المذهب المالكي', NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


