INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('إبراهيم العبيد', 'مؤلف', 'عضو هيئة التدريس في كلية الحديث، الجامعة الإسلامية بمدينة المدينة المنورة، المملكة العربية السعودية
[المؤهلات العلمية]
١. ليسانس شريعة من جامعة الإمام محمد بن سعود الإسلامية ١٤٠٦ هـ
٢. ماجستير من قسم فقه السنة ومصادرها بكلية الحديث الشريف بالجامعة الإسلامية ١٤١٠هـ
٣. دكتوراه من قسم فقه السنة ومصادرها بكلية الحديث الشريف بالجامعة الإسلامية ١٤١٥هـ
[التدرج الوظيفي]
١. معيد: ٢٠/ ٩/١٤٠٦هـ
٢. محاضر: ١٢/ ٢/١٤١١هـ
٣. أستاذ مساعد: ١٤/ ٢/١٤١٦هـ
٤. أستاذ مشارك: ٥/ ١١/١٤٢٢هـ
٥. أستاذ: ٤/ ١٢/١٤٢٤هـ.
[البحوث والكتب]
١. جامع أحاديث وآثار القراءة في الصلاة جمعاً ودراسة - دار المنهاج
٢. تحقيق كفاية المستقنع لأدلة المقنع للمردادي - لم يطبع
٣. تحقيق جزء من البدر المنير لابن الملقن (ثلاث مجلدات) - دار العاصمة
٤. جهود الجامعة الإسلامية في خدمة السنة النبوية من خلال كلية الحديث الشريف مجمع الملك فهد لطباعة المصحف الشريف
٥. إجابة الدعوة مجلة الجامعة الإسلامية - دار ابن الجوزي
٦. شروط إجابة الدعوة - دار ابن الجوزي
٧. أذكار الأذان والإقامة جمعاً ودراسة - مجلة جامعة أم القرى
٨. سنة الجمعة البعدية رواية ودراية - لم يطبع
٩. الأحاديث والآثار الواردة في الصلاة قبل الجمعة رواية ودراية - مجلة جامعة أم القرى
١٠. الأحاديث الواردة في القراءة في صلاة الفجر - مجلة الجامعة الإسلامية
١١. الأحاديث الواردة في القراءة في صلاتي الظهر العصر - مجلة الجامعة الإسلامية
١٢. الأحاديث الواردة في القراءة في صلاتي المغرب والعشاء - مجلة الجامعة الإسلامية
١٣. الأحاديث الواردة في الأكل والشرب قائما رواية ودراية - مجلة جامعة أم القرى
١٤. حديث عمر رضي الله عنه في نوم الجنب رواية ودراية - مجلة جامعة أم القرى', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('عمر عبد الكافي', 'مؤلف', 'الأستاذ الدكتور عمر عبد الكافى شحاتة أحد الدعاة إلى الله فى العصر الحديث من مواليد محافظة (المنيا) بصعيد مصر، نشأ فضيلته فى أسرة طيبة ملتزمة تتكون من أب وهو أحد أعيان الوجه القبلى بمصر وأم تحفظ -بفضل الله- أغلب القرآن الكريم وثلاثة إخوة وبنتين.
حفظ القرآن الكريم وهو فى العاشرة من عمره والتحق بالتعليم العام وسار فيه بتفوق واضح وظل ينتقل فى مراحل التعليم حتى تخرج من كلية الزراعة وعين معيدا بها وحصل على الماجستير والدكتوراة فى العلوم الزراعية، وعمل فضيلته كذلك باحثا بالمركز القومى للبحوث وأستاذا بأكاديمية البحث العلمى.
تنقل فضيلته وهو صغير بين أيدى أساتذة وعلماء فى شتى العلوم الشرعية من فقه وتوحيد وتفسير وسيرة وأصول فقه وعلوم حديث، وحفظ على يد أساتذته صحيحى البخارى ومسلم بالأسانيد عن ظهر قلب وكان لهذا الحفظ أثره الواضح فى تلقيه العلم طوال سنوات عمره
وتزوج فضيلته من حفيدة العلامة الإسلامى الشيخ محب الدين الخطيب وله من الأبناء خمسة هم أحمد وبلال وعمار وهدى وندى، وبعد تخرجه من كلية الزراعة انتسب فضيلته إلى كلية الدراسات العربية والإسلامية وحصل منها على الليسانس ثم الماجستير فى الفقه المقارن.
والشيخ عاشق للغة العربية وآدابها وعلومها لذا فقد درس البلاغة والنحو والصرف وحفظ كثيرا من المتون كألفية بن مالك وغيرها، ولم يترك كتابا كتب عن الإسلام بالعربية أو الإنجليزية وقع في يده إلا قرأه واستوعبه ودون عليه ملاحظات فى مذكراته.
تأثر كثيرا بشخصية أبى حنيفة وابن تيمية والحسن البصرى وأبى حامد الغزالى وفى السنوات التى كان فيها عضوا بالهيئة العالمية للإعجاز العلمى برابطة العالم الإسلامى عاصر وعايش كثيرا من علماء العالم الإسلامى فى شتى العلوم والثقافات.
- أسهم فضيلته بنصيب وافر فى مجال الدعوة إلى الله عز وجل - فقد بدأ يخطب الجمعة ويلقى دروس العلم فور تخرجه من الجامعة عام ١٩٧٢ م، وكان له درسان يومى الإثنين والخميس طيلة عشرين عاما، له دروس علم ومجموعات منتظمة ألقيت على مدى فترات طويلة منها: الدار الآخرة، وشرح صحيح البخارى، والسيرة النبوية، وقصص الأنبياء، عدا خطب الجمعة التى تربو على (١٢٠٠) خطبة، كذلك فقد بلغت دروسه قرابة الـ (٣٠٠٠) درس مدة كل درس ساعة ونصف.
كما يشغل الشيخ العديد من المناصب من بينها عضو في هيئة الحكماء للاتّحاد العالمي لعلماء المسلمين ومدير مركز الدّراسات القرآنية بمؤسّسة جائزة دبي الدّولية للقرآن الكريم وغيرها من المناصب.
يوصى فضيلته كل مسلم أن يكون على ثغر من ثغور الإسلام وأن يحمل كل مسلم هم الإسلام وهموم الأمة وأن يثق أن السباحة ضد التيار أمر ليس بالسهل ولا اليسير ويوصى الدعاة والعلماء بأن يخلصوا النية فى عملهم فهم ورثة الأنبياء، وأن يعطوا الدعوة كل وقتهم لا فضول أوقاتهم وأن لا يهنوا ولا يحزنوا إن حوربوا فهم دعاة الحق.
نسأل الله -عز وجل- أن يمد فى عمر فضيلته وأن يبارك فيه وعليه وأن يجعله ذخرا للإسلام والمسلمين، وأن يتقبلنا وإياه فى الصالحين، وآخر دعوانا أن الحمد لله رب العالمين.', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


