INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('عبد الهادي بن حسن وهبي', 'مؤلف', 'نشأته
وُلِدَ فضيلة الشيخ عبد الهادي بن حسن وهبي - حفظه الله - في بيروت عام ١٣٧٨ هـ الموافق ١٩٥٨ م، ونشأ فيها حيث تلقى علومه الابتدائية والثانوية في مدارسها، ثم سافر إلى الرياض، حيث التحق بجامعة الامام محمد بن سعود -رحمه الله- قسم السنة وعلومها.
وقد أنهى الشيخ دراسته الجامعية عام ١٤٠٥ هـ الموافق ١٩٨٥ م.
نشاطه الدعوي:
بعد ذلك: عاد فضيلته إلى بيروت ليبدأ طريقه الشاق، في غرس بذور الخير فيها، فبدأ باكورة نشاطه بالتدريس في مساجد بيروت، بالحكمة والموعظة الحسنة، مع التركيز على مبدأ التصفية والتربية كمنهج اقتنع الشيخ أنه من انفع ما يحتاج إليه المسلمون عموماً، وبالأخص في لبنان، حيث تعصف رياح الشبهات، وتكثر البدع والخرافات؛ فسار الشيخ حفظه الله بعكس التيار، ليواجه مع تلامذته وإخوانه ذاك الكم الهائل من الضغوطات والمصاعب، إلى أن بارك الله عز وجل، فآتت دعوة الشيخ ثمارها، وأينعت بفضل الله، حيث كان أول قطافها: تأسيس الشيخ مع بعض إخوانه الفضلاء "جمعية السراج المنير الإسلامية" في بيروت، وذلك عام ١٤٠٧هـ -الموافق ١٩٨٦ م، والتي يرأس الشيخ مجلس إدارتها إلى يومنا هذا.
ولا يفوتنا أن نذكر أن الله يسَّرَ للشيخ الالتقاء بكثير من أهل العلم في العالم الاسلامي، من أبرزهم: سماحة الوالد الشيخ عبد العزيز بن باز، وسماحة العلامة المحدث الشيخ محمد ناصر الدين الألباني، والعلامة الفقيه محمد بن صالح العثيمين-رحم الله الجميع- بالإضافة إلى غيرهم.
وللشيخ مشاركات في التدريس في العديد من الدورات العلمية خارح لبنان
وقد أمضى الشيخ كذلك قرابة العشر سنوات مدرِّساً في معهد الإمام البخاري للشريعة الإسلامية في عكار-شمال لبنان.
وقد كان لقراءة الشيخ لكتب شيخ الاسلام الثاني -ابن قيم الجوزية رحمه الله تعالى - وتركيزه عليها، الأثر البالغ والكبير في نفسه، مما جعله يتجه للتركيز على الجوانب الإيمانية، المتعلقة بتهذيب النفس ومجاهدتها، في دروسه ومحاضراته، ما ساهم في التفاف الناس حوله، ونظرتهم إليه بكونه والداً للجميع، مربياً ومصلحاً ومعلما. إلى جانب اهتمامه بنشر التوحيد، والعقيدة السلفية، منتهجاً في ذلك منهج العلماء الربانيين، أمثال الشيخ ابن باز والشيخ الألباني والشيخ ابن عثيميين.
مؤلفات الشيخ:
لقد من الله عز وجل على شيخنا بهمة عالية في التأليف، حيث صدر له العديد من المؤلفات والرسائل، نذكر منها:
١ - الكلمات الحسان في بيان علو الرحمن.
٢ - الأسماء الحسنى والصفات العلى.
٣ - غاية البيان في إثبات علو الرحمن.
٤ - الحصن الحصين من الشيطان الرجيم.
٥ - تذكير الإنسان بحفظ العين واللسان.
٦ - تذكير الإنسان بعداوة الشيطان.
٧ - تذكير الأنام بفضل صلاة القيام.
٨ - إصلاح القلوب.
٩ - آثار الذنوب على الأفراد والشعوب.
١٠ - الخصال الموجبة لدخول الجنة.
١١ - تحذير السالك من المهالك.
١٢ - التوبة طريق إلى الجنة.
١٣ - وقفات قبل الفوات.
١٤ - في ظلال التقوى.
١٥ - تحفة الأبرار بفضائل الأذكار.
١٦ - صفة المحبة من الكتاب والسنة.
١٧ - الخصال المنجية في الدنيا والآخرة.
١٨ - الدرر الثمينة من الأدعية النبوية.
١٩ - أزمة خلقية.', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


