INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('سعيد بن ناصر الغامدي', 'مؤلف', 'سعيد بن ناصر الغامدي
أستاذ مساعد في قسم العقيدة والمذاهب المعاصرة في كلية الشريعة وأصول الدين - جامعة الملك خالد بأبها
• مواليد ١٣٨١ هـ في الملد من بلاد غامد
• تخرج في كلية الشريعة في أبها عام ١٤٠٢ هـ
• الماجستير في كلية أصول الدين، جامعة الإمام في الرياض سنة ١٤١٠ هـ في تخصص العقيدة والمذاهب المعاصرة
• الدكتوراه في التخصص نفسه سنة ١٤٢٠ هـ
(المؤلفات)
