INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('عبد العزيز بن عبد الله آل الشيخ', 'مؤلف', 'عبد العزيز آل الشيخ
سماحة الشيخ عبد العزيز بن عبد الله بن محمد بن عبد اللطيف بن عبد الرحمن بن حسن بن الشيخ محمد بن عبد الوهاب
هو من مواليد مكة المكرمة بتاريخ ٣ \ ١٢ \ ١٣٦٢ هـ .
توفي والده وهو صغير لم يتجاوز الثامنة من عمره في عام ١٣٧٠ هـ ، وحفظ القرآن صغيرا في عام ١٣٧٣ هـ على يد الشيخ محمد بن سنان ، وقرأ على سماحة الشيخ محمد بن إبراهيم آل الشيخ مفتي الديار السعودية كتاب التوحيد والأصول الثلاثة والأربعين النووية وذلك من عام ١٣٧٤ هـ حتى عام ١٣٨٠هـ ، كما قرأ على سماحة الشيخ عبد العزيز بن عبد الله بن باز رحمه الله مفتي عام المملكة ورئيس هيئة كبار العلماء الفرائض في عام ١٣٧٧ هـ وعام ١٣٨٠ هـ ، وقرأ على الشيخ عبد العزيز بن صالح المرشد رحمه الله الفرائض والنحو والتوحيد وذلك في عام ١٣٧٩ كل ، وفي عام ١٣٧٥ هـ
و ١٣٧٦ هـ قرأ على الشيخ عبد العزيز الشثري عمدة الأحكام وزاد المستقنع ، وفي عام ١٣٧٤ هـ التحق بمعهد إمام الدعوة العلمي بالرياض ، ثم تخرج منه والتحق بكلية الشريعة بالرياض في عام ١٣٨٠ هـ وحصل على شهادة الليسانس في العلوم الشرعية واللغة العربية منها وذلك في العام الجامعي ١٣٨٣ \ ١٣٨٤ هـ ، ثم عين مدرسا في معهد إمام الدعوة العلمي بالرياض من عام ١٣٨٤ هـ حتى ١٣٩٢ هـ ، وانتقل إلى كلية الشريعة بالرياض التابعة لجامعة الإمام محمد بن سعود الإسلامية حيث كان يعمل أستاذا مشاركا فيها ، وبالإضافة إلى التدريس بها يقوم بالإشراف والمناقشة لرسائل الماجستير والدكتوراه في كل من كلية الشريعة ، وأصول الدين ، والمعهد العالي للقضاء التابع لجامعة الإمام محمد بن سعود الإسلامية ، وكلية الشريعة التابعة لجامعة أم القرى بمكة المكرمة ، بالإضافة إلى التدريس بالمعهد العالي للقضاء بالرياض ، والعضوية والمشاركة بالمجالس العلمية بالجامعة ، وفي شهر شوال عام ١٤٠٧هـ عين عضوا في هيئة كبار العلماء ، وقد تولى سماحته الإمامة والخطابة في جامع الشيخ محمد بن إبراهيم بدخنة بالرياض بعد وفاة سماحة الشيخ محمد بن إبراهيم وذلك في عام ١٣٨٩ هـ ، وفي شهر رمضان عام ١٣٩٠ هـ عين خطيبا في الجامع الكبير بالرياض ، وفي عام ١٤٠٢هـ عين إماما وخطيبا بمسجد نمرة بعرفة ، وفي شهر رمضان عام ١٤١٢هـ عين إماما وخطيبا بجامع الإمام تركي بن عبد الله بالرياض . ولسماحته حضور مميز في المحافل العلمية ، إضافة إلى المشاركة في الندوات وإلقاء المحاضرات والدروس ، وكذلك المشاركة في البرامج الدينية في الإذاعة والتلفاز .
ولسماحة الشيخ أربعة أبناء هم : عبد الله ويحضر رسالة الدكتوراه في المعهد العالي للقضاء ، ومحمد ويدرس في المستوى السابع في كلية أصول الدين ، وعمر ويدرس في السنة الثانية الثانوية ، وعبد الرحمن ويدرس في السنة الثانية المتوسطة .
ومن الصفات التي اتصف بها سماحة الشيخ عبد العزيز النشأة الصالحة منذ الصغر والورع والتقوى والإخلاص والنصح لولاة الأمر ولعموم المسلمين ومحبة الناس والعطف عليهم وبخاصة طلاب العلم .
أما التدرج الوظيفي فقد كان على النحو التالي :
١ - مدس بمعهد إمام الدعوة العلمي في ١ \ ٧ \ ١٣٨٤ هـ .
٢ - أستاذ مساعد بكلية الشريعة في ٧ \ ٥ \ ١٣٩٩ هـ .
٣ - أستاذ مشارك بكلية الشريعة في ١٣ \ ١١ \ ١٤٠٠هـ .
٤ - انتقل من الجامعة بتاريخ ١٥ \ ٧ \ ١٤١٢هـ لتعيينه عضوا للإفتاء في رئاسة البحوث العلمية والإفتاء بالقرار رقم
١ \ ٧٦ وتاريخ ١٥ \ ٧ \ ١٤١٢هـ .
٥ - صدر الأمر الملكي رقم ٨٣٨ وتاريخ ٢٥ \ ٨ \ ١٤١٦ هـ بتعيينه نائبا للمفتي العام .
وبعد وفاة سماحة الشيخ عبد العزيز بن عبد الله بن باز رحمه الله صدر أمر ملكي برقم أ \ ٢٠ وتاريخ ٢٩ \ ١ \ ١٤٢٠ هـ بتعيينه مفتيا عاما للمملكة العربية السعودية ورئيسا لهيئة كبار العلماء والبحوث العلمية والإفتاء .
وعن تعاونه المستمر مع جامعة الإمام محمد بن سعود الإسلامية فقد استمرت علاقته العلمية مع الجامعة بعد أن انتقل منها ، وذلك من خلال التدريس في المعهد العالي للقضاء ، والإشراف على رسائل الماجستير والدكتوراه في المعهد العالي للقضاء وكلية الشريعة وكلية أصول الدين ، والاشتراك في مناقشة رسائل الماجستير والدكتوراه ، وكانت آخر رسالة دكتوراه ناقشها في كلية أصول الدين يوم الأربعاء ٢٦ \ ١ \ ١٤٢٠ هـ .
نقلا عن : مجلة البحوث الإسلامية', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('عبد الله المصلح', 'مؤلف', 'الدكتور / عبد الله بن عبد العزيز المصلح
- نشأ وتربى في مدينة الرياض .
- التحق بمعهد الدعوة بالرياض ومنه نال الشهادة الثانوية .
- التحق بكلية الشريعة بالرياض وتخرج فيها عام ٩٠/٩١ هـ .
- عين معيداً بكلية الشريعة عام ١٣٩١هـ .
- أكمل الدراسات العليا بجامعة الإمام محمد بن سعود الإسلامية ونال منها شهادة الماجستير والدكتوراه .
- عمل عميداً لكلية الشريعة واللغة العربية في أبها عام ١٣٩٦هـ .
- ثم لما قسمت الكلية إلى كليتين إحداهما كلية الشريعة وأصول الدين والثانية كلية اللغة العربية والعلوم الاجتماعية كان عميداً للأولى ومشرفاً على الثانية .
- قام بافتتاح كلية الشريعة والدراسات الإسلامية بالإحساء .
- عمل مديراً لفرع جامعة الإمام محمد بن سعود الإسلامية بالجنوب .
-استمر في عمادة كلية الشريعة وأصول الدين ومديراً لفرع الجامعة في الجنوب في الفترة من ١٣٩٦ وحتى ١٤١٥هـ .
ألف مجموعة من الكتب .. منها:
١- الملكية الخاصة في الشريعة الإسلامية ومقارنتها بالاتجاهات المعاصرة .
٢- قيود الملكية الخاصة في الشريعة الإسلامية .
٣- القواعد العامة في فقه الجنايات .
٤- الشبهات التي تدرأ العقوبات في الفقه الإسلامي .
٥- منهج الإسلام في صيانة المجتمعات .
٦- حقوق غير المسلمين في المجتمع الإسلامي .
٧- الإمام الطبري منهجه في التفسير .
٨- مزايا المصارف الإسلامية .
٩- دليل مناسك الحج والعمرة .
١٠- ما لا يسع المسلم جهله ( مؤلف مشترك )
١١- المرابحة من التراث الفقهي إلى التطبيقات المعاصرة في المصارف الإسلامية.
١٢- الوجيز في أحكام الإجازة والشركة .
١٣- الإعجاز العلمي في القرآن والسنة تاريخه وضوابطه .
١٤- تجديد الدراسات الفقهية ودور المملكة العربية السعودية في هذا المجال .
المؤتمرات:
شارك في عدد كثير من المؤتمرات داخل المملكة وخارجها ممثلاً للمملكة أو مبعوثاً منها .
بعض الأعمال التي قام بها فضيلته:
١- أمين عام هيئة الإعجاز العلمي في القرآن والسنة.
٣- رئيس لجنة المعلمين بالهيئة .
٣- رئيس تحرير مجلة الإعجاز .
٤- وفي مجال الإعلام ( برنامج قضايا وردود) الذي قدمه أسبوعياً لمدة أكثر من ثمانية عشر عاماً بالقناة الأولى بالتلفزيون السعودي .
الأعمال التي يقوم بها حالياً:
١- عضو اللجنة الشرعية بالبنك الأهلي التجاري بالمملكة العربية السعودية .
٢- المشرف الإقليمي لمكاتب هيئة الإغاثة الإسلامية العالمية في المنطقة الجنوبية.
٣- عضو المجلس التأسيسي والتنفيذي لهيئة الاغاثة الاسلامية العالمية.
٤- عضو مجلس أمناء جامعة شيتاغونغ الإسلامية ببنجلاديش .
٥- رئيس المجلس التأسيسي للجامعة الأمريكية المفتوحة بنيويورك .
٦- مستشار لكلية الدراسات الإسلامية بدبي .
٧- يقدم برنامج أسبوعي بقناة اقرأ الفضائية بعنوان ( مشكلات من الحياة ).
٨- عضو المجلس التأسيسي للعديد من الهيئات الخيرية بدول الخليج العربي .
٩- مالك ومدير مكاتب الدكتور/ عبد الله المصلح للمحاماة والاستشارات الشرعية والقانونية.
١٠- يقدم العديد من البرامج بتلفزيون أبو ظبي بدول الإمارات العربية المتحدة وبعض القنوات الخليجية .', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
