INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('محمد أجمل الإصلاحي', 'مؤلف', 'العلامة اللغوي الدكتور محمد أجمل الإصلاحي
