INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('أحمد عمر هاشم', 'مؤلف', 'أحمد بن عمر بن إبراهيم بن إسماعيل بن محمد بن هاشم
أستاذ الحديث وعلومه بجامعة الأزهر، وعضو مجمع البحوث الإسلامية.
ولد أحمد عمر هاشم قي ٦/٢/١٩٤١م.
تخرج قي كلية أصول الدين جامعة الأزهر الشريف عام ١٩٦١.
حصل على الإجازة العالمية عام ١٩٦٧م،
ثم عُين معيداً بقسم الحديث بكلية أصول الدين،
حصل على درجة الماجستير قي الحديث وعلومه عام ١٩٦٩م،
ثم حصل على درجة الدكتوراه قي نفس تخصصه،
وأصبح أستاذ الحديث وعلومه عام ١٩٨٣م،
ثم عُين عميداً لكلية أصول الدين بالزقازيق عام ١٩٨٧م،
وفي عام ١٩٩٥م شغل منصب رئيس جامعة الأزهر.
الوظائف التي تولاها
* عضو مجلس الشعب معين بقرار من رئيس الجمهورية.
* عضو قي المكتب السياسى للحزب الوطني الديمقراطى.
* عضو مجلس الشورى بالتعيين.
* عضو مجلس أمناء اتحاد الإذاعة والتليفزيون.
* رئيس لجنة البرامج الدينية بالتليفزيون المصرى.
من مؤلفاته
* الإسلام وبناء الشخصية.
* من هدى السنة النبوية.
* الشفاعة في ضوء الكتاب والسنة والرد على منكريها.
* التضامن في مواجهة التحديات.
* الإسلام والشباب.
* قصص السنة.
* القرآن وليلة القدر.', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


