INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('عيد فهمي', 'مؤلف', 'سيرة ذاتية للمؤلف
الاسم: عيد فهمي محمد علي
تاريخ الميلاد: ١٠/١٢/١٣٩٢هـ الموافق ١٤/١/١٩٧٣م
محل الميلاد: المطرية - القاهرة - مصر
الدرجة العلمية: حاصل على ليسانس الآداب في اللغة العربية وآدابها واللغات الشرقية وآدابها - كلية الآداب - جامعة الإسكندرية.
تمهيدي ماجستير- كلية دار العلوم - جامعة القاهرة.
الخبرات السابقة:
عمل باحثًا شرعيًّا في العديد من دور وشركات التحقيق بمصر؛ مثل: دار ابن لقمان، دار التأصيل، شركة حرف لتقنية المعلومات، دار المحدثين، دار التابعين، ويعمل الآن مديرًا لشبكة السنة النبوية بمجموعة سهم للبرمجيات.
وشارك في العديد من الموسوعات العلمية أثناء عمله في مجال التحقيق، وله أعمال خاصَّة أخرى دعوية وعلمية وأدبية.
الإجازات العلمية:
كان له ملازمة خاصة للشيخ محمد بن أحمد بن إسماعيل المقدّم حفظه الله أثناء إقامته بالإسكندرية للدراسة وكان الشيخ يوليه اهتماما خاصًّا لما رأى عليه من علامات النبوغ، وقد حصَّل المؤلف العديد من الإجازات العلمية من جمعٍ من العلماء والدعاة، وكان أعلاها تلك التي أخذها من سماحة الشيخ عبد الله بن عقيل الظاهري حفظه الله رئيس المجلس الأعلى للقضاء السعودي سابقا، وحصَّل الإجازة أيضًا من كل من الأستاذ الدكتور/ رفعت فوزي، والأستاذ الدكتور/ أحمد معبد عبد الكريم، وفضيلة الشيخ/ محمد عمرو بن عبد اللطيف، حفظهم الله جميعًا، وكان أول من أجازه فضيلة الشيخ/ وليد بن إدريس المنيسي حفظه الله وكان حينئذٍ في مقتبل العمر قد قارب على العشرين ومع ذلك فقد وصفه الشيخ في الإجازة بقوله: الشيخ العلامة المتفنن، قال المؤلف: «هذا ولي إجازات أخرى عن شيوخ ليسوا على عقيدة السلف من الصوفية والشيعة والأشاعرة، ولذلك لم أذكرها، ولي سلف في ذلك فإن الشيخ تقي الدين الهلالي حصل على إجازات كثيرة إلا أنه كان لا يجيز إلا عن شيخين اثنين سلفيين، وأخبر أنه نبذ الرواية عن شيوخه من أهل البدع. والشيخان اللذان يروي عنهما هما الشيخ العالم المحقق أبو العلا عبد الرحمن المباركفوري صاحب تحفة الأحوذي والشيخ العالم المتفنن المحقق محمد بن حسين بن محسن الحديدي اليمني»', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


