INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('محمد بن خليفة التميمي', 'مؤلف', 'الأستاذ الدكتور محمد بن خليفة بن علي التميمي عميد البحث العلمي بالجامعة الإسلامية بالمدينة المنورة
(المؤهلات العلمية)
• البكالوريوس: ١٤٠١ هـ
• الماجستير: ١٤٠٦ هـ
• الدكتوراه: ١٤١٠ هـ
(الوظائف التعليمية)
• أستاذ مساعد: ٦/ ١٢ /١٤١٠ هـ
• أستاذ مشارك: ٣/ ٥/ ١٤١٧ هـ
• أستاذ: ٢٩/ ٨/ ١٤٢١ هـ
• عضو لجنة القبول بعمادة القبول والتسجيل بالجامعة الإسلامية بالمدينة المنورة.
• رئيس لجنة أوروبا والأمريكتين بعمادة القبول والتسجيل بالجامعة الإسلامية بالمدينة المنورة.
• وكيل مركز البحث العلمي بالجامعة الإسلامية بالمدينة المنورة.
• مدير مركز البحث العلمي (المكلف) بالجامعة الإسلامية بالمدينة المنورة.
• عضو هيئة التدريس بالجامعة الإسلامية بالمدينة المنورة.
• عميد البحث العلمي بالجامعة الإسلامية بالمدينة المنورة.
• رئيس هيئة تحرير مجلة الجامعة الإسلامية بالجامعة الإسلامية بالمدينة المنورة.
• عضو مجلس الدراسات العليا بالجامعة الإسلامية بالمدينة المنورة.
• عضو المجلس العلمي بالجامعة الإسلامية بالمدينة المنورة.
• عضو لجنة البحث العلمي بجائزة المدينة المنورة - جائزة المدينة المنورة.
• عضو اللجنة العلمية لموسوعة الإمام محمد بن عبد الوهاب وتلاميذه بوزارة الشؤون الإسلامية.
• المشرف العام على مشروع مكتبة المدينة الرقمية بالمدينة المنورة.
• التدريس بالمسجد النبوي الشريف في موسم الحج المسجد النبوي بالمدينة المنورة.
بالإضافة إلى رئاسة العديد من الدورات التدريبية والندوات، والمشاركة في العديد من المؤتمرات والندوات وورش العمل والمحاضرات الداخلية والخارجية.', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('أحمد بن عبد الله الزهراني', 'مؤلف', 'الشيخ الدكتور أحمد بن عبد الله العماري الزهراني
- من مواليد قرية النصباء بزهران سنة ١٣٧٠ هـ .
- درس المرحلة الإبتدائية بمدرسة النصباء الإبتدائية وتخرج فيها سنة ١٣٨٤هـ.
- درس المرحلة المتوسطة والثانوية بالمعهد العلمي بمكة المكرمة وتخرج فيه سنة ١٣٨٩هـ.
- حصل على البكالوريوس في الشريعة من كلية الشريعة بالرياض سنة ١٣٩٤هـ .
- حصل على الماجستير من قسم الكتاب والسنة في جامعة أم القرى عن أطروحته في تحقيق كتاب ( إعلام العالم بعد رسوخه بحقائق ناسخ الحديث و منسوخه ).
- حصل على الدكتوراه عن أطروحته في تحقيق الجزء الأول من كتاب (تفسير القرآن العظيم مسنداً عن النبي صلى الله عليه وسلم ) لابن أبي حاتم .
حياته العملية :
- عُيِّن معيداً في الجامعة الإسلامية سنة ١٣٩٥ هـ .
- عُيِّن محاضراً بكلية الدعوة في الجامعة الإسلامية .
- عُيِّن أستاذاً مساعداً بكلية القرآن الكريم بالجامعة الإسلامية .
- عُيِّن وكيلاً لكلية القرآن الكريم بالجامعة الإسلامية .
- عمل عميداً لكلية القرآن الكريم لمدة ثلاث سنوات بالجامعة نفسها.
- عُيِّن رئيساً لمجلس شئون الدعوة بالجامعة الإسلامية .
- عُيِّن عضواً في المجلس العلمي للجامعة الإسلامية .
- عُيِّن عضواً في هيئة تحرير مجلة الجامعة الإسلامية .
انتاجه العلمي :
- تحقيق الجزء الأول من تفسير بن أبي حاتم ( رسالة الماجستير ).
- تحقيق كتاب إعلام العالم بعد رسوخه بحقائق ناسخ الحديث ومنسوخه ( رسالة الدكتوراه ).
- رسالة في التفسير الموضوعي .
- شارك في عضوية العديد من اللجان العلمية والمجالس و الجمعيات .
- شارك في الإشراف و المناقشة لكثير من الرسائل العلمية لمرحلتي الماجستير والدكتوراه .
- شارك في الكثير من الندوات واللقاءات والدورات العلمية والدعوية داخل المملكة وخارجها', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


