INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('حمد الحمد', 'مؤلف', 'حمد بن عبد الله بن عبد العزيز الحمد، الداعية في مركز الدعوة والإرشاد بحائل - وزارة الشئون الإسلامية والأوقاف السعودية
• ولد في حائل في اليوم العشرين من شهر رمضان المبارك عام (١٣٨٧ هـ).
• تدرج في التعليم النظامي حتى حصل على الشهادة الثانوية من ثانوية حائل عام (١٤٠٥ هـ)
• أكمل دراسته الجامعية في كلية أصول الدين بجامعة الإمام محمد بن سعود الإسلامية في الرياض، ثم انتقل إلى فرعها في القصيم
• انقطع عن الدراسة فترة من الزمن تفرغاً للعلم والدعوة ثم أكمل دراسته انتساباً حتى حصل على البكالوريوس في أصول الدين من كلية الشريعة وأصول الدين في جامعة الإمام محمد بن سعود الإسلامية - فرع القصيم - لعام (١٤١٦ - ١٤١٧ هـ).
(من العلماء الذين أخذ عنهم)
• الشيخ عبد العزيز بن باز رحمه الله.
• الشيخ محمد بن عثيمين رحمه الله.
• الشيخ سليمان السكيت رحمه الله.
• الشيخ صالح الفوزان حفظه الله.
• الشيخ عبد الله الجبرين رحمه الله.
• الشيخ عبد الله بن عقيل حفظه الله.
• الشيخ عبد الرحمن البراك حفظه الله.
(المؤلفات)
• شرح كشف الشبهات لشيخ الإسلام محمد بن عبدالوهاب رحمه الله (مطبوع)
• «ما لا يسع المسلم جهله في أصول الاعتقاد» (لم يطبع بعد)
(الدروس)
شروح كثيرة (أغلبها مفرغة ومكتوبة) لم تطبع إلى الآن وبعضها في مرحلة الإعداد للطبع.
• فشرح متون العقيدة المهمة: كثلاثة الأصول والقواعد الأربع ونواقض الإسلام وكشف الشبهات وكتاب التوحيد ولمعة الاعتقاد والعقيدة الواسطية ومسائل الجاهلية والعقيدة الطحاوية والسفارينية وغيرها.
• وشرح أصول التفسير لابن قاسم رحمه الله.
• تفسير القرآن الكريم من البقرة إلى أوائل سورة الأنعام وهو مكتوب.
• وفي الحديث: شرح بلوغ المرام أكثر من مرة.
• وفي الفقه: شرح زاد المستقنع أكثر من مرة وشرح جزءاً من أخصر المختصرات وجزءاً من متن دليل الطالب وشرح منهج السالكين , كما شرح متن الرحبية في الفرائض.
• وفي اللغة: شرح الآجرومية وألفية ابن مالك كاملةً وجزءاً من لامية الأفعال لابن مالك رحمه الله.
• وله شرح مختصر في البلاغة بأنواعها الثلاث وفي العروض والقافية وفي الإملاء.
• وفي مصطلح الحديث: شرح البيقونية وشرح نزهة النظر أكثر من مرة وشرح الموقظة للذهبي رحمه الله.
• وفي أصول الفقه: له دروس إلقائية في شرح أصول الفقه ألقاها على طلابه من غير ارتباط بمتن معين.
وله مختصر في أصول الفقه ألقاه على الطلاب المبتدئين , وله شرح لمختصر روضة الناظر المسمى «البلبل» للطوفي رحمه الله , وله متن في أصول الفقه حرره بعناية وله شرح عليه , وله تعليقات على الأصول من علم الأصول للشيخ ابن عثيمين رحمه الله , وله شرح قواعد الأصول ومعاقد الفصول للبغدادي الحنبلي رحمه الله.
• وفي القواعد الفقهية: شرح منظومة القواعد الفقهية للشيخ السعدي رحمه الله , وشرح أيضاً جزءاً من قواعد الفقه الإسلامي لابن رجب الحنبلي رحمه الله , وله شرح على اختيارات شيخ الإسلام ابن تيمية لبرهان الدين إبراهيم بن محمد بن قيم الجوزية رحمهما الله.
وكثير من هذه المتون قد كرر الشيخ شرحها أكثر من مرة.
• وقد أقام وشارك في دورات علمية داخل السعودية كالرياض والمدينة النبوية وخارجها كالإمارات وقطر والكويت والبحرين. وله محاضرات متعددة (وعظية وفقهية) داخل السعودية وخارجها', 'المذهب الحنبلي', NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('هيثم بن فهد الرومي', 'مؤلف', 'هيثم بن فهد بن عبد الرحمن الرومي
• أستاذ الفقه المساعد، بقسم الثقافة الإسلامية، كلية التربية، جامعة الملك سعود، الرياض، المملكة العربية السعودية.
• ماجستير الفقه المقارن من المعهد العالي للقضاء، بجامعة الإمام محمد بن سعود الإسلامية، عام ١٤٢١ هـ، وعنوان الرسالة: (الأحكام الفقهية المتعلقة بالشِّعر في الفقه الإسلامي).
• دكتوراة الفقه وأصوله من شعبة الفقه وأصوله، بقسم الثقافة الإسلامية في كلية التربية بجامعة الملك سعود بالرياض، عام ١٤٣٢ هـ، وعنوان الرسالة: (الصياغة الفقهية في العصر الحديث).
• من إسهاماته البحثية:
١ - الصياغة الفقهية في العصر الحديث، دراسة تأصيلية.
٢ - إصلاح الفقيه، فصول في الإصلاح الفقهي.', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
