INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('سعدي بن مهدي الهاشمي', 'مؤلف', 'سعدي بن مهدي بن صالح الهاشمي
أستاذ بقسم الكتاب والسنة بكلية الدعوة وأصول الدين بجامعة أم القرى (حاليا)، وبكلية الحديث بالجامعة الإسلامية بالمدينة النبوية (سابقاً)
