INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('عبد الحي يوسف', 'مؤلف', 'الدكتور عبد الحي يوسف
رئيس قسم الثقافة الإسلامية بجامعة الخرطوم
أبو عمر عبد الحي بن يوسف، من مواليد القاهرة عام ١٣٨٤هـ الموافق ١٩٦٤م.
تخرج في الجامعة الإسلامية بالمدينة المنورة في كلية الشريعة عام ١٤٠٦ ـ ١٤٠٧هـ،.
أتم الدراسات العليا في جامعة الخرطوم عام ١٤١٨هـ ـ ١٩٩٨م.
يعمل الآن رئيساً لقسم الثقافة الإسلامية بجامعة الخرطوم.
كما أنه إمام وخطيب مسجد حي الدوحة بالخرطوم.
اشتهر فضيلته بالجرأة والصدع بالحق، وله جهود مشكورة في الدعوة والتربية.
الشيخ عبد الحي يوسف من أهل العلم في السودان هو الآن أستاذ مشارك بقسم الثقافة الإسلامية في جامعة الخرطوم، وله مشاريع دعوية كبيرة يشرف عليها، وقد نفع الله به أمماً.
له موهبة مميزة في الخطابة والحديث ساعده عليها مِلك حافظة جيدة، واستقامة لسان فقل أن يلحن هذا الشيخ في حرف أثناء ارتجاله الكلام، ولغته فصيحة عالية في الجملة.
وقد حباه الله تواضعاً جماً وأدباً عظيماً ولا سيما مع أهل العلم وبالأخص من يكبره سناً وقد جمع هذا حوله نفراً من الطيبين.
فتح الله عليه في الدعوة وكتب له قبولاً عند قطاع عريض من أهل السودان على اختلاف مشاربهم المذهبية وتياراتهم الإسلامية .. ولعل من أسباب ذلك حكمته في التعامل مع الناس وحسن مداراته لهم فقل أن يكاشح إسلامياً -وإن كان منحرفاً عنده- بالعداء، اللهم إلاّ الرافضة الإثني عشرية ومن كان نحوهم، فله معهم مواقف مشكورة، وله في كل ذلك نظرة أخالها مقدرة ولا سيما لمن يعيش واقعه وبيئته.
وهو في المقابل شديد على الصلبيين وأذنابهم ومنهم العلمانيين والتغريبيين وكذا الشيوعيين ومن لف لف هؤلاء في مكاشحة الدين والكيد له.
والشيخ مستقيم في الجملة على السنة، محب لها، ناصر لها، وتبقى له كغيره اجتهادات وآراء لا يوافقه عليها غيره، ونحسبه -والله حسيبه- مخلصاً مريداً للحق، وقد نفع الله به خلقاً عظيماً.', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


