INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('أزهري أحمد محمود', 'مؤلف', 'أزهري أحمد محمود
سوداني، له أكثر من مائة كتيب دعوي، مثل:
