INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('مختار بن العربي الجزائري', 'مؤلف', 'أبو سليمان مختار بن العربي بن أحمد بن اعمر بن عامر، واللقب: مومن
• ولد ببادية عين السخونة (فيض الرَّمَل) ولاية سعيدة والمسماة جغرافيا بالشط الشرقي، بالجزائر سنة ١٣٨٤ هـ - ١٩٦٤ م
• طلب العلم في الجزائر، رحل إلى أدرار وتلمسان ومستغانم، ثم التحق بمدرسة الأمير عبد القادر بمدينة سعيدة في ١٩٨٦ م
• ثم رحل إلى موريتانيا (شنقيط) فالتحق بمعهد العلوم الإسلامية والعربية التابع لجامعة الإمام محمد بن سعود الإسلامية، وكانت الدراسة في المعهد ثلاث سنوات، وتخرج بدرجة ممتاز وبترتيب الأول في السنوات الثلاث
أما عن الدراسة النظامية، فقد عزفت نفسه عنها بعد نيل الثانوية العامة، ورُشح للدراسة في الجامعة الإسلامية، لكنه اعتذر بسبب كبر سنه (كان إذ ذاك ٢٩ سنة).
ثم لزم الشيخ محمد بن محفوظ بن المختار فال الشنقيطي، ودرس على عدد من مشايخ شنقيط.
• في ١٩٩٦ م، ارتحل إلى قطر، ويعمل هناك بإدارة الدعوة والإشاد، باحثا وخطيبا.
(المؤهلات)
• الباكالوريا: معهد العلوم العربية والإسلامية موريتانيا
• الليسانس: في أصول الدين بمرتبة الشرف الثانية من جامعة أم درمان الإسلامية، الخرطوم - السودان
• الماجستير: جامعة محمد الأمين الشنقيطي موريتانيا.
(من مؤلفاته)
• المناهل الزلالة في شرح وأدلة مسائل الرسالة لابن أبي زيد القيراوني (٤ مجلدات)
• مسالك الجلالة في اختصار المناهل الزلالة في شرح الرسالة (٣ مجلدات)
• العرف الناشر في شرح وأدلة فقه متن ابن عاشر
• المسك الأذفري في شرح وأدلة متن الأخضري
• التحفة السخونية في شرح مصطلح البيقونية
• الجهل وأثره في الأحكام
• الإمام في فضل الإمامة وأحكام الإمام
• تحقيق نظم الرسالة للغلاوي', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


