INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('سامى عامرى', 'مؤلف', 'أستاذ العقيدة والفرق والأديان في إحدى الجامعات الإسلاميّة عن بعد، وهو متخصص في دراسات العهد الجديد والاستشراق التنصيري. درس في كليّة الحقوق قبل أن يلتحق بدراسة الشريعة.
اللغات:
اللغات الحديثة: العربيّة والإنجليزيّة والفرنسيّة.
اللغات القديمة: يدرس اللغات الساميّة عامة, واللغتين العبريّة والسريانيّة خاصة, بالإضافة إلى يونانيّة العهد الجديد.
الاهتمامات/
* الردّ العلمي على شبهات المنصّرين في ضوء آخر الدراسات والأبحاث المتخصصة.
* الردّ العلمي على أهمّ الشبهات التي يثيرها الاستشراق التنصيري.
* الردّ العلمي على شبهات التغريبيين المتقاطعة مع دعاوى المستشرقين والمنصّرين.
* تحليل الكتب المقدّسة لليهود والنصارى ونقدها في لغاتها الأصليّة وأهم ترجماتها القديمة.
* الاهتمام بقضيّة تحريف الأسفار المقدّسة للنصارى في ضوء منهج النقد النصّي (Textual Criticism) في إطار التصوّر الإسلامي لهذه الأسفار وتاريخها وعقائدها.
* فتح أبواب جديدة في الإعجاز القرآني, وهي التي يسمّيها بـ(إعجاز القرآن في نقد العقائد والأديان)
* التعامل مع كلّ فنّ كتابي بمنهجه الخاص وآلياته الدقيقة ومراجعه الخاصة, بعيدًا عن الإجمال المخلّ والإنشائيات العقيمة.
* الاستفادة من الدراسات الأركيولوجيّة الحديثة والتأكيد على أهميّتها في نطاق الدراسات الكتابيّة.
* الاستفادة من الأبحاث الفيلولوجيّة الحديثة في ميدانها الذي يليق بها.
* الخروج من منهج (التكرار) الذي ساد المكتبة العربية لفترة طويلة.
* الاستفادة المعمّقة من المكتبتين الانجليزية والفرنسية, من خلال القراءة الفاحصة لمؤلفات أعلام الأكاديميين من كتب ومقالات متخصصة, ومتابعة آخر الإصدارات العلميّة.
* تأكيد الصوت الإسلامي في السجالات العلميّة في الغرب.
* تأصيل منهج عصري أصيل للدراسات الدينية للنصرانيّة.
* الجمع بين الحجّة العلميّة الصلبة والأسلوب الأدبي السلس.', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


