INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('محمد صباح منصور', 'مؤلف', 'من كتبه
- المنظومة الحاوية للعقيدة الطحاوية (دار البشائر الإسلامية).
- ليلة القدر: معرفتها- فضلها- خصائصها- علاماتها- تعيينها- أحكامها- ما يتأكد فعله فيها (دار البشائر الإسلامية).
- الدرر اللطيفة بتحقيق ما ورد في الروضة الشريفة (دار البشائر الإسلامية).
- الإعلام بنقد كتاب الروض البسام (غراس للنشر والتوزيع)
وله تحقيقات، منها:
- مجموع فيه فتاوى ورسائل العلامة محمد بن إسماعيل الأمير الصنعاني (دار البشائر الإسلامية).
- عروس الأجزاء، تصنيف سيد الرؤساء مسعود بن الحسن الثقفي (دار البشائر الإسلامية).
- مجموع فيه: جواب بعض الخدم لأهل النعم عن تصحيف حديث احتجم، ويليه: العشرة من مرويات صالح بن الإمام أحمد وزياداتها، كلاهما ليوسف بن عبد الهادي، ويليه جزء في إسلام زيد بن حارثة وغيره من أحاديث الشيوخ، للإمام تمام الرازي، (دار البشائر الإسلامية).', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
