INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('أحمد ياسوف', 'مؤلف', 'معيد بكلية الآداب بجامعة حلب
من كتبه (ط دار المكتبي - سوريا)
١ - الصورة الفنية في الحديث النبوي الشريف: دراسة معمقة في الصورة الفنية في الحديث النبوي الشريف يتناول فيها مقدمات نظرية والوسائل البلاغية للصورة والوسائل الجمالية الأخرى لها ومظاهر الصورة ومكونات اللوحة الفنية مع فهارس فنية مفيدة.
٢ - جماليات المفردة القرآنية: يتناول الجوانب الجمالية للمفردة القرآنية عامة، وإسهامها في الجمال البصري والسمعي، ويبحث ظلال المفردة القرآنية على المعنى، مع دراسات فنية جمعت بين القديم والحديث إضافة إلى فنون البلاغة واللغة والإعراب في دراسة مبتكرة تفيد من دراسات القدامى ونظريات المحدثين معاً، ويخرج بنتائج مهمة في مكانة المفردة في إعجاز القرآن.
٣ - جماليات المفردة القرآنية في كتب الإعجاز والتفسير: يتناول دراسة الجوانب الجمالية للمفردة القرآنية عامة، وإسهامها في الجمال بصري والسمعي، ويبحث في الظلال التي تضفيها المفردة على المعنى، إلى دراسات فنية جمعت بين القديم والحديث، وفنون البلاغة واللغة والإعراب من خلال مفهوم الجميل عند العلماء المسلمين ودلائل المفردات التهذيبية وسعة الاختزان فيها ومناسبتها للمقام، والفاصلة القرآنية.', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
