INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('محمد بن عبد العزيز القرعاوي', 'مؤلف', 'هو محمد بن عبد العزيز السليمان القرعاوي من قبيلة عنزه، ولد في عنيزة في منطقة القصيم في المملكة العربية السعودية سنة (١٣٥٣) هـ في ٢٤ رمضان، وقد شب في مدينة عنيزة، والتحق في إحدى الكتاتيب، ودرس القرآن الكريم وبعض علوم الشريعة واللغة العربية، ثم التحق بالمعهد العلمي بعنيزة عام ١٣٧٧ هـ، وتخرج منه عام ١٣٨١ هـ، والتحق بكلية الشريعة بالرياض، ثم تخرج منها عام ١٣٨٥ هـ ١٣٨٦ هـ. وقد انتظم في سلك القضاء منذ تخرجه حتى قضى سنتين في القضاء، فانتقل بعد ذلك إلى التدريس في وزارة المعارف، ولا يزال حتى الآن مدرسا بمعهد النور بعنيزة.
أما حالته الاجتماعية فقد نشأ يتيما عصاميا بنى مستقبله بنفسه، ولا يزال يعمل في حقل الدعوة الإسلامية إضافة إلى عمله الرسمي في معهد النور.', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


