INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('مصطفي عبد اللطيف درويش', 'مؤلف', 'محامي، حاصل على ماجستير في الشريعة والقانون
تخصص في التوحيد ومقارنة الأديان
أتم الدراسات القانونية بكلية الحقوق، وأتم بعد ذلك دراسة الشريعة الإسلامية بالدراسات العليا قسم الدكتوراة بكلية الحقوق، وقد أتاح له ذلك فرصة الدراسة المقارنة.
له مؤلفات إسلامية كثيرة أعيد طبعها وترجمت ، وتهدف هذه المؤلفات إلى تنقية الإسلام مما أدخل عليه في العقائد والعبادات والمناسك والشرائع ، حيث يرى أن قيام مثل هذا المجتمع المسلم هو الصورة المشجعة للآخرين على الدخول فيه كما حدث في المجتمع الإسلامي الأول
اما في مجال الأديان الأخرى فله مؤلفات منها :«محمد الرسول في التوراة والإنجيل»و«القرآن والنصرانية»، وقد اعتنق الكثيرون الإسلام بعد قراءة هذه الكتب. أما كتاب«نداء إلى الفاتيكان»، فهو يرى أن أهل الأديان الأخرى الأوربيين في حاجة إلى اكتشاف الإسلام والتعرف عليه', NULL, NULL, NULL, NOW(), NOW())
