INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('أمين الشقاوي', 'مؤلف', 'أمين بن عبد الله الشقاوي، من مواليد ١٣٨٤ هـ، عضو دعوة بوزارة الشئون الإسلامية.
• حاصل على درجة البكالوريوس من جامعة الإمام محمد بن سعود الإسلامية - كلية أصول الدين - قسم السنة وعلومها عام ١٤١٥ هـ.
• حاصل على درجة الماجستير ١٤١٩ هـ من جامعة الملك سعود بالرياض - كلية التربية - قسم الدراسات - شعبة التفسير والحديث.
• حاصل على درجة الدكتوراه من دولة لبنان - في الدراسات الإسلامية - شعبة التفسير عام ١٤٢٦ هـ.
• المؤلفات العلمية:
١ - غزوة بدر من القرآن الكريم والحديث الشريف دروس وعبر وفوائد وأحكام، وهي رسالة الدكتوراه (مطبوع).
٢ - تعارض أحكام الإمام محمد بن حبان البستي على بعض الرواة في كتابيه الثقات والمجروحين، وهي رسالة الماجستير (مطبوع).
٣ - الدُّرَر المنتقاة من الكلمات المُلقاة - دروس يومية - مطبوع (١ - ٣، ٤ - ٥، ٦ - ٧، ٨، ٩، ١٠، ١١، ١٢).', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('علي بن عبد العزيز الشبل', 'مؤلف', '- بكالوريوس من جامعة الإمام محمد بن سعود الإسلامية، قسم العقيدة، كلية أصول الدين، عام ١٤١١ هـ.
- ماجستير من الجامعة نفسها عام ١٤١٨ هـ.
- دكتوراه من الجامعة نفسها عام ١٤٢٢ هـ.
- أستاذً بكلية أصول الدين، قسم العقيدة، بجامعة الإمام محمد بن سعود بالرياض.
هو ابن الشيخ عبد العزيز الشبل رحمه الله العالم الكبير المدرس بالمسجد النبوي الشريف، وبالجامعة الإسلامية بالمدينة النبوية.
وأخوه: د. عبد الرحمن بن عبد العزيز الشبل (ت ١٤٢٥ هـ) عضو هيئة التدريس بالجامعة الإسلامية بالمدينة النبوية، المعروف بتحقيق كتاب «ذم الكلام وأهله» لأبي إسماعيل الهروي.
من شيوخ المترجَم:
الإمام عبد العزيز بن باز رحمه الله.
والشيخ العلامة صالح الفوزان حفظه الله.
والشيخ العلامة عبد الرحمن البراك. حفظه الله.
والشيخ العلامة عبد الله الغنيمان. حفظه الله.', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


