INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('محمد سالم أبو عاصي', 'مؤلف', 'أولا- معلومات شخصية:
الاسم: محمد سالم أبو عاصي.
مواليد: مصر ١٩٦٢م.
ثانيا- المؤهلات العلمية:
إجازة من كلية أصول الدين - جامعة الأزهر - القاهرة ١٩٨٦م.
ماجستير من كلية أصول الدين- جامعة الأزهر ١٩٩٠م.
دكتوراه من كلية أصول الدين - جامعة الأزهر بمرتبة الشرف الأولى مع التوصية بطباعة الرسالة ١٩٩٣م.
ثالثاً- الخبرات والأعمال التي وليها:
مدرس مساعد بكلية أصول الدين جامعة الأزهر القاهرة ١٩٩٢م-١٩٩٤م.
أستاذ مدرس في كلية أصول الدين جامعة الأزهر القاهرة ١٩٩٤م-١٩٩٩م.
مدرس بكلية الشريعة والقانون بمسقط - سلطنة عمان -١٩٩٧م.
أستاذ مساعد - مشارك - بكلية أصول الدين بالقاهرة والشريعة والقانون بمسقط ١٩٩٩م.
رئيس قسم أصول الدين بكلية الشريعة والقانون بمسقط -١٩٩٩ - ٢٠٠٣م.
أستاذ بكلية أصول الدين - جامعة الأزهر بالقاهرة ٢٢/ ٨/٢٠٠٤م.
أستاذ بكلية الشريعة والدراسات الإسلامية - جامعة قطر.
أستاذ زائر بالجامعة الإسلامية العالمية بالهند ٢٠٠٢م.
عضو لجنة الندوات العلمية بكليتي أصول الدين - القاهرة - والشريعة والقانون بمسقط ١٩٩٩م-٢٠٠٣م.
عضو لجنة البحث العلمي بكلية الشريعة والقانون بمسقط ١٩٩٩م - ٢٠٠٣م.
عضو لجنة الشريعة - بمجمع اللغة العربية بالقاهرة بجمهورية مصر العربية.
عضو لجنة موسوعة الفرق الإسلامية بالمجلس الأعلى للشؤون الإسلامية،
عضو لجنة الندوات بقسم أصول الدين - كلية الشريعة والدراسات الإسلامية - جامعة قطر- ١١/ ٩/٢٠٠٦ حتى الآن.
له العديد من المؤلفات والأبحاث العلمية المحكمة منها:
تفسير آيات الشرط في القرآن الكريم
التعليل في القرآن والسنة
دعوى تاريخية النص القرآني: تحليل وتعقيب (حولية كلية أصول الدين بالقاهرة ١٩٩٩م).
دعوى القرآن إلى العقيدة (حولية كلية أصول الدين القاهرة - ٢٠٠١م).
شارك في عدد من الندوات والمؤتمرات العلمية بمصر وسلطنة عمان والإمارات العربية المتحدة ولبنان وغيرها.
له عدد من المقالات في بعض الصحف والمجلات العربية وبعض التسجيلات الإذاعية والتليفزيونية بمصر وسلطنة عمان.', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
