INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('نوال العيد', 'مؤلف', 'أ. د. نوال بنت عبد العزيز العيد، أستاذ دكتور في السنة بجامعة الأميرة نورة بنت عبدالرحمن، فائزة بجائزة الأمير نايف بن عبد العزيز للسنة وعلومها والدراسات الإسلامية المعاصرة بعنوان حقوق المرأة في السنة النبوية عام ١٤٢٧ هـ
• ولدت في مدينة شقراء بالمملكة العربية السعودية ١٣٩٧ هـ
(المؤهلات)
• البكالوريوس من كلية التربية للبنات بالرياض، الأقسام الأدبية في تخصص الدراسات الإسلامية في عام ١٤١٩ هـ / ١٤٢٠ هـ بتقدير ممتاز مع مرتبة الشرف، وكانت الأولى على الكلية
• الماجستير من الكلية نفسها في تخصص «الحديث النبوي وعلومه» بتقدير ممتاز مع مرتبة الشرف، وكان موضوع الرسالة: شرح صحيح البخاري لأبي الحسن علي بن خلف بن عبد الملك بن بطال القرطبي المالكي المتوفى سنة ٤٤٩ هـ من بداية كتاب فضائل المدينة إلى باب الدعاء للمشركين بالهدى من كتاب الجهاد «دراسة وتحقيق».
• الدكتوراه من الكلية نفسها بتقدير ممتاز مع مرتبة الشرف الأولى عام ١٤٢٤/ ١٤٢٥ هـ وكان موضوع الرسالة: الأحكام الكبرى لأبي الفداء إسماعيل ابن عمر بن كثير القرشي الدمشقي الشافعي المتوفى سنة ٧٧٤ هـ من بداية كتاب الأذان إلى باب ما يقال عند الإقامة في الصلاة «دراسة وتحقيق».
(العمل الأكاديمي)
• معيدة في كلية التربية بالرياض عام ١٤١٩ هـ، ثم محاضر في عام ١٤٢٤ هـ، ثم أستاذ مساعد عام ١٤٢٥ هـ.
• أستاذ مشارك في جامعة الأميرة بنت عبد الرحمن في عام ١٤٣٢ هـ ثم أستاذ دكتور فيها (كلية الآداب - قسم الدراسات الإسلامية في الحديث وعلومه) عام ١٤٣٥ هـ
(المؤلفات)
• موسوعة شرح أسماء الله الحسنى (مطبوع)
• ضوابط التكفير في ضوء السنة النبوية (مطبوع)
• كيف تنصر نبيك (مطبوع)
• حقوق المرأة في ضوء السنة النبوية (مطبوع)
• التيسير على النساء في الحج (مطبوع)
• موقف المؤمن من الفتن في ضوء حديث عبد الله بن عمرو (مطبوع)
• برنامج رمضاني مستوحى من الهدي النبوي
• ماذا بعد الحج والعمرة؟
• برنامج فعلي في التوبة إلى الله
• كيف تقوي إيمانك
(الأبحاث)
• أثر القيم النبوية في التعايش بين أتباع الأديان
• الدور الوسيط للتدين والأمل في تخفيف تأثير الوصمة الذاتية على الرفاهية النفسية لمرضى كوفيد ١٩
• إدارة الأزمات والكوارث في ضوء المنهج الإسلامي
• الذكاء الروحي والتدين لدى القادة
• تحديد الهدف مفاهيم وتطبيقات في ضوء السنة النبوية
• شبهات حول السنة النبوية والرد عليها
• شرح اسم الله الأول والآخر والظاهر والباطن
• واقع الشباب وتطلعاتهم المستقبلية
• شبهة حد الردة في السنة النبوية
• حقوق المحضون
• منهج النبي محمد - صلى الله عليه وسلم - في مكافحة الفساد', 'المذهب المالكي', NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
