INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('الشاهد البوشيخي', 'مؤلف', 'الشاهد بن محمد البوشيخي، ولد سنة ١٩٤٥م بالحريشة، قرية با محمد.
* أستاذ محاضر بكلية الآداب والعلوم الإنسانية بفاس
* مدير معهد الدراسات المصطلحية بفاس
* رئيس وحدة القرآن والحديث بالدراسات العليا بجامعة محمد بن عبد الله بفاس
مَعْلَمة حية نابضة بهموم العلم والثقافة ليس في الواقع المغربي فقط، وإنما في واقع الأمة الإسلامية. له عدة إسهامات في تحريك الحس الحضاري، وإيقاظ الشعور الجماعي للأمة من خلال ما يكتب وما يحاضر به في المحافل الثقافية والعلمية.
إن الذي يتدبر خطاب الرجل في كل ما يكتب وما يقول يشدُّه هذا التفكير والنظر الطويل في البحث عن أسباب وعلل الأزمات المحدقة بالأمة، واقتراح الحلول والعلاج لها، ويأسره هذا التعبير المتين والأسلوب الرصين الذي يختزل المعاني الكثيرة في الألفاظ القليلة وهو يقبس من القرآن الكريم ومن البلاغة العربية.
والأستاذ البوشيخي إلى جانب ذلك كله داعية إسلامي قدير يحمل همَّ الدعوة إلى الله، ويسعى إلى استرداد ذات الأمة المهربة، وحمل أبناء الإسلام على الرضاع من لبنه الخالص بتصور شامل يستوعب فقه الدين وفقه الواقع، ويتسلح بالعلم والعمل. إننا بحق أمام رجل وهبه الله ـ عز وجل ـ من الطاقات والملكات، ناهيك عن تواضعه الجم وخلقه الرفيع الذي يشهد له بالقدوة والحكمة.
أن تدخل إلى رحاب عقل العلاَّمة الدكتور الشاهد البوشيخي فأنت تفتح عينيك على مدى مساحة الأفق الرحب الذي يختزن عمق الرؤى وشمولية التطلعات صوب الحياة والإنسان.. صوب الأفكار الأصيلة المنبثقة من القرآن الكريم والسنة النبوية.
له كتابات بمجموعة من المنابر: آفاق، مجلة كلية الآداب بفاس، الهدى، مجلة المسلم المعاصر التي يصدرها المعهد العالي للفكر الإسلامي وبمجلة المشكاة.
من أبرز تلامذته الشيخ الدكتور فريد الأنصاري.
من مؤلفاته
* نظرات في المصطلح والمنهج
* نحو معجم تاريخي للمصطلحات القرآنية المعرفة
* القرآن الكريم طبيعته ووظيفته
* الهداية إلى بلوغ النهاية (أصل هذا الكتاب مجموعة رسائل علمية تحت إشراف الدكتور الشاهد البوشيخي)
* مصطلحات نقدية وبلاغية في كتاب البيان والتبيين للجاحظ
* مصطلحات النقد العربي لدى الشعراء الجاهليين والإسلاميين: قضايا ونماذج
* …
* ..
من مقالاته
* مفهوم الأمن في القرآن الكريم
* المنهج مشكلة أمتنا الأولى!
* مفهوم الحياة في القرآن الكريم
* المسلمون بين الشدائد والبشائر
* نظرات في مفهوم الحوار في القرآن الكريم
* مظاهر التكريم الإلهي لبني الإنسان
* الهُدى المنهاجي في القرآن الكريم
* الهوية الإسلامية في ضوء العولمة
* نظرات في المصطلح والمنهج
* المضامين التنموية للثقافة الإسلامية
* التعليم الشرعي ضرورة تنموية
* أولويات البحث العلمي في الدراسات القرآنية
* الإنسان، خُلُق وعمل
* مفهوم الحياة في القرآن الكريم
* المسلمون بين الشدائد والبشائر', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


