INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('محمد بن سعيد القحطاني', 'مؤلف', 'الدكتور محمد بن سعيد بن سالم القحطاني
حاصل على شهادة الدكتوراه من جامعة أم القرى عام ١٤٠٥ هـ - ١٩٨٤م
