INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('محمد علي الهاشمي', 'مؤلف', 'الدكتور محمد علي الهاشمي أديب ومؤلف إسلامي سوري
ولد في حلب ١٩٢٥، حصل على الإجازة من كلية الآداب وأيضا من كلية التربية جامعة دمشق ١٩٦٠، وحصل على (الماجستير ١٩٦٥ ثم الدكتوراة ١٩٧٠) من كلية الآداب جامعة القاهرة
درّس في كليتي الشريعة واللغة العربية لعدة كليات في المملكة العربية السعودية وحلب. له برنامج في إذاعة القران الكريم في المملكة العربية السعودية.
طبعت آلاف النسخ من مؤلفاته في دار البشائر الإسلامية: منها مفاخر القضاء الإسلامي كما يجليها الإسلام في الكتاب والسنة ووترجمت أشهر كتبه: (شخصية المسلم) و (شخصية المرأة المسلمة) و (المجتمع الإسلامي) إلى الإنجليزية والفرنسية والروسية والتركية والملايوية والأوردية والكردية.', NULL, '1383-01-01', '1388-01-01', NOW(), NOW())
