INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('مجدي الهلالي', 'مؤلف', 'الدكتور مجدي الهلالي
طبيب تحاليل طبية، وداعية مصري، من أعلام الدعوة الإسلامية والإخوان المسلمين بمصر، كان له دور فى العمل الطلابى أثناء دراسته الجامعية، اتجه إلى التأليف، فقدم عشرات الكتب فى الدعوة و التربية الإيمانية، والتى تهدف إلى ارتقاء الفرد بنفسه والتخلص من مثبطات الهمم، له العديد من الخطب والتسجيلات والمقالات فى مختلف الصحف والمواقع الالكترونية، شارك فى العديد من الندوات والمؤتمرات المحلية والدولية، عمل بالسعودية فأقام في المدينة المنورة فترة طويلة من عام ١٩٩٤م وحتى عام ٢٠٠٥م حيث الجوار الطيب المبارك الذي ساعده كثيرا في التأليف، وهو الآن مقيم في القاهرة. وما زال يمارس الدعوة والتربية.
من مؤلفاته
١. الإيمان أولاً - فكيف نبدأ به؟
٢. ظاهرة الضعف النفسي وسبل علاجها
٣. واجبات الشاب المسلم
٤. من فقه الأولويات في الإسلام
٥. أضواء على طريق الدعوة
٦. رسالة من غريق
٧. طوق النجاة
٨. فلنبدأ بأنفسنا
٩. هلموا إلى ربكم
١٠. رسالة إلى أخي في الله.
١١. تحقيق الوصال بين القلب والقرآن
١٢. أين المخرج فالصخرة أغلقت الغار
١٣. عودة الروح ويقظة الإيمان
١٤. التوازن التربوي
١٥. وماذا بعد؟
١٦. الجيل الموعود بالنصر والتمكين
١٧. كيف نغير ما بانفسنا
١٨. كيف نحب الله ونشتاق إليه
١٩. العودة إلى القرآن -لماذا وكيف
٢٠. إنه القرآن سر نهضتنا
٢١. حطم صنمك
٢٢. ركائز الدعوة
٢٣. حقيقة العبودية
٢٤. الطريق إلى الربانية
٢٥. الوعد الحق والثقة
٢٦. فلنبدأ بأنفسنا
٢٧. صور مرفوضة إحذرها أخي الداعية
٢٨. طريق الإصلاح .. أضواء على مفاهيم مختلطة
٢٩. مهلا أخي الداعية
٣٠. نظرات في التربية الإيمانية
٣١. ركائز الدعوة
٣٢. أيامًا معدودات
٣٣. الطوفان قادم .. الله أو الدمار
وكذلك مجموعة من الكتيبات منها:
١. حتى لا نخسر رمضان
٢. كيف نستفيد من رمضان
٣. الكنز المهجور', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


