INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('سامي القدومي', 'مؤلف', 'باحث في العلوم الشرعية، وحاصل على درجة الماجستير في الشريعة الإسلامية
الاهتمامات:
١ - أهدف إلى بيان دين الله - سبحانه وتعالى - بناء على الدليل من الكتاب والسنة الصحيحة
٢ - ألتزم ببيان درجة الحديث صحة وضعفاً.
٣ - أدعو إلى الأخذ بأقوال العلماء الأعلام، وعدم الخروج عن أقوالهم؛ لأن اتباع أهل العلم نور، واتباع الشذوذ شذوذ.
٤ - أهدف إلى تسهيل المعلومة؛ لتكون في متناول أكبر عدد من القرَّاء.
٥ - أدعو إلى نبذ التعصب إلى مذهب أو شيخ أو أي شيء يصرف طالب الحق عن الحق
للتواصل مع المؤلف
[email protected][email protected]
للاطلاع على كتب المؤلف
http://Samiwadi.blogspot.com', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
