INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('عبد الحميد البلالي', 'مؤلف', '* عبد الحميد جاسم أحمد الجاسم البلالي
* من مواليد ١٩٥٥ (قبلة) - الكويت.
* درس في الكلية الصناعية عام ١٩٧١ وذهب في بعثة علمية إلى بريطانيا وحصل على دبلوم بالهندسة الكهربائية من كلية «بورمث» عام ١٩٧٨ والبكالوريوس بالهندسة الإلكترونية من جامعة دايتون الأميركية عام ١٩٩٠.
* عمل مهندساً للكهرباء في شركة المباني الجاهزة ثم تدرج من مهندس إلى رئيس قسم للصيانة ومهندس تخطيط أول في شركة صناعة الكيماويات البترولية.
* مارس الخطابة في المساجد منذ أن كان طالبا في الجامعة وقدم برامج دعوية واجتماعية في التلفزيون والإذاعة.
* صحافي وكاتب، تنقل بين مجلة «المجتمع» و «القبس» و «الأنباء» و «الوسط» و «صوت الكويت» و «الرأي العام».
* رئيس مجلس إدارة جمعية بشائر الخير المتخصصة في علاج المدمنين.
* عضو في جمعية الإصلاح الاجتماعي واللجنة الوطنية للوقاية من المخدرات واتحاد الجمعيات العربية غير الحكومية لمكافحة المخدرات.
* عضو جمعية الصحفيين الكويتية، وعضو باللجنة الوطنية للوقاية من المخدرات منذ تشكيلها بالمرسوم الأميري رقم ٣٣/ ٨٩ بصفته عضواً من ذوي الرأي والخبرة والاختصاص ولا يزال، وعضو اتحاد الجمعيات العربية الغير حكومية لمكافحة المخدرات.
* شارك في العديد من المؤتمرات الخاصة بعلاج المدمنين من المخدرات على المستوى الخليجي والعربي والدولي.
* أصدر كتبا عدة في مجال مكافحة المخدرات وفي الانتاج العلمي بلغت ٣٧ كتابا وترجمت كتبه الى اللغات الانكليزية والفرنسية والاوردو والفارسية والماليزية والتركية والمالاوية.', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


