INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('أحمد بن يوسف الأهدل', 'مؤلف', '• من مواليد مكة المكرمة عام ١٩٧٠م
• درس وتخرج على أيدي مشايخ عظام بالمدرسة الصولتية والمسجد الحرام، ومنهم الشيخ عبدالله سعيد اللحجي، والشيخ إسماعيل عثمان الزين، والشيخ أحمد جابر جبران، والشيخ السيد محمد علوي المالكي، والشيخ عبد الفتاح راوه، والشيح طه البركاتي، رحمهم الله تعالى. والشيخ السيد أحمد الرقيمي، والحبيب عمر الجيلاني، والشيخ السهيلي، والشيخ أيوب أبكر أسد الأهدل، والشيخ سيف الرحمن، والشيخ علاء الدين الأفغاني، والشيخ ماجد رحمت الله، والدكتور هاشم مهدي، والدكتور قاسم الأهدل، والشيخ سعيد عناية الله، عافاهم الله تعالى وغيرهم.', 'المذهب المالكي', NULL, NULL, NOW(), NOW())
