INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('بتول جندية', 'مؤلف', '• بتول أحمد جندية سورية من مواليد مدينة حلب عام ١٩٧٤م
• تعمل مدرسة في كلية الآداب والعلوم الإنسانية، جامعة حلب ـ سورية، قسم اللغة العربية، في اختصاص نظرية الأدب.
• تخرجت عام ١٩٩٦م من كلية الآداب والعلوم الإنسانية ـ قسم اللغة العربية ـ جامعة حلب، بتقدير جيد جدًا.
• حصلت على شهادة الباسل للتفوق الدراسي مرتين، ونالت في التخرج شهادة الباسل للخريج المتفوق.
• حصلت على شهادة الدبلوم في الدراسات الأدبية بتقدير جيد جدًا عام ١٩٩٧م.
• حصلت على درجة الماجستير في اللغة العربية في اختصاص نظرية الأدب بتقدير ممتاز عام ٢٠٠٥م، عن بحث بعنوان: «وظيفة • الخطاب الشعري عند العرب في القرن الثالث الهجري».
• حصلت على درجة الدكتوراه في اللغة العربية في اختصاص نظرية الأدب بتقدير ممتاز عام ٢٠١٠م، عن بحث بعنوان: «مفهوم الوظيفة ومستوياتها في الشعر العربي الحديث في القرن العشرين»
البحوث العلمية والكتب المطبوعة:
• بحث محكم في مجلة بحوث جامعة حلب، بعنوان: «الدرس الأدبي بين الواقع والتصور».
• بحث مقدم إلى أعمال مؤتمر جامعة اليرموك عن «تداخل الأنواع الأدبية»، بعنوان: «الأنواع الأدبية التراثية ـ رؤية حضارية».
• بحث محكم في مجلة بحوث جامعة حلب، بعنوان: «الدور الحضاري للشعر العربي المعاصر ـ مدرسة الأصالة ومدرسة الحداثة».
• بحث محكم في مجلة بحوث جامعة حلب، بعنوان: «الانحطاط وأزمة الفعالية ـ تنقيب عن العلل والآثار».
• بحث محكم في مجلة بحوث جامعة حلب، بعنوان: «تخلّق النوع الأدبي وتطوره بين إرادة الفرد وسلطة الجماعة».
• بحث محكم في مجلة بحوث جامعة البعث، بعنوان: «طبيعة الخيال الشعري وضوابطه بين التراث والحداثة».
البريد الالكتروني: [email protected][email protected]', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


INSERT INTO authors 
(full_name, author_role, biography, madhhab, birth_date, death_date, created_at, updated_at) 
VALUES ('أحمد بن ناصر الحمد', 'مؤلف', 'أحمد بن ناصر بن محمد الحمد. أستاذ العقيدة بجامعة أم القرى
له عدة مؤلفات في العقيدة منها:
١ - صفة الرؤية. وقد طبع بمركز البحث العلمي وإحياء التراث الإسلامي بالجامعة.
٢ - ابن حزم وموقفه من الإلهيات، وهو من أحسن كتبه إن لم يكن أحسنها، وفيه جهد كبير في البحث والتوثيق والنقد والتحليل. وقد طبع بمركز البحث العلمي بالجامعة.
٣ - السحر بين الحقيقة والخيال؛ وهو مطبوع متداول.
٤ - العقيدة نبع التربية؛ وهو مطبوع أيضا.
٥ - تحقيق كتاب الدرة لابن حزم، وقد شاركه في التحقيق الدكتور سعيد القزقي.
٦ - النبي والرسول؛ وهو كتاب مفرد لبيان الفرق بين النبي والرسول.', NULL, NULL, NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
    biography = COALESCE(VALUES(biography), biography),
    madhhab = COALESCE(VALUES(madhhab), madhhab),
    birth_date = COALESCE(VALUES(birth_date), birth_date),
    death_date = COALESCE(VALUES(death_date), death_date),
    updated_at = NOW();


